-- Brings the V12 schema (108 tables) to the final release schema (140 tables).
-- 1. Adds columns and replaces constraints on existing tables, then backfills existing rows,
--    then applies NOT NULL (add column, backfill, NOT NULL order).
-- 2. Creates the 32 new tables (the 8 visit request tables and the 24 added later) in dependency order.
-- 3. Adds the constraints that reference new tables, then all COMMENT statements.
-- V12 and earlier are not modified. Business seed data (price schedules, trial events,
-- retention rules) is not inserted here; it lives in separate seed files.
-- Generated by script from the final schema definition; do not edit by hand.

