-- ---------------------------------------------------------------------
-- 1. Existing tables: backfill existing rows
-- ---------------------------------------------------------------------
-- Revocation date if revoked, otherwise the valid_until date, plus 90 days.
-- 90 mirrors the draft GUEST_INPUT_AFTER_APPROVAL_END rule; the rule table has no rows yet,
-- so the value is fixed here. A date already in the past is kept; the retention sweep handles it.
UPDATE property_access_approval SET retention_until =
  ((COALESCE(revoked_at, valid_until) AT TIME ZONE 'Asia/Seoul')::date + 90) WHERE retention_until IS NULL;

-- Rows recorded before this column existed get the dedicated UNKNOWN value.
UPDATE terms_agreement SET consent_path = 'UNKNOWN' WHERE consent_path IS NULL;

-- Owning office of the candidate property.
UPDATE visit_candidate_property vcp SET property_office_id = p.office_id
  FROM property p WHERE p.id = vcp.property_id AND vcp.property_office_id IS NULL;

-- Link expiry date plus 90 days. If the coordination already ended, the later of that date and
-- the coordination end date (cancel date if cancelled, otherwise period end) plus 90 days.
UPDATE visit_customer_link l SET retention_until = GREATEST(
    ((l.expires_at AT TIME ZONE 'Asia/Seoul')::date + 90),
    COALESCE((SELECT CASE WHEN vc.status IN ('VISIT_COMPLETED','VISIT_INCOMPLETE','CANCELLED')
                          THEN COALESCE((vc.cancelled_at AT TIME ZONE 'Asia/Seoul')::date, vc.period_end_date) + 90 END
               FROM visit_coordination vc WHERE vc.id = l.coordination_id), DATE '0001-01-01'))
  WHERE l.retention_until IS NULL;

-- approver_phone_hash stays NULL for existing rows. A one-off backend job computes it from the
-- phone number with the application HMAC key, which SQL migrations do not hold.
-- All other new columns on existing tables take their column default or NULL.

ALTER TABLE property_access_approval ALTER COLUMN retention_until SET NOT NULL;
ALTER TABLE terms_agreement ALTER COLUMN consent_path SET NOT NULL;
ALTER TABLE visit_candidate_property ALTER COLUMN property_office_id SET NOT NULL;
ALTER TABLE visit_customer_link ALTER COLUMN retention_until SET NOT NULL;

