ALTER TABLE property_access_approval ADD CONSTRAINT uq_property_access_approval_id_role UNIQUE (id, approval_role);
ALTER TABLE visit_candidate_property ADD CONSTRAINT uq_visit_candidate_property_id_coord_property UNIQUE (id, coordination_id, property_id);
ALTER TABLE visit_schedule_item ADD CONSTRAINT uq_visit_schedule_item_confirmed_request UNIQUE (id, confirmed_request_id);
ALTER TABLE trial_event ADD CONSTRAINT ex_trial_event_general_window EXCLUDE USING gist (tstzrange(starts_at, ends_at, '[)'::text) WITH &&) WHERE ((((audience)::text = 'GENERAL'::text) AND (status IN ('SCHEDULED', 'ACTIVE'))));
ALTER TABLE billing_invoice ADD CONSTRAINT billing_invoice_supply_amount_check CHECK ((supply_amount >= 0));
ALTER TABLE billing_invoice ADD CONSTRAINT billing_invoice_vat_amount_check CHECK ((vat_amount >= 0));
ALTER TABLE billing_invoice ADD CONSTRAINT billing_invoice_vat_rate_bp_snapshot_check CHECK ((vat_rate_bp_snapshot >= 0));
ALTER TABLE billing_invoice ADD CONSTRAINT ck_billing_invoice_tax_split CHECK ((((supply_amount IS NULL) AND (vat_amount IS NULL) AND (vat_rate_bp_snapshot IS NULL)) OR ((supply_amount IS NOT NULL) AND (vat_amount IS NOT NULL) AND (vat_rate_bp_snapshot IS NOT NULL) AND ((supply_amount + vat_amount) = vat_included_amount))));
ALTER TABLE customer ADD CONSTRAINT customer_processing_basis_check CHECK ((processing_basis IN ('CONSENT', 'CONTRACT_PERFORMANCE', 'LEGAL_OBLIGATION', 'LEGITIMATE_INTEREST', 'OTHER_LAW', 'UNSPECIFIED')));
ALTER TABLE office_membership ADD CONSTRAINT office_membership_withdrawn_alias_no_check CHECK ((withdrawn_alias_no > 0));
ALTER TABLE price_schedule ADD CONSTRAINT price_schedule_audience_check CHECK ((audience IN ('STANDARD', 'START_CUSTOMER')));
ALTER TABLE privacy_request ADD CONSTRAINT privacy_request_handler_type_check CHECK ((handler_type IN ('SAIRO', 'OFFICE')));
ALTER TABLE property_access_approval ADD CONSTRAINT ck_property_access_approval_anonymized CHECK ((((anonymized_at IS NULL) = (approver_name IS NOT NULL)) AND ((anonymized_at IS NULL) OR ((approver_phone IS NULL) AND (approver_phone_hash IS NULL) AND ((revoked_at IS NOT NULL) OR (anonymized_at >= valid_until))))));
ALTER TABLE property_access_approval ADD CONSTRAINT ck_property_access_approval_phone CHECK ((((source)::text = 'PROXY'::text) OR (approver_phone IS NOT NULL) OR (anonymized_at IS NOT NULL)));
ALTER TABLE property_access_approval ADD CONSTRAINT property_access_approval_approval_role_check CHECK ((approval_role IN ('PRIMARY', 'CO_APPROVER')));
ALTER TABLE subscription ADD CONSTRAINT subscription_check CHECK (((trial_started_at IS NULL) OR (trial_ends_at > trial_started_at)));
ALTER TABLE terms_agreement ADD CONSTRAINT ck_terms_agreement_consent_path CHECK ((consent_path IN ('SIGNUP_EMAIL', 'SIGNUP_KAKAO', 'ACCOUNT_SETTINGS', 'RECONSENT', 'UNSUBSCRIBE_LINK', 'PURCHASE_CONSENT', 'CARD_REGISTRATION', 'UNKNOWN')));
ALTER TABLE terms_agreement ADD CONSTRAINT ck_terms_agreement_office_scope CHECK (((consent_path NOT IN ('PURCHASE_CONSENT', 'CARD_REGISTRATION')) OR (office_id IS NOT NULL)));
ALTER TABLE terms_catalog ADD CONSTRAINT ck_terms_catalog_display_context CHECK ((display_context IN ('SIGNUP', 'CARD_REGISTRATION', 'LINK_NOTICE', 'PURCHASE')));
ALTER TABLE terms_catalog ADD CONSTRAINT ck_terms_catalog_hash_pair CHECK (((last_hash_checked_at IS NULL) = (last_hash_check_result IS NULL)));
ALTER TABLE terms_catalog ADD CONSTRAINT ck_terms_catalog_hash_result CHECK (((last_hash_check_result IS NULL) OR (last_hash_check_result IN ('MATCH', 'MISMATCH', 'ERROR'))));
ALTER TABLE terms_catalog ADD CONSTRAINT ck_terms_catalog_reconsent_scope CHECK (((NOT reconsent_required) OR (category IN ('TERMS', 'SEPARATE_CONSENT'))));
ALTER TABLE trial_event ADD CONSTRAINT ck_trial_event_fixed_free_end CHECK ((((free_end_mode)::text = 'FIXED_END'::text) = (fixed_free_ends_at IS NOT NULL)));
ALTER TABLE trial_event ADD CONSTRAINT ck_trial_event_max_offices_audience CHECK (((max_offices IS NULL) OR ((audience)::text = 'START_CUSTOMER'::text)));
ALTER TABLE trial_event ADD CONSTRAINT trial_event_audience_check CHECK ((audience IN ('GENERAL', 'START_CUSTOMER')));
ALTER TABLE trial_event ADD CONSTRAINT trial_event_free_end_mode_check CHECK ((free_end_mode IN ('DURATION', 'FIXED_END')));
ALTER TABLE trial_event ADD CONSTRAINT trial_event_max_offices_check CHECK (((max_offices IS NULL) OR (max_offices >= 1)));
ALTER TABLE visit_coordination ADD CONSTRAINT visit_coordination_status_check CHECK ((status IN ('TIME_COLLECTING', 'COORDINATABLE', 'FINAL_CONFIRMATION_REQUIRED', 'APPLYING', 'CONFIRMED', 'RESCHEDULE_REQUIRED', 'VISIT_COMPLETED', 'VISIT_INCOMPLETE', 'CANCELLED')));
ALTER TABLE visit_coordination_status_history ADD CONSTRAINT visit_coordination_status_history_from_status_check CHECK ((from_status IN ('TIME_COLLECTING', 'COORDINATABLE', 'FINAL_CONFIRMATION_REQUIRED', 'APPLYING', 'CONFIRMED', 'RESCHEDULE_REQUIRED', 'VISIT_COMPLETED', 'VISIT_INCOMPLETE', 'CANCELLED')));
ALTER TABLE visit_coordination_status_history ADD CONSTRAINT visit_coordination_status_history_to_status_check CHECK ((to_status IN ('TIME_COLLECTING', 'COORDINATABLE', 'FINAL_CONFIRMATION_REQUIRED', 'APPLYING', 'CONFIRMED', 'RESCHEDULE_REQUIRED', 'VISIT_COMPLETED', 'VISIT_INCOMPLETE', 'CANCELLED')));
ALTER TABLE visit_schedule_item ADD CONSTRAINT visit_schedule_item_check2 CHECK ((((travel_starts_at IS NULL) AND (travel_ends_at IS NULL)) OR ((travel_starts_at IS NOT NULL) AND (travel_ends_at IS NOT NULL) AND (travel_ends_at >= travel_starts_at))));
ALTER TABLE visit_schedule_item_result_history ADD CONSTRAINT visit_schedule_item_result_history_cancel_reason_code_check CHECK (((cancel_reason_code IS NULL) OR (cancel_reason_code IN ('USER_CANCEL', 'CHANGE_REPLACED', 'APPROVER_REASON', 'CUSTOMER_REASON', 'OTHER'))));
ALTER TABLE visit_schedule_item_result_history ADD CONSTRAINT visit_schedule_item_result_history_check2 CHECK (((cancel_reason_code IS NULL) OR ((result)::text = 'CANCELLED'::text)));
ALTER TABLE billing_invoice ADD CONSTRAINT fk_billing_invoice_supplier_info_version FOREIGN KEY (supplier_info_version) REFERENCES company_service_info(version_no);
