CREATE INDEX ix_visit_candidate_property_property ON visit_candidate_property USING btree (property_id);
CREATE INDEX ix_visit_schedule_item_confirmed_request ON visit_schedule_item USING btree (confirmed_request_id) WHERE (confirmed_request_id IS NOT NULL);

-- ---------------------------------------------------------------------
-- 2. New tables (32)
-- ---------------------------------------------------------------------
CREATE TABLE visit_approver_condition (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id                  BIGINT NOT NULL REFERENCES property_access_approval(id),
    version_no                   INT NOT NULL,
    status                       VARCHAR(12) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUPERSEDED')),
    applies_from                 TIMESTAMPTZ NOT NULL,
    applies_until                TIMESTAMPTZ NOT NULL,
    max_visits_per_day           INT CHECK (max_visits_per_day IS NULL OR max_visits_per_day >= 1),
    min_gap_minutes              INT CHECK (min_gap_minutes IS NULL OR min_gap_minutes >= 0),
    min_lead_minutes             INT CHECK (min_lead_minutes IS NULL OR min_lead_minutes >= 0),
    single_visit_max_minutes     INT CHECK (single_visit_max_minutes IS NULL OR single_visit_max_minutes >= 1),
    grouping_preference          VARCHAR(12) CHECK (grouping_preference IS NULL OR grouping_preference IN ('CONSECUTIVE','SPREAD')),
    source                       VARCHAR(10) NOT NULL DEFAULT 'DIRECT' CHECK (source IN ('DIRECT','PROXY')),
    recorded_by_membership_id    BIGINT REFERENCES office_membership(id),
    registered_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
    superseded_at                TIMESTAMPTZ,
    approval_role                VARCHAR(12) NOT NULL DEFAULT 'PRIMARY' CHECK (approval_role = 'PRIMARY'),
    entered_by_profile_id        BIGINT,
    UNIQUE (approval_id, version_no),
    UNIQUE (id, approval_id),
    CONSTRAINT ck_visit_approver_condition_period CHECK (applies_until > applies_from),
    CONSTRAINT ck_visit_approver_condition_proxy CHECK (recorded_by_membership_id IS NULL OR source = 'PROXY'),
    CONSTRAINT ck_visit_approver_condition_superseded CHECK ((superseded_at IS NOT NULL) = (status = 'SUPERSEDED')),
    CONSTRAINT fk_visit_approver_condition_primary FOREIGN KEY (approval_id, approval_role) REFERENCES property_access_approval (id, approval_role),
    CONSTRAINT ck_visit_approver_condition_profile CHECK (entered_by_profile_id IS NULL OR source = 'DIRECT')
);

CREATE UNIQUE INDEX uq_visit_approver_condition_active ON visit_approver_condition (approval_id) WHERE status = 'ACTIVE';

CREATE TABLE visit_approver_condition_window (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    condition_id                 BIGINT NOT NULL REFERENCES visit_approver_condition(id),
    window_type                  VARCHAR(10) NOT NULL CHECK (window_type IN ('WEEKDAY','DATE')),
    weekday                      SMALLINT,
    window_date                  DATE,
    starts_time                  TIME NOT NULL,
    ends_time                    TIME NOT NULL,
    is_exception                 BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT ck_visit_approver_condition_window_kind CHECK ((window_type = 'WEEKDAY' AND weekday IS NOT NULL AND weekday BETWEEN 1 AND 7 AND window_date IS NULL) OR (window_type = 'DATE' AND window_date IS NOT NULL AND weekday IS NULL)),
    CONSTRAINT ck_visit_approver_condition_window_time CHECK (ends_time > starts_time)
);

CREATE TABLE visit_approver_property_link (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id                  BIGINT NOT NULL REFERENCES property_access_approval(id),
    token_hash                   CHAR(64) UNIQUE,
    issued_by_membership_id      BIGINT NOT NULL REFERENCES office_membership(id),
    issued_at                    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at                   TIMESTAMPTZ NOT NULL,
    revoked_at                   TIMESTAMPTZ,
    last_accessed_at             TIMESTAMPTZ,
    retention_until              DATE NOT NULL,
    anonymized_at                TIMESTAMPTZ,
    CONSTRAINT ck_visit_approver_property_link_anonymized CHECK ((anonymized_at IS NULL) = (token_hash IS NOT NULL) AND (anonymized_at IS NULL OR (revoked_at IS NOT NULL AND last_accessed_at IS NULL))),
    CONSTRAINT uq_visit_approver_property_link_approval UNIQUE (id, approval_id)
);

CREATE UNIQUE INDEX uq_visit_approver_property_link_active ON visit_approver_property_link (approval_id) WHERE revoked_at IS NULL;

CREATE TABLE visit_request (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    condition_id                 BIGINT NOT NULL,
    approval_id                  BIGINT NOT NULL,
    property_id                  BIGINT NOT NULL,
    applicant_office_id          BIGINT NOT NULL,
    applicant_membership_id      BIGINT NOT NULL,
    coordination_id              BIGINT NOT NULL,
    candidate_property_id        BIGINT NOT NULL,
    request_kind                 VARCHAR(10) NOT NULL DEFAULT 'NEW' CHECK (request_kind IN ('NEW','CHANGE')),
    replaces_schedule_item_id    BIGINT REFERENCES visit_schedule_item(id),
    requested_start_at           TIMESTAMPTZ NOT NULL,
    requested_end_at             TIMESTAMPTZ NOT NULL,
    expected_duration_minutes    INT NOT NULL CHECK (expected_duration_minutes >= 1),
    party_size                   INT CHECK (party_size IS NULL OR party_size >= 1),
    request_note                 TEXT,
    status                       VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SELECTED','CONFIRMED','REVALIDATION_FAILED','TIME_CLOSED','EXPIRED','WITHDRAWN','CANCELLED')),
    status_reason                TEXT,
    submitted_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
    closed_at                    TIMESTAMPTZ,
    updated_at                   TIMESTAMPTZ NOT NULL DEFAULT now(),
    version                      BIGINT NOT NULL DEFAULT 1,
    property_office_id           BIGINT NOT NULL,
    access_grant_id              BIGINT,
    FOREIGN KEY (applicant_membership_id, applicant_office_id) REFERENCES office_membership (id, office_id),
    FOREIGN KEY (approval_id, property_id) REFERENCES property_access_approval (id, property_id),
    FOREIGN KEY (condition_id, approval_id) REFERENCES visit_approver_condition (id, approval_id),
    FOREIGN KEY (coordination_id, applicant_office_id) REFERENCES visit_coordination (id, office_id),
    CONSTRAINT ck_visit_request_replaces CHECK (replaces_schedule_item_id IS NULL OR request_kind = 'CHANGE'),
    CONSTRAINT ck_visit_request_period CHECK (requested_end_at > requested_start_at),
    CONSTRAINT ck_visit_request_closed CHECK ((closed_at IS NOT NULL) = (status IN ('REVALIDATION_FAILED','TIME_CLOSED','EXPIRED','WITHDRAWN','CANCELLED'))),
    CONSTRAINT fk_visit_request_property FOREIGN KEY (property_id, property_office_id) REFERENCES property (id, office_id),
    CONSTRAINT ck_visit_request_cross_office CHECK ((applicant_office_id = property_office_id) = (access_grant_id IS NULL)),
    CONSTRAINT fk_visit_request_candidate FOREIGN KEY (candidate_property_id, coordination_id, property_id) REFERENCES visit_candidate_property (id, coordination_id, property_id),
    CONSTRAINT uq_visit_request_review_ref UNIQUE (id, approval_id, applicant_membership_id, applicant_office_id)
);

CREATE UNIQUE INDEX uq_visit_request_active_candidate ON visit_request (candidate_property_id) WHERE status IN ('PENDING','SELECTED');

CREATE INDEX ix_visit_request_property_status ON visit_request (property_id, status);

CREATE INDEX ix_visit_request_access_grant ON visit_request (access_grant_id) WHERE access_grant_id IS NOT NULL;

CREATE INDEX ix_visit_request_applicant_membership ON visit_request (applicant_membership_id);

CREATE INDEX ix_visit_request_applicant_open ON visit_request (applicant_membership_id) WHERE status IN ('PENDING','SELECTED');

CREATE INDEX ix_visit_request_approval_open ON visit_request (approval_id) WHERE status IN ('PENDING','SELECTED');

CREATE TABLE visit_request_status_history (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id                   BIGINT NOT NULL REFERENCES visit_request(id),
    from_status                  VARCHAR(24) CHECK (from_status IS NULL OR from_status IN ('PENDING','SELECTED','CONFIRMED','REVALIDATION_FAILED','TIME_CLOSED','EXPIRED','WITHDRAWN','CANCELLED')),
    to_status                    VARCHAR(24) NOT NULL CHECK (to_status IN ('PENDING','SELECTED','CONFIRMED','REVALIDATION_FAILED','TIME_CLOSED','EXPIRED','WITHDRAWN','CANCELLED')),
    source                       VARCHAR(10) NOT NULL CHECK (source IN ('BROKER','APPROVER','SYSTEM')),
    actor_membership_id          BIGINT REFERENCES office_membership(id),
    reason                       TEXT,
    effective_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at                   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_visit_request_status_history_actor CHECK (actor_membership_id IS NULL OR source = 'BROKER')
);

CREATE TABLE visit_request_selection (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id                   BIGINT NOT NULL REFERENCES visit_request(id),
    approver_link_id             BIGINT REFERENCES visit_approver_property_link(id),
    compared_request_count       INT NOT NULL CHECK (compared_request_count >= 1),
    selection_note               TEXT,
    selected_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    approver_profile_id          BIGINT,
    UNIQUE (id, request_id),
    CONSTRAINT ck_visit_request_selection_actor CHECK ((approver_link_id IS NOT NULL) <> (approver_profile_id IS NOT NULL))
);

CREATE TABLE visit_request_revalidation (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id                   BIGINT NOT NULL REFERENCES visit_request(id),
    selection_id                 BIGINT,
    condition_id                 BIGINT NOT NULL REFERENCES visit_approver_condition(id),
    result                       VARCHAR(10) NOT NULL CHECK (result IN ('PASSED','FAILED')),
    failure_code                 VARCHAR(30) CHECK (failure_code IS NULL OR failure_code IN ('CONDITION_EXPIRED','CONDITION_CHANGED','NO_PERMISSION','WINDOW_MISMATCH','MAX_VISITS_PER_DAY','MIN_GAP','MIN_LEAD','SINGLE_VISIT_MAX','CUSTOMER_CONFLICT','BROKER_CONFLICT','PROPERTY_CONFLICT','TRAVEL_CONFLICT')),
    failure_detail               TEXT,
    checked_at                   TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (selection_id, request_id) REFERENCES visit_request_selection (id, request_id),
    CONSTRAINT ck_visit_request_revalidation_failure CHECK (failure_code IS NULL OR result = 'FAILED')
);

CREATE TABLE visit_request_notice (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id                   BIGINT NOT NULL REFERENCES visit_request(id),
    recipient_membership_id      BIGINT NOT NULL REFERENCES office_membership(id),
    notice_type                  VARCHAR(30) NOT NULL CHECK (notice_type IN ('TIME_CLOSED','SELECTED','REVALIDATION_FAILED','CONFIRMED','CONDITION_CHANGE_IMPACT','REAPPROVAL_REQUESTED','SLOT_REOPENED','GRANT_REVOKED')),
    channel                      VARCHAR(20),
    created_at                   TIMESTAMPTZ NOT NULL DEFAULT now(),
    read_at                      TIMESTAMPTZ
);

CREATE TABLE billing_start_customer_agreement (
    id                                    BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    office_id                             BIGINT       NOT NULL REFERENCES office(id),
    trial_event_id                        BIGINT       NOT NULL REFERENCES trial_event(id),
    price_schedule_id                     BIGINT       NOT NULL REFERENCES price_schedule(id),
    price_starts_at                       TIMESTAMPTZ  NOT NULL,
    price_ends_at                         TIMESTAMPTZ  NOT NULL,
    status                                VARCHAR(12)  NOT NULL DEFAULT 'REGISTERED' CHECK (status IN ('REGISTERED','APPROVED','REVOKED')),
    contracted_on                         DATE         NOT NULL,
    contract_reference                    VARCHAR(100) NOT NULL,
    weekly_use_confirmed                  BOOLEAN      NOT NULL,
    monthly_interview_confirmed           BOOLEAN      NOT NULL,
    case_publication_consent              BOOLEAN      NOT NULL DEFAULT false,
    agreement_text_version                VARCHAR(20)  NOT NULL,
    owner_acknowledged_at                 TIMESTAMPTZ,
    owner_acknowledged_by_membership_id   BIGINT       REFERENCES office_membership(id),
    created_by_operator_id                BIGINT       NOT NULL REFERENCES operator_account(id),
    created_at                            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    approved_by_operator_id               BIGINT       REFERENCES operator_account(id),
    approved_at                           TIMESTAMPTZ,
    revoked_by_operator_id                BIGINT       REFERENCES operator_account(id),
    revoked_at                            TIMESTAMPTZ,
    revoke_reason                         TEXT,
    updated_at                            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                               BIGINT       NOT NULL DEFAULT 1 CHECK (version > 0),
    CONSTRAINT ck_billing_sca_price_period CHECK (price_ends_at > price_starts_at),
    CONSTRAINT ck_billing_sca_conditions CHECK (weekly_use_confirmed AND monthly_interview_confirmed),
    CONSTRAINT ck_billing_sca_maker_checker CHECK (approved_by_operator_id IS NULL OR approved_by_operator_id <> created_by_operator_id),
    CONSTRAINT ck_billing_sca_approval_pair CHECK ((approved_at IS NULL) = (approved_by_operator_id IS NULL)),
    CONSTRAINT ck_billing_sca_approved_status CHECK (status <> 'APPROVED' OR approved_at IS NOT NULL),
    CONSTRAINT ck_billing_sca_revoked CHECK ((status = 'REVOKED') = (revoked_at IS NOT NULL AND revoked_by_operator_id IS NOT NULL AND revoke_reason IS NOT NULL)),
    CONSTRAINT ck_billing_sca_ack_pair CHECK ((owner_acknowledged_at IS NULL) = (owner_acknowledged_by_membership_id IS NULL)),
    CONSTRAINT ck_billing_sca_ack_after_approval CHECK (owner_acknowledged_at IS NULL OR approved_at IS NOT NULL)
);

CREATE UNIQUE INDEX uq_billing_sca_office_open
    ON billing_start_customer_agreement (office_id)
    WHERE status IN ('REGISTERED','APPROVED');

CREATE INDEX ix_billing_sca_event_status
    ON billing_start_customer_agreement (trial_event_id, status);

CREATE TABLE pricing_change_notice (
    id                          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    office_id                   BIGINT       NOT NULL REFERENCES office(id),
    subscription_id             BIGINT       NOT NULL REFERENCES subscription(id),
    from_price_schedule_id      BIGINT       NOT NULL REFERENCES price_schedule(id),
    to_price_schedule_id        BIGINT       NOT NULL REFERENCES price_schedule(id),
    change_kind                 VARCHAR(12)  NOT NULL CHECK (change_kind IN ('INCREASE','NON_INCREASE')),
    member_count_snapshot       INT          NOT NULL CHECK (member_count_snapshot > 0),
    current_amount_incl_vat     BIGINT       NOT NULL CHECK (current_amount_incl_vat >= 0),
    new_amount_incl_vat         BIGINT       NOT NULL CHECK (new_amount_incl_vat >= 0),
    notified_at                 TIMESTAMPTZ  NOT NULL,
    effective_at                TIMESTAMPTZ  NOT NULL,
    applies_from_period_start   TIMESTAMPTZ  NOT NULL,
    response_due_at             TIMESTAMPTZ  NOT NULL,
    notification_id             BIGINT       REFERENCES notification(id),
    decision                    VARCHAR(20)  NOT NULL DEFAULT 'PENDING' CHECK (decision IN ('PENDING','AGREED','DECLINED','NOT_REQUIRED','ENDED_NO_CONSENT')),
    decided_at                  TIMESTAMPTZ,
    decided_by_membership_id    BIGINT       REFERENCES office_membership(id),
    purchase_consent_id         BIGINT       REFERENCES subscription_purchase_consent(id),
    created_at                  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_pricing_notice_subscription_schedule UNIQUE (subscription_id, to_price_schedule_id),
    CONSTRAINT ck_pricing_notice_distinct CHECK (from_price_schedule_id <> to_price_schedule_id),
    CONSTRAINT ck_pricing_notice_kind_amount CHECK ((change_kind = 'INCREASE') = (new_amount_incl_vat > current_amount_incl_vat)),
    CONSTRAINT ck_pricing_notice_increase_period CHECK (change_kind <> 'INCREASE' OR effective_at >= notified_at + interval '30 days'),
    CONSTRAINT ck_pricing_notice_apply_after_effective CHECK (applies_from_period_start >= effective_at),
    CONSTRAINT ck_pricing_notice_due CHECK (response_due_at <= applies_from_period_start),
    CONSTRAINT ck_pricing_notice_not_required CHECK ((decision = 'NOT_REQUIRED') = (change_kind = 'NON_INCREASE')),
    CONSTRAINT ck_pricing_notice_decided_at CHECK ((decision IN ('PENDING','NOT_REQUIRED')) = (decided_at IS NULL)),
    CONSTRAINT ck_pricing_notice_decided_by CHECK ((decision IN ('AGREED','DECLINED')) = (decided_by_membership_id IS NOT NULL)),
    CONSTRAINT ck_pricing_notice_agreed_consent CHECK ((decision = 'AGREED') = (purchase_consent_id IS NOT NULL))
);

CREATE INDEX ix_pricing_notice_pending_due
    ON pricing_change_notice (response_due_at)
    WHERE decision = 'PENDING';

CREATE INDEX ix_pricing_notice_office
    ON pricing_change_notice (office_id, created_at DESC);

CREATE TABLE approver_profile (
    id             BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    phone_hash     CHAR(64)    UNIQUE,
    phone_last4    CHAR(4),
    status         VARCHAR(8)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','CLOSED')),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at  TIMESTAMPTZ,
    closed_at      TIMESTAMPTZ,
    close_source   VARCHAR(10) CHECK (close_source IN ('SELF','OPERATOR')),
    version        BIGINT      NOT NULL DEFAULT 1 CHECK (version > 0),
    CONSTRAINT ck_approver_profile_active CHECK (status <> 'ACTIVE' OR (phone_hash IS NOT NULL AND phone_last4 IS NOT NULL AND closed_at IS NULL AND close_source IS NULL)),
    CONSTRAINT ck_approver_profile_closed CHECK (status <> 'CLOSED' OR (phone_hash IS NULL AND phone_last4 IS NULL AND closed_at IS NOT NULL AND close_source IS NOT NULL))
);

CREATE TABLE approver_profile_approval (
    id           BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id   BIGINT      NOT NULL REFERENCES approver_profile(id),
    approval_id  BIGINT      NOT NULL REFERENCES property_access_approval(id),
    status       VARCHAR(16) NOT NULL CHECK (status IN ('PENDING_CONFIRM','LINKED','REJECTED','UNLINKED')),
    linked_via   VARCHAR(12) NOT NULL CHECK (linked_via IN ('LINK_TOKEN','PHONE_MATCH')),
    proposed_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    decided_at   TIMESTAMPTZ,
    unlinked_at  TIMESTAMPTZ,
    UNIQUE (profile_id, approval_id),
    CONSTRAINT ck_approver_profile_approval_times CHECK (
        (status = 'PENDING_CONFIRM' AND decided_at IS NULL     AND unlinked_at IS NULL)
     OR (status = 'LINKED'          AND decided_at IS NOT NULL AND unlinked_at IS NULL)
     OR (status = 'REJECTED'        AND decided_at IS NOT NULL AND unlinked_at IS NULL)
     OR (status = 'UNLINKED'        AND decided_at IS NOT NULL AND unlinked_at IS NOT NULL)),
    CONSTRAINT ck_approver_profile_approval_token CHECK (linked_via <> 'LINK_TOKEN' OR status <> 'PENDING_CONFIRM')
);

CREATE UNIQUE INDEX uq_approver_profile_approval_linked ON approver_profile_approval (approval_id) WHERE status = 'LINKED';

CREATE INDEX ix_approver_profile_approval_profile ON approver_profile_approval (profile_id, status);

CREATE TABLE approver_condition_bulk_batch (
    id                      BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id              BIGINT      NOT NULL REFERENCES approver_profile(id),
    requested_count         INT         NOT NULL CHECK (requested_count BETWEEN 1 AND 20),
    applied_count           INT         NOT NULL DEFAULT 0 CHECK (applied_count >= 0),
    needs_impact_ack_count  INT         NOT NULL DEFAULT 0 CHECK (needs_impact_ack_count >= 0),
    failed_count            INT         NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at            TIMESTAMPTZ,
    CONSTRAINT ck_approver_condition_bulk_batch_total CHECK (applied_count + needs_impact_ack_count + failed_count <= requested_count),
    CONSTRAINT ck_approver_condition_bulk_batch_complete CHECK (completed_at IS NULL OR applied_count + needs_impact_ack_count + failed_count = requested_count)
);

CREATE TABLE approver_condition_bulk_item (
    id                   BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id             BIGINT      NOT NULL REFERENCES approver_condition_bulk_batch(id),
    approval_id          BIGINT      NOT NULL REFERENCES property_access_approval(id),
    result               VARCHAR(18) NOT NULL CHECK (result IN ('APPLIED','NEEDS_IMPACT_ACK','FAILED')),
    condition_id         BIGINT,
    failure_code         VARCHAR(30) CHECK (failure_code IS NULL OR failure_code IN ('NOT_LINKED','NOT_PRIMARY','APPROVAL_INACTIVE','OFFICE_RESTRICTED','INVALID_CONDITION')),
    affected_item_count  INT         NOT NULL DEFAULT 0 CHECK (affected_item_count >= 0),
    UNIQUE (batch_id, approval_id),
    FOREIGN KEY (condition_id, approval_id) REFERENCES visit_approver_condition (id, approval_id),
    CONSTRAINT ck_approver_condition_bulk_item_applied CHECK ((result = 'APPLIED') = (condition_id IS NOT NULL)),
    CONSTRAINT ck_approver_condition_bulk_item_failed CHECK ((result = 'FAILED') = (failure_code IS NOT NULL))
);

CREATE TABLE approver_auth_event (
    id           BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id   BIGINT      NOT NULL REFERENCES approver_profile(id),
    approval_id  BIGINT      REFERENCES property_access_approval(id),
    batch_id     BIGINT      REFERENCES approver_condition_bulk_batch(id),
    event_type   VARCHAR(24) NOT NULL CHECK (event_type IN ('CLAIM_COMPLETED','LOGIN_SUCCEEDED','LOGIN_FAILED','APPROVAL_LINKED','APPROVAL_REJECTED','APPROVAL_UNLINKED','BULK_APPLIED','SESSION_REVOKED','PROFILE_CLOSED')),
    reason       VARCHAR(30),
    ip_hmac           CHAR(64),
    hmac_key_version  SMALLINT,
    occurred_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_approver_auth_event_approval CHECK (event_type NOT IN ('CLAIM_COMPLETED','APPROVAL_LINKED','APPROVAL_REJECTED','APPROVAL_UNLINKED') OR approval_id IS NOT NULL),
    CONSTRAINT ck_approver_auth_event_batch CHECK ((event_type = 'BULK_APPLIED') = (batch_id IS NOT NULL)),
    CONSTRAINT ck_approver_auth_event_ip CHECK ((ip_hmac IS NULL) = (hmac_key_version IS NULL) AND (hmac_key_version IS NULL OR hmac_key_version > 0))
);

CREATE INDEX ix_approver_auth_event_profile ON approver_auth_event (profile_id, occurred_at);

CREATE TABLE visit_approver_condition_date_rule (
    id            BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    condition_id  BIGINT      NOT NULL REFERENCES visit_approver_condition(id),
    rule_date     DATE        NOT NULL,
    rule_item     VARCHAR(24) NOT NULL CHECK (rule_item IN ('MAX_VISITS_PER_DAY','MIN_GAP','MIN_LEAD','SINGLE_VISIT_MAX')),
    limit_kind    VARCHAR(10) NOT NULL CHECK (limit_kind IN ('VALUE','UNLIMITED')),
    limit_value   INT,
    UNIQUE (condition_id, rule_date, rule_item),
    CONSTRAINT ck_visit_approver_condition_date_rule_kind CHECK ((limit_kind = 'VALUE') = (limit_value IS NOT NULL)),
    CONSTRAINT ck_visit_approver_condition_date_rule_value CHECK (
        limit_value IS NULL
        OR (rule_item IN ('MAX_VISITS_PER_DAY','SINGLE_VISIT_MAX') AND limit_value >= 1)
        OR (rule_item IN ('MIN_GAP','MIN_LEAD') AND limit_value >= 0))
);

CREATE TABLE visit_property_apply_grant (
    id                          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id                 BIGINT       NOT NULL,
    property_id                 BIGINT       NOT NULL,
    owner_office_id             BIGINT       NOT NULL,
    grantee_office_id           BIGINT       NOT NULL REFERENCES office(id),
    grantee_membership_id       BIGINT,
    granted_by_membership_id    BIGINT       NOT NULL,
    granted_at                  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at                  TIMESTAMPTZ,
    revoked_at                  TIMESTAMPTZ,
    revoke_source               VARCHAR(8)   CHECK (revoke_source IN ('OFFICE','SYSTEM')),
    revoked_by_membership_id    BIGINT,
    revoke_reason               TEXT,
    UNIQUE (id, approval_id, grantee_office_id),
    FOREIGN KEY (approval_id, property_id) REFERENCES property_access_approval (id, property_id),
    FOREIGN KEY (property_id, owner_office_id) REFERENCES property (id, office_id),
    FOREIGN KEY (granted_by_membership_id, owner_office_id) REFERENCES office_membership (id, office_id),
    FOREIGN KEY (revoked_by_membership_id, owner_office_id) REFERENCES office_membership (id, office_id),
    FOREIGN KEY (grantee_membership_id, grantee_office_id) REFERENCES office_membership (id, office_id),
    CONSTRAINT ck_visit_property_apply_grant_other_office CHECK (grantee_office_id <> owner_office_id),
    CONSTRAINT ck_visit_property_apply_grant_expiry CHECK (expires_at IS NULL OR expires_at > granted_at),
    CONSTRAINT ck_visit_property_apply_grant_revoke CHECK (
        (revoked_at IS NULL AND revoke_source IS NULL AND revoked_by_membership_id IS NULL AND revoke_reason IS NULL)
     OR (revoked_at IS NOT NULL AND revoke_source = 'OFFICE' AND revoked_by_membership_id IS NOT NULL AND NULLIF(BTRIM(revoke_reason), '') IS NOT NULL)
     OR (revoked_at IS NOT NULL AND revoke_source = 'SYSTEM' AND revoked_by_membership_id IS NULL AND NULLIF(BTRIM(revoke_reason), '') IS NOT NULL))
);

CREATE UNIQUE INDEX uq_visit_property_apply_grant_active_office ON visit_property_apply_grant (approval_id, grantee_office_id)
    WHERE revoked_at IS NULL AND grantee_membership_id IS NULL;

CREATE UNIQUE INDEX uq_visit_property_apply_grant_active_member ON visit_property_apply_grant (approval_id, grantee_membership_id)
    WHERE revoked_at IS NULL AND grantee_membership_id IS NOT NULL;

CREATE INDEX ix_visit_property_apply_grant_grantee ON visit_property_apply_grant (grantee_office_id) WHERE revoked_at IS NULL;

CREATE TABLE visit_property_apply_grant_event (
    id                      BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grant_id                BIGINT      NOT NULL REFERENCES visit_property_apply_grant(id),
    event_type              VARCHAR(10) NOT NULL CHECK (event_type IN ('GRANTED','REVOKED','EXPIRED')),
    source                  VARCHAR(8)  NOT NULL CHECK (source IN ('OFFICE','SYSTEM')),
    actor_membership_id     BIGINT      REFERENCES office_membership(id),
    reason                  VARCHAR(30),
    affected_request_count  INT         NOT NULL DEFAULT 0 CHECK (affected_request_count >= 0),
    occurred_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_visit_property_apply_grant_event_actor CHECK ((source = 'OFFICE') = (actor_membership_id IS NOT NULL)),
    CONSTRAINT ck_visit_property_apply_grant_event_expired CHECK (event_type <> 'EXPIRED' OR source = 'SYSTEM')
);

CREATE UNIQUE INDEX uq_visit_property_apply_grant_event_granted ON visit_property_apply_grant_event (grant_id) WHERE event_type = 'GRANTED';

CREATE UNIQUE INDEX uq_visit_property_apply_grant_event_expired ON visit_property_apply_grant_event (grant_id) WHERE event_type = 'EXPIRED';

CREATE INDEX ix_visit_property_apply_grant_event_grant ON visit_property_apply_grant_event (grant_id, occurred_at);

CREATE TABLE visit_review (
    id                         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    schedule_item_id           BIGINT       NOT NULL UNIQUE,
    request_id                 BIGINT       NOT NULL,
    approval_id                BIGINT       NOT NULL,
    reviewed_membership_id     BIGINT       NOT NULL,
    reviewed_office_id         BIGINT       NOT NULL,
    approver_link_id           BIGINT,
    approver_profile_id        BIGINT,
    punctuality                VARCHAR(4)   NOT NULL CHECK (punctuality IN ('YES','NO','SKIP')),
    advance_contact            VARCHAR(4)   NOT NULL CHECK (advance_contact IN ('YES','NO','SKIP')),
    as_requested               VARCHAR(4)   NOT NULL CHECK (as_requested IN ('YES','NO','SKIP')),
    status                     VARCHAR(10)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISPUTED','REMOVED','WITHDRAWN')),
    review_deadline_at         TIMESTAMPTZ  NOT NULL,
    submitted_at               TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_revised_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    revision_count             INT          NOT NULL DEFAULT 0 CHECK (revision_count BETWEEN 0 AND 2),
    withdrawn_at               TIMESTAMPTZ,
    removed_at                 TIMESTAMPTZ,
    removed_reason_code        VARCHAR(30)  CHECK (removed_reason_code IS NULL OR removed_reason_code IN ('DISPUTE_ACCEPTED','LEGAL_REQUEST','PRIVACY_REQUEST','OPERATOR_DISCRETION')),
    removed_by_operator_id     BIGINT       REFERENCES operator_account(id),
    updated_at                 TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                    BIGINT       NOT NULL DEFAULT 1,
    FOREIGN KEY (schedule_item_id, request_id) REFERENCES visit_schedule_item (id, confirmed_request_id),
    FOREIGN KEY (request_id, approval_id, reviewed_membership_id, reviewed_office_id) REFERENCES visit_request (id, approval_id, applicant_membership_id, applicant_office_id),
    FOREIGN KEY (approver_link_id, approval_id) REFERENCES visit_approver_property_link (id, approval_id),
    FOREIGN KEY (approver_profile_id, approval_id) REFERENCES approver_profile_approval (profile_id, approval_id),
    UNIQUE (id, reviewed_office_id),
    CONSTRAINT ck_visit_review_actor CHECK ((approver_link_id IS NOT NULL) <> (approver_profile_id IS NOT NULL)),
    CONSTRAINT ck_visit_review_answered CHECK (punctuality <> 'SKIP' OR advance_contact <> 'SKIP' OR as_requested <> 'SKIP'),
    CONSTRAINT ck_visit_review_deadline CHECK (review_deadline_at > submitted_at),
    CONSTRAINT ck_visit_review_withdrawn CHECK ((status = 'WITHDRAWN') = (withdrawn_at IS NOT NULL)),
    CONSTRAINT ck_visit_review_removed CHECK (
        ((status = 'REMOVED') = (removed_at IS NOT NULL AND removed_reason_code IS NOT NULL AND removed_by_operator_id IS NOT NULL))
        AND ((removed_at IS NULL) = (removed_reason_code IS NULL))
        AND ((removed_at IS NULL) = (removed_by_operator_id IS NULL))
    )
);

CREATE INDEX ix_visit_review_membership_active ON visit_review (reviewed_membership_id) WHERE status = 'ACTIVE';

CREATE INDEX ix_visit_review_approval ON visit_review (approval_id);

CREATE TABLE visit_review_dispute (
    id                         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    review_id                  BIGINT       NOT NULL UNIQUE,
    office_id                  BIGINT       NOT NULL,
    filed_by_membership_id     BIGINT       NOT NULL,
    reason_code                VARCHAR(20)  NOT NULL CHECK (reason_code IN ('FACT_INCORRECT','WRONG_TARGET','OTHER')),
    reason_text                TEXT         NOT NULL CHECK (char_length(reason_text) BETWEEN 1 AND 500),
    status                     VARCHAR(10)  NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','UPHELD','REMOVED')),
    filed_at                   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    decided_at                 TIMESTAMPTZ,
    decided_by_operator_id     BIGINT       REFERENCES operator_account(id),
    decision_note              TEXT         CHECK (decision_note IS NULL OR char_length(decision_note) <= 500),
    version                    BIGINT       NOT NULL DEFAULT 1,
    FOREIGN KEY (review_id, office_id) REFERENCES visit_review (id, reviewed_office_id),
    FOREIGN KEY (filed_by_membership_id, office_id) REFERENCES office_membership (id, office_id),
    CONSTRAINT ck_visit_review_dispute_decided CHECK (((status = 'OPEN') = (decided_at IS NULL)) AND ((decided_at IS NULL) = (decided_by_operator_id IS NULL))),
    CONSTRAINT ck_visit_review_dispute_note CHECK (status = 'OPEN' OR NULLIF(BTRIM(decision_note), '') IS NOT NULL)
);

CREATE INDEX ix_visit_review_dispute_open ON visit_review_dispute (filed_at) WHERE status = 'OPEN';

CREATE TABLE visit_preferred_broker (
    id                         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id                BIGINT       NOT NULL,
    broker_membership_id       BIGINT       NOT NULL REFERENCES office_membership(id),
    designated_via_link_id     BIGINT,
    designated_via_profile_id  BIGINT,
    source_request_id          BIGINT       REFERENCES visit_request(id),
    source_schedule_item_id    BIGINT       REFERENCES visit_schedule_item(id),
    designated_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),
    released_at                TIMESTAMPTZ,
    released_via_link_id       BIGINT,
    released_via_profile_id    BIGINT,
    FOREIGN KEY (designated_via_link_id, approval_id) REFERENCES visit_approver_property_link (id, approval_id),
    FOREIGN KEY (released_via_link_id, approval_id) REFERENCES visit_approver_property_link (id, approval_id),
    FOREIGN KEY (designated_via_profile_id, approval_id) REFERENCES approver_profile_approval (profile_id, approval_id),
    FOREIGN KEY (released_via_profile_id, approval_id) REFERENCES approver_profile_approval (profile_id, approval_id),
    CONSTRAINT ck_visit_preferred_broker_designated_actor CHECK ((designated_via_link_id IS NOT NULL) <> (designated_via_profile_id IS NOT NULL)),
    CONSTRAINT ck_visit_preferred_broker_source CHECK ((source_request_id IS NULL) <> (source_schedule_item_id IS NULL)),
    CONSTRAINT ck_visit_preferred_broker_released CHECK (((released_at IS NULL) = (released_via_link_id IS NULL AND released_via_profile_id IS NULL)) AND (released_via_link_id IS NULL OR released_via_profile_id IS NULL) AND (released_at IS NULL OR released_at >= designated_at))
);

CREATE UNIQUE INDEX uq_visit_preferred_broker_active ON visit_preferred_broker (approval_id, broker_membership_id) WHERE released_at IS NULL;

CREATE TABLE visit_selection_trust_snapshot (
    id                              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    selection_id                    BIGINT       NOT NULL REFERENCES visit_request_selection(id),
    compared_request_id             BIGINT       NOT NULL REFERENCES visit_request(id),
    broker_membership_id            BIGINT       NOT NULL REFERENCES office_membership(id),
    is_selected                     BOOLEAN      NOT NULL,
    is_preferred                    BOOLEAN      NOT NULL,
    policy_version                  VARCHAR(20)  NOT NULL,
    as_of                           TIMESTAMPTZ  NOT NULL,
    window_months                   INT          NOT NULL CHECK (window_months >= 1),
    state                           VARCHAR(12)  NOT NULL CHECK (state IN ('NO_DATA','INSUFFICIENT','AVAILABLE')),
    overall_band                    VARCHAR(4)   CHECK (overall_band IS NULL OR overall_band IN ('HIGH','MID','LOW')),
    completed_visit_count           INT          NOT NULL CHECK (completed_visit_count >= 0),
    evaluated_visit_count           INT          NOT NULL CHECK (evaluated_visit_count >= 0),
    distinct_approver_count         INT          NOT NULL CHECK (distinct_approver_count >= 0),
    punctuality_answered_count      INT          NOT NULL CHECK (punctuality_answered_count >= 0),
    punctuality_yes_count           INT          NOT NULL CHECK (punctuality_yes_count >= 0),
    punctuality_band                VARCHAR(4)   CHECK (punctuality_band IS NULL OR punctuality_band IN ('HIGH','MID','LOW')),
    advance_contact_answered_count  INT          NOT NULL CHECK (advance_contact_answered_count >= 0),
    advance_contact_yes_count       INT          NOT NULL CHECK (advance_contact_yes_count >= 0),
    advance_contact_band            VARCHAR(4)   CHECK (advance_contact_band IS NULL OR advance_contact_band IN ('HIGH','MID','LOW')),
    as_requested_answered_count     INT          NOT NULL CHECK (as_requested_answered_count >= 0),
    as_requested_yes_count          INT          NOT NULL CHECK (as_requested_yes_count >= 0),
    as_requested_band               VARCHAR(4)   CHECK (as_requested_band IS NULL OR as_requested_band IN ('HIGH','MID','LOW')),
    created_at                      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    UNIQUE (selection_id, compared_request_id),
    CONSTRAINT ck_visit_selection_trust_snapshot_counts CHECK (
        evaluated_visit_count <= completed_visit_count
        AND punctuality_yes_count <= punctuality_answered_count AND punctuality_answered_count <= evaluated_visit_count
        AND advance_contact_yes_count <= advance_contact_answered_count AND advance_contact_answered_count <= evaluated_visit_count
        AND as_requested_yes_count <= as_requested_answered_count AND as_requested_answered_count <= evaluated_visit_count
    ),
    CONSTRAINT ck_visit_selection_trust_snapshot_bands CHECK (
        (state = 'AVAILABLE' AND overall_band IS NOT NULL)
        OR (state <> 'AVAILABLE' AND overall_band IS NULL AND punctuality_band IS NULL AND advance_contact_band IS NULL AND as_requested_band IS NULL)
    )
);

CREATE UNIQUE INDEX uq_visit_selection_trust_snapshot_selected ON visit_selection_trust_snapshot (selection_id) WHERE is_selected;

CREATE TABLE legal_retention_rule (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rule_code                VARCHAR(50)  NOT NULL UNIQUE,
    data_group_label         VARCHAR(100) NOT NULL,
    retention_days           INT          NOT NULL CHECK (retention_days > 0),
    anchor_event             VARCHAR(20)  NOT NULL CHECK (anchor_event IN ('WITHDRAWN_AT','RECORDED_AT','APPROVAL_END','ACCESSED_AT','COMPLETED_AT','CLOSED_AT','CONTRACT_END','ISSUED_AT')),
    basis_note               TEXT         NOT NULL,
    status                   VARCHAR(20)  NOT NULL DEFAULT 'ASSUMPTION' CHECK (status IN ('ASSUMPTION','LAWYER_CONFIRMED','ADVISOR_CONFIRMED')),
    effective_from           DATE         NOT NULL DEFAULT CURRENT_DATE,
    updated_by_operator_id   BIGINT       REFERENCES operator_account(id),
    updated_at               TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                  BIGINT       NOT NULL DEFAULT 1 CHECK (version > 0)
);

CREATE TABLE consent_notice_delivery (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT      NOT NULL REFERENCES app_user(id),
    terms_agreement_id  BIGINT      NOT NULL REFERENCES terms_agreement(id),
    notice_type         VARCHAR(20) NOT NULL CHECK (notice_type IN ('MARKETING_RESULT','MARKETING_RECONFIRM')),
    cycle_no            INT         NOT NULL DEFAULT 1 CHECK (cycle_no >= 1),
    expressed_at        TIMESTAMPTZ NOT NULL,
    target_at           TIMESTAMPTZ NOT NULL,
    due_at              TIMESTAMPTZ NOT NULL,
    status              VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','FAILED','SKIPPED_NO_EMAIL')),
    attempt_count       INT         NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    sent_at             TIMESTAMPTZ,
    failure_code        VARCHAR(40),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (terms_agreement_id, notice_type, cycle_no),
    CHECK (target_at <= due_at),
    CHECK ((status = 'SENT') = (sent_at IS NOT NULL))
);

CREATE INDEX ix_consent_notice_delivery_pending ON consent_notice_delivery (target_at) WHERE status = 'PENDING';

CREATE TABLE consent_guest_notice_ack (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    office_id                   BIGINT      NOT NULL REFERENCES office(id),
    link_kind                   VARCHAR(20) NOT NULL CHECK (link_kind IN ('APPROVER_PROPERTY','CUSTOMER','APPROVER_PORTAL')),
    approver_property_link_id   BIGINT REFERENCES visit_approver_property_link(id) ON DELETE CASCADE,
    approver_profile_id         BIGINT REFERENCES approver_profile(id),
    customer_link_id            BIGINT REFERENCES visit_customer_link(id) ON DELETE CASCADE,
    terms_code                  VARCHAR(30) NOT NULL,
    terms_version               VARCHAR(20) NOT NULL,
    action_type                 VARCHAR(20) NOT NULL CHECK (action_type IN ('CONDITION_SAVE','TIME_SUBMIT','REQUEST_SELECT','PRIVACY_INTAKE','REVIEW_SUBMIT','PREFERRED_SET','PORTAL_CLAIM')),
    resource_version            INT,
    acknowledged_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (terms_code, terms_version) REFERENCES terms_catalog (terms_code, terms_version),
    CHECK (
        (link_kind = 'APPROVER_PROPERTY' AND approver_property_link_id IS NOT NULL AND customer_link_id IS NULL AND approver_profile_id IS NULL)
        OR (link_kind = 'CUSTOMER' AND customer_link_id IS NOT NULL AND approver_property_link_id IS NULL AND approver_profile_id IS NULL)
        OR (link_kind = 'APPROVER_PORTAL' AND approver_profile_id IS NOT NULL AND approver_property_link_id IS NULL AND customer_link_id IS NULL)
    )
);

CREATE INDEX ix_consent_guest_notice_ack_approver ON consent_guest_notice_ack (approver_property_link_id, acknowledged_at) WHERE approver_property_link_id IS NOT NULL;

CREATE INDEX ix_consent_guest_notice_ack_customer ON consent_guest_notice_ack (customer_link_id, acknowledged_at) WHERE customer_link_id IS NOT NULL;

CREATE INDEX ix_consent_guest_notice_ack_office ON consent_guest_notice_ack (office_id, acknowledged_at);

CREATE TABLE legal_public_link_access_log (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    accessed_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    link_kind         VARCHAR(20) CHECK (link_kind IN ('APPROVER_PROPERTY','CUSTOMER','APPROVER_PORTAL')),
    link_id           BIGINT,
    office_id         BIGINT REFERENCES office(id),
    action_type       VARCHAR(20) NOT NULL CHECK (action_type IN ('VIEW','CONDITION_SAVE','TIME_SUBMIT','REQUEST_SELECT','PRIVACY_INTAKE','CONFIRMED_VIEW','INVALID_TOKEN','REVIEW_SUBMIT','PREFERRED_SET','PORTAL_AUTH')),
    http_status       SMALLINT    NOT NULL CHECK (http_status BETWEEN 100 AND 599),
    ip_hmac           CHAR(64)    NOT NULL,
    user_agent_hash   CHAR(64),
    hmac_key_version  SMALLINT    NOT NULL CHECK (hmac_key_version > 0),
    purge_after       DATE        NOT NULL,
    CHECK ((link_kind IS NULL) = (link_id IS NULL)),
    CHECK (action_type <> 'INVALID_TOKEN' OR link_id IS NULL)
);

CREATE INDEX ix_legal_public_link_access_link ON legal_public_link_access_log (link_kind, link_id, accessed_at);

CREATE INDEX ix_legal_public_link_access_purge ON legal_public_link_access_log (purge_after);

CREATE TABLE legal_guest_privacy_intake (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    office_id             BIGINT      NOT NULL REFERENCES office(id),
    link_kind             VARCHAR(20) NOT NULL CHECK (link_kind IN ('APPROVER_PROPERTY','CUSTOMER','APPROVER_PORTAL')),
    link_id               BIGINT      NOT NULL,
    request_type          VARCHAR(20) NOT NULL CHECK (request_type IN ('ACCESS','CORRECTION','DELETION','SUSPENSION')),
    requester_role        VARCHAR(10) NOT NULL CHECK (requester_role IN ('SELF','AGENT')),
    contact_channel       VARCHAR(10) NOT NULL CHECK (contact_channel IN ('EMAIL','PHONE')),
    contact_encrypted     TEXT,
    contact_wiped_at      TIMESTAMPTZ,
    request_note          TEXT CHECK (request_note IS NULL OR char_length(request_note) <= 1000),
    verification_status   VARCHAR(10) NOT NULL DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING','VERIFIED','FAILED')),
    status                VARCHAR(12) NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','CONVERTED','CLOSED')),
    privacy_request_id    BIGINT UNIQUE REFERENCES privacy_request(id),
    received_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    internal_due_at       TIMESTAMPTZ NOT NULL,
    closed_at             TIMESTAMPTZ,
    closed_reason         VARCHAR(30) CHECK (closed_reason IN ('COMPLETED_BY_PRIVACY_REQUEST','DUPLICATE','NOT_SUBJECT','UNVERIFIABLE','WITHDRAWN_BY_REQUESTER')),
    CHECK ((contact_encrypted IS NULL) = (contact_wiped_at IS NOT NULL)),
    CHECK (status <> 'CONVERTED' OR privacy_request_id IS NOT NULL),
    CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL AND closed_reason IS NOT NULL)),
    CHECK (internal_due_at >= received_at)
);

CREATE INDEX ix_legal_guest_privacy_intake_queue ON legal_guest_privacy_intake (status, internal_due_at) WHERE status <> 'CLOSED';

CREATE INDEX ix_legal_guest_privacy_intake_office ON legal_guest_privacy_intake (office_id, received_at DESC);

CREATE TABLE legal_kakao_unlink_event (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    direction             VARCHAR(16) NOT NULL CHECK (direction IN ('OUTBOUND_CALL','INBOUND_WEBHOOK')),
    user_id               BIGINT REFERENCES app_user(id),
    kakao_key_hmac        CHAR(64),
    hmac_key_version      SMALLINT CHECK (hmac_key_version > 0),
    target_key_encrypted  TEXT,
    referrer_type         VARCHAR(40),
    status                VARCHAR(20) NOT NULL CHECK (status IN ('PENDING','SUCCEEDED','FAILED_RETRYING','ABANDONED','APPLIED','NO_MATCH','DUPLICATE_IGNORED')),
    attempt_count         INT         NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    next_attempt_at       TIMESTAMPTZ,
    last_error_code       VARCHAR(40),
    occurred_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at          TIMESTAMPTZ,
    key_wiped_at          TIMESTAMPTZ,
    CHECK (direction = 'OUTBOUND_CALL' OR (target_key_encrypted IS NULL AND status IN ('APPLIED','NO_MATCH','DUPLICATE_IGNORED'))),
    CHECK (direction = 'INBOUND_WEBHOOK' OR (user_id IS NOT NULL AND status IN ('PENDING','SUCCEEDED','FAILED_RETRYING','ABANDONED'))),
    CHECK (direction = 'OUTBOUND_CALL' OR (kakao_key_hmac IS NOT NULL AND hmac_key_version IS NOT NULL)),
    CHECK (status NOT IN ('SUCCEEDED','ABANDONED','APPLIED','NO_MATCH','DUPLICATE_IGNORED') OR completed_at IS NOT NULL),
    CHECK (target_key_encrypted IS NULL OR status IN ('PENDING','FAILED_RETRYING')),
    CHECK (direction <> 'OUTBOUND_CALL' OR status NOT IN ('PENDING','FAILED_RETRYING') OR target_key_encrypted IS NOT NULL),
    CHECK ((status IN ('PENDING','FAILED_RETRYING')) = (next_attempt_at IS NOT NULL))
);

CREATE INDEX ix_legal_kakao_unlink_event_retry ON legal_kakao_unlink_event (next_attempt_at) WHERE status IN ('PENDING','FAILED_RETRYING');

CREATE INDEX ix_legal_kakao_unlink_event_key ON legal_kakao_unlink_event (kakao_key_hmac, occurred_at) WHERE kakao_key_hmac IS NOT NULL;

CREATE TABLE legal_authority_request (
    id                        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    received_at               TIMESTAMPTZ  NOT NULL,
    agency_type               VARCHAR(16)  NOT NULL CHECK (agency_type IN ('INVESTIGATION','COURT','SUPERVISORY','OTHER')),
    agency_name               VARCHAR(200) NOT NULL,
    document_reference        VARCHAR(100),
    legal_basis_note          TEXT         NOT NULL,
    target_office_id          BIGINT REFERENCES office(id),
    target_user_id            BIGINT REFERENCES app_user(id),
    requested_items           TEXT         NOT NULL,
    decision                  VARCHAR(24)  NOT NULL DEFAULT 'PENDING' CHECK (decision IN ('PENDING','PROVIDED','PARTIALLY_PROVIDED','REFUSED','FORWARDED_TO_OFFICE')),
    provided_items            TEXT,
    provided_at               TIMESTAMPTZ,
    office_notice_status      VARCHAR(20)  NOT NULL DEFAULT 'NOT_REVIEWED' CHECK (office_notice_status IN ('NOT_REVIEWED','NOTIFIED','DEFERRED','NOT_ALLOWED')),
    recorded_by_operator_id   BIGINT       NOT NULL REFERENCES operator_account(id),
    approved_by_operator_id   BIGINT REFERENCES operator_account(id),
    closed_at                 TIMESTAMPTZ,
    retention_until           DATE,
    created_at                TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CHECK (decision NOT IN ('PROVIDED','PARTIALLY_PROVIDED') OR (provided_items IS NOT NULL AND provided_at IS NOT NULL AND approved_by_operator_id IS NOT NULL AND approved_by_operator_id <> recorded_by_operator_id)),
    CHECK (closed_at IS NULL OR retention_until IS NOT NULL)
);

CREATE INDEX ix_legal_authority_request_open ON legal_authority_request (received_at) WHERE closed_at IS NULL;

CREATE TABLE legal_provider_contract_copy (
    id                               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    integration_id                   BIGINT       NOT NULL REFERENCES integration_config(id),
    document_kind                    VARCHAR(20)  NOT NULL CHECK (document_kind IN ('SERVICE_CONTRACT','PROCESSING_TERMS','SUBPROCESSOR_NOTICE','OTHER')),
    version_label                    VARCHAR(40)  NOT NULL,
    signed_on                        DATE,
    valid_until                      DATE,
    storage_key                      VARCHAR(300) NOT NULL,
    content_sha256                   CHAR(64)     NOT NULL,
    subprocessor_change_notified_at  TIMESTAMPTZ,
    uploaded_by_operator_id          BIGINT       NOT NULL REFERENCES operator_account(id),
    uploaded_at                      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    retention_until                  DATE,
    UNIQUE (integration_id, document_kind, version_label),
    CHECK (valid_until IS NULL OR signed_on IS NULL OR valid_until >= signed_on)
);

CREATE TABLE tax_invoice_recipient (
    id                           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    office_id                    BIGINT       NOT NULL REFERENCES office(id),
    status                       VARCHAR(12)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUPERSEDED')),
    business_number              CHAR(10)     NOT NULL CHECK (business_number ~ '^[0-9]{10}$'),
    company_name                 VARCHAR(100) NOT NULL,
    representative_name          VARCHAR(50)  NOT NULL,
    receiver_email               VARCHAR(254) NOT NULL,
    tax_type                     VARCHAR(12)  NOT NULL DEFAULT 'UNKNOWN' CHECK (tax_type IN ('GENERAL','SIMPLIFIED','EXEMPT','UNKNOWN')),
    issue_requested              BOOLEAN      NOT NULL DEFAULT true,
    registered_by_membership_id  BIGINT       NOT NULL REFERENCES office_membership(id),
    registered_at                TIMESTAMPTZ  NOT NULL DEFAULT now(),
    superseded_at                TIMESTAMPTZ,
    CHECK ((status = 'SUPERSEDED') = (superseded_at IS NOT NULL))
);

CREATE UNIQUE INDEX uq_tax_invoice_recipient_active ON tax_invoice_recipient (office_id) WHERE status = 'ACTIVE';

CREATE TABLE tax_document (
    id                        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    billing_invoice_id        BIGINT      NOT NULL REFERENCES billing_invoice(id),
    recipient_id              BIGINT REFERENCES tax_invoice_recipient(id),
    document_kind             VARCHAR(20) NOT NULL CHECK (document_kind IN ('TAX_INVOICE','CASH_RECEIPT','EXEMPT_INVOICE')),
    is_electronic             BOOLEAN     NOT NULL DEFAULT true,
    status                    VARCHAR(16) NOT NULL CHECK (status IN ('NOT_REQUIRED','PENDING','ISSUED','ISSUE_FAILED','AMENDED','CANCELLED')),
    approval_number           VARCHAR(40),
    issued_on                 DATE,
    supply_amount             BIGINT,
    vat_amount                BIGINT,
    original_document_id      BIGINT REFERENCES tax_document(id),
    operator_note             TEXT,
    recorded_by_operator_id   BIGINT      NOT NULL REFERENCES operator_account(id),
    recorded_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
    retention_until           DATE,
    version                   BIGINT      NOT NULL DEFAULT 1 CHECK (version > 0),
    CHECK (status NOT IN ('ISSUED','AMENDED') OR (approval_number IS NOT NULL AND issued_on IS NOT NULL AND supply_amount IS NOT NULL AND vat_amount IS NOT NULL)),
    CHECK (status <> 'AMENDED' OR original_document_id IS NOT NULL),
    CHECK (original_document_id IS NULL OR original_document_id <> id),
    CHECK (status NOT IN ('ISSUE_FAILED','AMENDED','CANCELLED') OR operator_note IS NOT NULL)
);

CREATE UNIQUE INDEX uq_tax_document_issued ON tax_document (billing_invoice_id, document_kind) WHERE status = 'ISSUED';

CREATE UNIQUE INDEX uq_tax_document_approval_number ON tax_document (approval_number) WHERE approval_number IS NOT NULL;

CREATE INDEX ix_tax_document_invoice ON tax_document (billing_invoice_id, recorded_at DESC);

ALTER TABLE visit_approver_condition ADD CONSTRAINT fk_visit_approver_condition_entered_by_profile_id FOREIGN KEY (entered_by_profile_id) REFERENCES approver_profile(id);

ALTER TABLE visit_request ADD CONSTRAINT fk_visit_request_access_grant FOREIGN KEY (access_grant_id, approval_id, applicant_office_id) REFERENCES visit_property_apply_grant (id, approval_id, grantee_office_id);

ALTER TABLE visit_request_selection ADD CONSTRAINT fk_visit_request_selection_approver_profile_id FOREIGN KEY (approver_profile_id) REFERENCES approver_profile(id);

-- ---------------------------------------------------------------------
-- 3. Existing tables: constraints that reference new tables
-- ---------------------------------------------------------------------
ALTER TABLE visit_schedule_item ADD CONSTRAINT fk_visit_schedule_item_confirmed_request FOREIGN KEY (confirmed_request_id) REFERENCES visit_request(id);

-- ---------------------------------------------------------------------
-- 3. COMMENT statements for all 140 tables
-- ---------------------------------------------------------------------
COMMENT ON TABLE app_user IS '이메일 또는 카카오로 인증한 사용자. 두 로그인수단을 함께 등록할 수 있다. 두 수단은 서로 연결할 수 있다. 마지막 남은 로그인수단은 해제할 수 없다. 이 규칙은 서비스 계층이 강제한다';
COMMENT ON COLUMN app_user.id IS '사용자 내부 식별자';
COMMENT ON COLUMN app_user.email IS '이메일 로그인 주소다. 값이 있으면 반드시 password_hash도 있어야 하고 반드시 인증을 거친 값이다. 카카오 가입 시 참고용으로 받는 이메일은 이 컬럼이 아니라 kakao_reference_email에 저장한다';
COMMENT ON COLUMN app_user.password_hash IS '단방향 해시다. bcrypt 등을 쓴다. 평문과 재설정 토큰은 어떤 로그에도 남기지 않는다';
COMMENT ON COLUMN app_user.email_verified_at IS '이메일 인증 완료 시각이다. NULL이면 미인증 이메일이다';
COMMENT ON COLUMN app_user.kakao_provider_key IS '카카오 고유 회원번호';
COMMENT ON COLUMN app_user.kakao_reference_email IS '카카오 가입 시 사용자가 참고용으로 직접 입력한 이메일이다. 인증을 거치지 않으며 로그인 이메일로 쓰지 않는다. email 컬럼과 별개 컬럼이라 ck_app_user_email_needs_password 제약과 충돌하지 않는다';
COMMENT ON COLUMN app_user.phone IS '휴대폰 번호. 본인확인을 완료한 번호만 저장한다. 본인확인을 마친 활성 계정 사이에서는 유일하다';
COMMENT ON COLUMN app_user.phone_verified_at IS '휴대폰 본인확인 완료 시각';
COMMENT ON COLUMN app_user.name IS '표시 이름';
COMMENT ON COLUMN app_user.account_status IS '계정 상태다. ACTIVE는 정상, WITHDRAWN은 탈퇴다';
COMMENT ON COLUMN app_user.failed_login_count IS '연속 로그인 실패 횟수다. IP와 계정 조합 기준 카운터는 서비스 계층이 별도로 관리한다';
COMMENT ON COLUMN app_user.failed_login_locked_until IS '5회 실패 시 15분 지연 잠금의 만료 시각';
COMMENT ON COLUMN app_user.created_at IS '계정 생성 일시';
COMMENT ON COLUMN app_user.withdrawn_at IS '탈퇴 처리 일시. WITHDRAWN이 아니면 NULL';
COMMENT ON INDEX uq_app_user_verified_phone IS '본인확인을 마친 활성 계정 사이에서 휴대폰 번호는 유일하다. 겹치는 번호로 가입하면 409 PHONE_ALREADY_REGISTERED로 거절한다. 탈퇴 계정과 본인확인 전 번호는 대상이 아니다';
COMMENT ON COLUMN app_user.kakao_unlinked_at IS '카카오 쪽 연결 끊김을 수신한 시각이다. 값이 있으면 카카오 로그인수단이 끊어진 상태다';
COMMENT ON TABLE email_verification_token IS '이메일 인증 링크다. 발급 후 30분간 1회 유효하다. 이메일당 활성(미소진·미대체) 링크는 최대 1개다';
COMMENT ON COLUMN email_verification_token.id IS '이메일 인증 토큰 내부 식별자';
COMMENT ON COLUMN email_verification_token.user_id IS 'LINK와 CHANGE 목적일 때만 값이 있다. LINK는 이미 가입된 계정에 이메일을 연결하고 CHANGE는 이미 가입된 계정의 로그인 이메일을 새 주소로 바꾼다. 두 목적 모두 대상 계정이 정해져 있어 user_id가 필요하다. SIGNUP은 계정 생성 이전 단계라 NULL이다';
COMMENT ON COLUMN email_verification_token.email IS '이메일';
COMMENT ON COLUMN email_verification_token.purpose IS 'SIGNUP은 신규가입 인증, LINK는 기존 계정에 이메일을 연결하는 것, CHANGE는 로그인 이메일을 바꾸려는 새 주소의 인증 링크다';
COMMENT ON COLUMN email_verification_token.token_hash IS '토큰 원문의 SHA-256 해시다. 원문은 저장하지 않는다';
COMMENT ON COLUMN email_verification_token.issued_at IS '발급 일시';
COMMENT ON COLUMN email_verification_token.expires_at IS '발급 후 정확히 30분 뒤의 시각';
COMMENT ON COLUMN email_verification_token.consumed_at IS '인증을 완료해 소진한 시각이다. NULL이면 미사용이다';
COMMENT ON COLUMN email_verification_token.superseded_at IS '같은 이메일로 재발송해 이 행이 무효화된 시각이다. 재발송 시 서비스 계층이 이전 미소진 행에 이 값을 채운 뒤 새 행을 삽입한다. 이렇게 해야 uq_email_verification_active가 재발송 자체를 막지 않는다';
COMMENT ON INDEX uq_email_verification_active IS '이메일당 활성 인증 링크는 최대 1개다. 발송 60초 간격과 시간당 5회 제한은 rate_limit_counter가 담당한다';
COMMENT ON TABLE password_reset_token IS '비밀번호 재설정 링크다. 같은 사용자의 활성(미소진·미대체) 링크는 최대 1개다';
COMMENT ON COLUMN password_reset_token.id IS '비밀번호 재설정 토큰 내부 식별자';
COMMENT ON COLUMN password_reset_token.user_id IS '대상 사용자';
COMMENT ON COLUMN password_reset_token.token_hash IS '토큰 원문의 SHA-256 해시다. 원문과 재설정 토큰은 어떤 로그에도 남기지 않는다';
COMMENT ON COLUMN password_reset_token.issued_at IS '발급 일시';
COMMENT ON COLUMN password_reset_token.expires_at IS '만료 일시';
COMMENT ON COLUMN password_reset_token.consumed_at IS '소진 처리 일시';
COMMENT ON COLUMN password_reset_token.superseded_at IS '재발급으로 이 행이 무효화된 시각이다. 재발급 시 서비스 계층이 이전 미소진 행에 이 값을 채운 뒤 새 행을 삽입한다';
COMMENT ON TABLE login_history IS '로그인 시도 기록. 최근 로그인 조회·보안 감사용. 세션 자체는 별도 세션 저장소가 관리한다';
COMMENT ON COLUMN login_history.id IS '로그인 기록 내부 식별자';
COMMENT ON COLUMN login_history.user_id IS '대상 사용자';
COMMENT ON COLUMN login_history.auth_method IS '이번 로그인에 실제 사용한 수단';
COMMENT ON COLUMN login_history.ip_address IS '요청 IP';
COMMENT ON COLUMN login_history.user_agent IS '요청 환경 정보';
COMMENT ON COLUMN login_history.created_at IS '생성 일시';
COMMENT ON TABLE terms_catalog IS '약관·개인정보처리방침·마케팅수신동의 등 동의 항목의 버전 카탈로그다. terms_code=MARKETING처럼 선택 동의 항목도 이 카탈로그로 통합 관리한다. 선택 항목은 required 값이 false다. 개인정보처리방침은 category가 NOTICE이고 required가 false인 행으로 둔다';
COMMENT ON COLUMN terms_catalog.terms_code IS '약관 코드';
COMMENT ON COLUMN terms_catalog.terms_version IS '약관 버전';
COMMENT ON COLUMN terms_catalog.title IS '화면과 동의 내역에 표시하는 약관 제목이다. 버전 행마다 갖고 동의 내역 응답의 약관 표시명과 같은 값이다';
COMMENT ON COLUMN terms_catalog.category IS 'TERMS는 이용약관 필수 동의, NOTICE는 계약 이행에 필요한 처리의 열람 고지로 동의 대상이 아니다. SEPARATE_CONSENT는 별도 동의가 필요한 처리의 항목별 동의, MARKETING은 선택 동의로 기본 미동의다';
COMMENT ON COLUMN terms_catalog.required IS '미동의 시 가입을 거부하는 필수 약관인지를 나타낸다. 마케팅 수신 동의처럼 선택 항목은 false이고 기본값은 미동의다. NOTICE 항목은 동의 대상이 아니므로 항상 false다. 철회할 수 있는 항목은 required가 false인 선택 항목이며 별도 컬럼을 두지 않는다';
COMMENT ON COLUMN terms_catalog.document_url IS '시행 버전 전문을 여는 주소다. SEPARATE_CONSENT 항목의 구체 문구도 이 주소가 가리키는 본문으로 저장한다';
COMMENT ON COLUMN terms_catalog.content_hash IS '약관 본문 해시';
COMMENT ON COLUMN terms_catalog.effective_at IS '시행 시각';
COMMENT ON COLUMN terms_catalog.display_context IS '이 항목을 보여 주는 맥락이다. SIGNUP은 가입과 설정 화면, CARD_REGISTRATION은 카드 등록 안내, LINK_NOTICE는 비회원 링크 안내, PURCHASE는 구독 구매 동의다. GET /api/terms의 context 필터가 이 값을 쓴다';
COMMENT ON COLUMN terms_catalog.reconsent_required IS '이 버전이 시행될 때 기존 동의자에게 재동의를 받아야 하는지다. 고지만 하는 개정은 false다. TERMS와 SEPARATE_CONSENT 범주만 true가 될 수 있다';
COMMENT ON COLUMN terms_catalog.change_summary IS '재동의 화면에 보여 주는 주요 변경 내용이다';
COMMENT ON COLUMN terms_catalog.last_hash_checked_at IS '게시된 본문 해시를 마지막으로 대조한 시각이다';
COMMENT ON COLUMN terms_catalog.last_hash_check_result IS '마지막 대조 결과다. MATCH는 일치, MISMATCH는 불일치, ERROR는 원문을 읽지 못한 경우다';
COMMENT ON TABLE terms_agreement IS '동의·철회 이벤트 로그다. append-only로 기록해 행을 수정하지 않는다. 현재 동의 상태는 사용자·약관코드별 최신 행의 agreed 값이다. 과거 동의는 당시 시행 버전인 terms_version을 그대로 참조한다. 정책이 바뀌어도 과거 이력은 재해석되지 않는다. 탈퇴 뒤 보관 기간이 지나도 구독 구매 동의나 수신 설정 통지 이력이 이 행을 참조하는 동안은 지우지 않고 참조하는 행의 보관이 끝난 뒤 지운다';
COMMENT ON COLUMN terms_agreement.id IS '약관 동의 내부 식별자';
COMMENT ON COLUMN terms_agreement.user_id IS '대상 사용자';
COMMENT ON COLUMN terms_agreement.terms_code IS '약관 코드';
COMMENT ON COLUMN terms_agreement.terms_version IS '약관 버전';
COMMENT ON COLUMN terms_agreement.agreed IS '동의 여부';
COMMENT ON COLUMN terms_agreement.recorded_at IS '기록 일시';
COMMENT ON COLUMN terms_agreement.consent_path IS '동의 또는 철회가 일어난 경로다. UNKNOWN은 이 컬럼을 추가하기 전에 쌓인 행에만 쓰며 새 행은 UNKNOWN을 쓰지 않는다';
COMMENT ON COLUMN terms_agreement.office_id IS '사무소 단위 동의의 사무소다. 구독 구매 동의와 카드 등록 안내 확인은 값이 필수이고 회원 단위 동의는 비워 둔다. 대표가 바뀐 뒤에도 사무소 기준으로 이전 기록을 찾기 위한 값이다';
COMMENT ON TABLE app_user_notification_preference IS '사용자별 알림 수신 설정이다. 설정 키는 VISIT_REMINDER, SECURITY, MARKETING 세 가지이며 행이 없는 키는 서비스 기본값을 따른다. SECURITY는 법정 고지성이라 enabled가 항상 true다. 사무소 인증 심사, 구성원 승인 필요, 초대, 담당자 변경, 체험 종료 예정, 요금제 변경, 결제, 반환 예정, 파기 예정, 문의 답변 알림은 서비스 필수 알림이라 어느 키에도 속하지 않고 이 표와 무관하게 항상 발송한다. GET /api/me의 notificationPreferences와 PATCH /api/me/notification-preferences가 이 표를 쓴다';
COMMENT ON COLUMN app_user_notification_preference.id IS '알림 수신 설정 내부 식별자';
COMMENT ON COLUMN app_user_notification_preference.user_id IS '설정 주인인 사용자';
COMMENT ON COLUMN app_user_notification_preference.channel_key IS '알림 수신 설정 키다. VISIT_REMINDER는 방문 일정·확정·재조율·결과 입력·감독 확인 알림, SECURITY는 로그인·보안 알림, MARKETING은 공지·혜택·프로모션 알림이다';
COMMENT ON COLUMN app_user_notification_preference.enabled IS '수신 여부다. SECURITY 키는 항상 true다';
COMMENT ON COLUMN app_user_notification_preference.created_at IS '설정 행 생성 일시';
COMMENT ON COLUMN app_user_notification_preference.updated_at IS '설정을 마지막으로 바꾼 일시';
COMMENT ON TABLE office IS '사업자 인증이 승인된 부동산 중개사무소다. 값은 신청자 제출값이 아니라 사이로 운영자가 심사 후 최종 확정한 값이다. 사업자등록번호는 UNIQUE를 걸지 않는다. 법인의 복수 사무소 등 정당한 중복이 있을 수 있다. 운영자가 지점과 등록관계를 확인해 개별 판단하며, 중복은 경고로만 표시한다';
COMMENT ON COLUMN office.id IS '사무소 내부 식별자';
COMMENT ON COLUMN office.name IS '이름';
COMMENT ON COLUMN office.entity_type IS '개인·법인 구분';
COMMENT ON COLUMN office.registration_authority IS '개설등록관청이다. real_estate_license_number와 조합해 사무소 식별 유니크 키를 이룬다';
COMMENT ON COLUMN office.real_estate_license_number IS '개설등록번호';
COMMENT ON COLUMN office.business_registration_number IS '사업자등록번호다. 중복이면 신청 화면에서 경고만 표시한다. UNIQUE 제약은 걸지 않는다';
COMMENT ON COLUMN office.representative_name IS '대표자 이름';
COMMENT ON COLUMN office.representative_phone IS '대표자 연락처';
COMMENT ON COLUMN office.address IS '주소';
COMMENT ON COLUMN office.created_at IS '생성 일시';
COMMENT ON TABLE office_registration IS '신규 사무소 등록 신청이다. 승인 시 office는 이 행의 값이 아니라 운영자가 최종 확정한 값으로 생성된다. 자동 승인 경로는 없다. 작성 중에서 심사 중으로 넘어가고, 심사 중에서 승인, 보완요청, 반려 중 하나로 전이한다. 인증완료 후 핵심정보 변경이나 허위 확인이 드러나면 운영자가 REVOKED로 회수할 수 있다. 신청자는 작성 중, 심사 중, 보완요청 상태에서 CANCELLED로 직접 취소할 수 있다. 작성 중에서 증빙 제출에 성공하면 심사 중으로 전이한다';
COMMENT ON COLUMN office_registration.id IS '사업자 인증 신청 내부 식별자';
COMMENT ON COLUMN office_registration.applicant_user_id IS '신청자';
COMMENT ON COLUMN office_registration.entity_type IS '개인·법인 구분';
COMMENT ON COLUMN office_registration.registration_authority IS '개설등록관청';
COMMENT ON COLUMN office_registration.real_estate_license_number IS '개설등록번호';
COMMENT ON COLUMN office_registration.business_registration_number IS '사업자등록번호';
COMMENT ON COLUMN office_registration.requested_office_name IS '신청 사무소명';
COMMENT ON COLUMN office_registration.requested_representative_name IS '신청 대표자명';
COMMENT ON COLUMN office_registration.requested_representative_phone IS '신청 연락처';
COMMENT ON COLUMN office_registration.requested_address IS '신청 주소';
COMMENT ON COLUMN office_registration.applicant_registration_relation IS '신청자의 등록관계다. 대표 본인 또는 법인 대표권한자 등을 값으로 갖는다. 법인은 대표권한과 등록관계 확인자료를 evidence로 별도 첨부한다';
COMMENT ON COLUMN office_registration.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN office_registration.resulting_office_id IS '승인 시 생성된 사무소';
COMMENT ON COLUMN office_registration.current_revision_no IS '현재 심사 대상 버전이다. 보완요청 후 재제출하면 office_registration_revision에 새 버전이 쌓이고 이 값이 증가한다';
COMMENT ON COLUMN office_registration.supplement_reason IS '보완 사유';
COMMENT ON COLUMN office_registration.supplement_due_at IS '보완 기한';
COMMENT ON COLUMN office_registration.rejection_reason IS '거절 사유';
COMMENT ON COLUMN office_registration.revocation_reason IS '회수 사유';
COMMENT ON COLUMN office_registration.reviewed_at IS '심사 처리 일시';
COMMENT ON COLUMN office_registration.revoked_at IS '폐기 일시';
COMMENT ON COLUMN office_registration.cancelled_at IS '신청자 취소 처리 일시다. CANCELLED에서만 값이 있다';
COMMENT ON COLUMN office_registration.resolved_at IS '재신청 시작으로 REJECTED 건이 해결됨 처리된 일시다. REJECTED에서만 값이 있다. REVOKED는 재신청 개념이 없어 항상 NULL이다';
COMMENT ON COLUMN office_registration.created_at IS '생성 일시';
COMMENT ON INDEX uq_office_registration_pending_applicant IS '신청자당 진행 중인 신규 사무소 신청은 최대 1개다. 작성 중과 심사 중과 보완 요청이 진행 중 상태다';
COMMENT ON TABLE office_registration_revision IS '보완요청 후 재제출마다 쌓이는 심사 버전 스냅샷이다. 증빙은 office_registration_evidence에서 종류별로 보관한다. 증빙 원본은 최대 30일 보관한 뒤 파기한다. 심사 결과와 사유만 반환기간까지 보존한다';
COMMENT ON COLUMN office_registration_revision.id IS '사업자 인증 신청 재제출 버전 내부 식별자';
COMMENT ON COLUMN office_registration_revision.registration_id IS '대상 신청';
COMMENT ON COLUMN office_registration_revision.revision_no IS '재제출 버전 번호';
COMMENT ON COLUMN office_registration_revision.requested_office_name IS '신청 사무소명';
COMMENT ON COLUMN office_registration_revision.requested_address IS '신청 주소';
COMMENT ON COLUMN office_registration_revision.submitted_at IS '제출 처리 일시';
COMMENT ON TABLE office_registration_evidence IS '심사 버전별 증빙 파일이다. 개설등록증, 사업자등록증, 대표 자격증 사본, 법인 대표권한 확인자료, 신청자 등록관계 확인자료를 종류별 한 건씩 기록한다';
COMMENT ON COLUMN office_registration_evidence.id IS '증빙 파일 내부 식별자';
COMMENT ON COLUMN office_registration_evidence.revision_id IS '증빙이 속한 심사 버전';
COMMENT ON COLUMN office_registration_evidence.evidence_type IS 'BROKERAGE_LICENSE 개설등록증, BUSINESS_CERTIFICATE 사업자등록증, REPRESENTATIVE_QUALIFICATION 대표 자격증 사본, CORPORATE_AUTHORITY 법인 대표권한 확인자료, REGISTRATION_RELATION 신청자 등록관계 확인자료';
COMMENT ON COLUMN office_registration_evidence.object_key IS '마스킹 검사를 마친 비공개 객체 스토리지 키';
COMMENT ON COLUMN office_registration_evidence.uploaded_at IS '파일 접수 시각';
COMMENT ON TABLE office_registration_status_history IS '사업자 인증 신청 심사 이력이다. 내부 처리목표는 2영업일이며 법정 기한은 아니다';
COMMENT ON COLUMN office_registration_status_history.id IS '사업자 인증 상태 이력 내부 식별자';
COMMENT ON COLUMN office_registration_status_history.registration_id IS '대상 신청';
COMMENT ON COLUMN office_registration_status_history.from_status IS '변경 전 상태';
COMMENT ON COLUMN office_registration_status_history.to_status IS '변경 후 상태';
COMMENT ON COLUMN office_registration_status_history.changed_by_type IS '변경 주체다. APPLICANT는 신청자 본인, OPERATOR는 운영자, SYSTEM은 배치·자동 처리다';
COMMENT ON COLUMN office_registration_status_history.changed_by_operator_id IS '변경을 처리한 운영자';
COMMENT ON COLUMN office_registration_status_history.reason IS '사유';
COMMENT ON COLUMN office_registration_status_history.created_at IS '생성 일시';
COMMENT ON TABLE office_membership IS '사용자와 사무소의 소속·역할이다. OWNER는 대표를 뜻하며 사무소당 정확히 1명만 APPROVED 상태를 가질 수 있다. 대표 이전은 office_owner_transfer 트랜잭션으로 원자적으로 교체한다. PENDING 상태에서는 AGENT나 DEPUTY로만 참여를 요청할 수 있다. OWNER는 사업자 인증 승인이나 대표이전으로만 생긴다';
COMMENT ON COLUMN office_membership.id IS '사무소 소속 내부 식별자';
COMMENT ON COLUMN office_membership.office_id IS '소속 사무소';
COMMENT ON COLUMN office_membership.user_id IS '대상 사용자';
COMMENT ON COLUMN office_membership.role IS 'OWNER는 대표이며 사무소당 1명이다. AGENT는 소속공인중개사, DEPUTY는 중개보조원이다. 법정 신분인 자격 보유 여부와 이 시스템의 권한은 별도 개념이다. employment_roster의 자격정보를 기준으로 무자격자에게 OWNER·AGENT 권한을 부여하지 않는다. 이 검증은 서비스 계층이 수행한다';
COMMENT ON COLUMN office_membership.status IS 'APPROVED는 승인, PENDING은 승인 대기, REJECTED는 거절, REVOKED는 회수, CANCELLED는 신청자 취소, SUSPENDED는 접근정지, EXPIRED는 기한이 지난 승인 대기를 배치가 정리한 상태다. SUSPENDED는 내보내짐 이전 단계다';
COMMENT ON COLUMN office_membership.request_source IS 'REQUEST는 본인 참여 신청, INVITE는 대표 초대, REGISTRATION은 사업자 인증 승인, TRANSFER는 대표 이전이다';
COMMENT ON COLUMN office_membership.invitation_accepted_at IS '초대 대상 사용자가 수락한 시각이다. INVITE가 아니면 NULL이다';
COMMENT ON COLUMN office_membership.invitation_expires_at IS 'request_source가 INVITE이고 PENDING일 때 발급·재발송 시각에 7×24시간을 더해 채우는 초대 만료 시각이다. INVITE가 아니면 NULL이다. 참여 요청의 30일 만료는 created_at에 30일을 더해 계산하므로 컬럼을 두지 않는다';
COMMENT ON COLUMN office_membership.qualification_number IS 'AGENT 참여 신청이나 초대 수락 때 입력한 자격증 번호다. 대표가 승인 전에 확인하며 구성원 목록과 상세 응답에 싣는다. 사업자 인증 승인과 대표 이전 경로의 OWNER 행은 NULL을 허용한다';
COMMENT ON COLUMN office_membership.employment_report_confirmed IS '참여 신청이나 초대 수락 때 입력한 고용신고 확인 값이다. OWNER 행은 NULL을 허용한다';
COMMENT ON COLUMN office_membership.training_confirmed IS '참여 신청이나 초대 수락 때 입력한 필요 교육 이수 확인 값이다. OWNER 행은 NULL을 허용한다';
COMMENT ON COLUMN office_membership.approved_at IS '승인 처리 일시';
COMMENT ON COLUMN office_membership.rejection_reason IS '거절 사유';
COMMENT ON COLUMN office_membership.revoked_at IS '폐기 일시';
COMMENT ON COLUMN office_membership.revocation_reason IS '회수 사유';
COMMENT ON COLUMN office_membership.revoked_by_type IS '소속을 해제한 주체다. SELF는 본인 나가기, OWNER는 대표의 내보내기, SYSTEM은 배치·자동 처리다. REVOKED에서만 값이 있다. 응답의 removalReason에서 RESIGNED와 REMOVED를 구분하는 근거이며 SUSPENDED는 status로 판정한다';
COMMENT ON COLUMN office_membership.cancelled_at IS '취소 처리 일시';
COMMENT ON COLUMN office_membership.resolved_at IS '해결 처리 일시';
COMMENT ON COLUMN office_membership.suspended_at IS '정지 처리 일시';
COMMENT ON COLUMN office_membership.suspension_reason IS '정지 사유';
COMMENT ON COLUMN office_membership.expired_at IS '기한이 지난 PENDING을 배치가 EXPIRED로 정리한 일시다. EXPIRED에서만 값이 있다';
COMMENT ON COLUMN office_membership.created_at IS '생성 일시';
COMMENT ON INDEX uq_office_membership_active IS '같은 사무소·사용자 조합의 중복 행을 막는다. EXPIRED는 막지 않아 만료 후 새 요청을 만들 수 있다. REJECTED는 resolved_at이 채워지면(재신청 시작) 더 이상 막지 않아 새 행을 만들 수 있다. REVOKED는 항상 막는다: 회수는 재신청 개념이 없다. CANCELLED(신청자 취소)는 막지 않아 바로 재신청할 수 있다';
COMMENT ON INDEX uq_office_single_owner IS '사무소당 APPROVED 상태의 OWNER는 정확히 1명이다. 마지막 대표는 직접 강등하거나 내보낼 수 없다. 이 규칙은 서비스 계층이 강제한다. 교체는 office_owner_transfer 트랜잭션으로만 한다';
COMMENT ON COLUMN office_membership.withdrawn_alias_no IS '회원 탈퇴 때 사무소 안에서 매기는 대체 표시 번호다. 업무 기록의 담당자는 탈퇴한 구성원 뒤에 이 번호를 붙여 표시한다. 같은 사람의 같은 사무소 소속 행은 같은 번호를 쓴다';
COMMENT ON TABLE office_membership_status_history IS '소속 상태 변경 이력이다. 역할 변경, 정지, 내보내기가 일어나면 진행 중인 고객·매물·업무·계약의 담당자는 대표에게 인계된다. 과거 담당 기록은 이 이력과 별개로 원본 그대로 유지한다. 이 인계 처리는 서비스 계층이 수행한다. 본인 나가기는 to_status가 REVOKED이고 changed_by_type이 APPLICANT인 행으로 기록한다. 기한이 지난 승인 대기를 정리하는 EXPIRED 전이는 changed_by_type이 SYSTEM이다';
COMMENT ON COLUMN office_membership_status_history.id IS '사무소 소속 상태 이력 내부 식별자';
COMMENT ON COLUMN office_membership_status_history.membership_id IS '연결된 소속';
COMMENT ON COLUMN office_membership_status_history.from_status IS '변경 전 상태';
COMMENT ON COLUMN office_membership_status_history.to_status IS '변경 후 상태';
COMMENT ON COLUMN office_membership_status_history.changed_by_type IS '변경 주체다. APPLICANT는 신청자 본인, OWNER는 대표, SYSTEM은 배치·자동 처리다';
COMMENT ON COLUMN office_membership_status_history.changed_by_membership_id IS '변경을 실행한 담당자';
COMMENT ON COLUMN office_membership_status_history.reason IS '사유';
COMMENT ON COLUMN office_membership_status_history.created_at IS '생성 일시';
COMMENT ON TABLE employment_roster IS '계정 유무와 분리해 관리하는 고용명부다. 계정이 없는 고용인도 membership_id를 NULL로 두고 기록한다. 이렇게 해야 보조원 5배 한도의 분모인 자격보유 고용인원을 정확히 계산할 수 있다. 유료 과금 인원은 office_membership 기준으로 세고, 이 명부와는 별개로 카운트한다';
COMMENT ON COLUMN employment_roster.id IS '고용명부 내부 식별자';
COMMENT ON COLUMN employment_roster.office_id IS '소속 사무소';
COMMENT ON COLUMN employment_roster.membership_id IS '연결된 소속';
COMMENT ON COLUMN employment_roster.person_name IS '고용인 이름';
COMMENT ON COLUMN employment_roster.legal_qualification IS 'AGENT는 자격을 보유한 개업·소속공인중개사다. DEPUTY는 무자격인 중개보조원이다. 5배 한도의 분모는 AGENT 행 수다';
COMMENT ON COLUMN employment_roster.employment_start_date IS '고용 시작일';
COMMENT ON COLUMN employment_roster.employment_end_date IS '고용 종료일';
COMMENT ON COLUMN employment_roster.confirmation_source IS '고용 사실의 확인 출처: 등록관청 신고서류 대조 또는 수기입력';
COMMENT ON COLUMN employment_roster.created_at IS '생성 일시';
COMMENT ON TABLE office_owner_transfer IS '대표 이전이다. 완료 직전에 대상의 활성 소속, 자격, 등록관계, 사무소 종료 여부를 재검사한다. 이 재검사는 서비스 계층이 수행한다. 운영자가 승인하면 단일 트랜잭션으로 기존 대표를 소속공인중개사로 전환하거나 소속을 해제하고, 새 대표를 office_membership.role=OWNER로 교체한다. 이전, 사무소종료, 대상퇴사는 직렬화해 동시성을 제어한다. 이 동시성 제어도 서비스 계층이 수행한다. 수락은 곧바로 UNDER_REVIEW 전이로 처리하므로 ACCEPTED 상태는 두지 않고 수락 시각은 accepted_at에 남긴다';
COMMENT ON COLUMN office_owner_transfer.id IS '대표 이전 내부 식별자';
COMMENT ON COLUMN office_owner_transfer.office_id IS '소속 사무소';
COMMENT ON COLUMN office_owner_transfer.from_membership_id IS '이전 전 대표 소속';
COMMENT ON COLUMN office_owner_transfer.to_membership_id IS '이전 후 대표 소속';
COMMENT ON COLUMN office_owner_transfer.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN office_owner_transfer.requested_at IS '요청 일시';
COMMENT ON COLUMN office_owner_transfer.accept_deadline_at IS '수락 기한';
COMMENT ON COLUMN office_owner_transfer.accepted_at IS '수락 처리 일시';
COMMENT ON COLUMN office_owner_transfer.completed_at IS '완료 처리 일시';
COMMENT ON COLUMN office_owner_transfer.rejected_reason IS '거절 사유';
COMMENT ON COLUMN office_owner_transfer.rejected_at IS '거절 처리 일시다. REJECTED에서만 값이 있고 거절 사유는 rejected_reason에 둔다';
COMMENT ON COLUMN office_owner_transfer.withdrawn_at IS '철회 처리 일시';
COMMENT ON INDEX uq_office_owner_transfer_pending IS '사무소당 진행 중인 대표 이전은 동시에 1건만이다. 수락하면 곧바로 UNDER_REVIEW로 전이하므로 PENDING과 UNDER_REVIEW가 진행 중 상태다';
COMMENT ON TABLE office_change_request IS '주소, 등록관계, 대표자 등 재인증이 필요한 사무소 정보 변경 신청이다. 단순 연락처 변경은 즉시 반영되므로 이 테이블을 거치지 않는다. 대표만 신청할 수 있다. 이 권한 검사는 서비스 계층이 수행한다';
COMMENT ON COLUMN office_change_request.id IS '사무소 정보 변경 신청 내부 식별자';
COMMENT ON COLUMN office_change_request.office_id IS '소속 사무소';
COMMENT ON COLUMN office_change_request.requested_by_membership_id IS '신청한 대표';
COMMENT ON COLUMN office_change_request.change_type IS '변경 종류';
COMMENT ON COLUMN office_change_request.requested_values IS '변경 요청 값';
COMMENT ON COLUMN office_change_request.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN office_change_request.reviewed_at IS '심사 처리 일시';
COMMENT ON COLUMN office_change_request.rejection_reason IS '거절 사유';
COMMENT ON COLUMN office_change_request.created_at IS '생성 일시';
COMMENT ON TABLE property_category IS '매물 카테고리다. office_id가 NULL인 기본 10종은 is_system=true이며 명칭과 코드가 불변이다. 사무소별 커스텀 카테고리는 사무소당 활성 20개까지 허용한다. 이 상한은 서비스 계층이 강제한다';
COMMENT ON COLUMN property_category.id IS '매물 카테고리 내부 식별자';
COMMENT ON COLUMN property_category.office_id IS '소속 사무소';
COMMENT ON COLUMN property_category.code IS '기본 10종의 코드는 COMMERCIAL_BUILDING, LAND, RETAIL_OFFICE, FACTORY_WAREHOUSE, DETACHED_MULTI, APARTMENT, OFFICETEL, ROWHOUSE_MULTI, LODGING, PRESALE_RIGHT다';
COMMENT ON COLUMN property_category.name IS '이름';
COMMENT ON COLUMN property_category.is_system IS '기본 카테고리 여부';
COMMENT ON COLUMN property_category.active IS '활성 여부';
COMMENT ON COLUMN property_category.created_at IS '생성 일시';
COMMENT ON INDEX uq_property_category_system_code IS '기본 카테고리 코드는 전역에서 유일하다. office_id가 NULL이면 일반 UNIQUE 제약으로 검증되지 않으므로 부분 인덱스로 보강한다';
COMMENT ON TABLE property_custom_field_definition IS '카테고리별 추가 입력 항목 정의다. 카테고리당 활성 필드는 50개까지 허용한다. 이 상한은 서비스 계층이 강제한다. 데이터가 있는 필드는 타입 변경과 물리삭제를 금지하고 active=false로만 비활성화한다. 기본 10종 전용 필드는 시스템이 office_id가 NULL인 행으로 시드하며 number_kind, unit, min_value, max_value를 시스템이 정하고 바꿀 수 없다. 시드 값은 개수형 필드 INTEGER, 단위 층·원·m·kW·%, 전용률 0 이상 100 이하, 분양권 프리미엄 min_value NULL, 그 밖의 기본 숫자 필드 min_value 0이다. 사무소가 추가한 NUMBER 필드는 number_kind가 DECIMAL이고 unit, min_value, max_value는 NULL이다';
COMMENT ON COLUMN property_custom_field_definition.id IS '매물 커스텀 필드 정의 내부 식별자';
COMMENT ON COLUMN property_custom_field_definition.category_id IS '대상 카테고리';
COMMENT ON COLUMN property_custom_field_definition.office_id IS '소속 사무소. NULL이면 기본 10종 카테고리의 시스템 전용 필드다';
COMMENT ON COLUMN property_custom_field_definition.field_name IS '필드 이름';
COMMENT ON COLUMN property_custom_field_definition.field_type IS '필드 타입';
COMMENT ON COLUMN property_custom_field_definition.number_kind IS 'NUMBER 타입에서 정수만 받는지 소수도 받는지를 나타내는 INTEGER 또는 DECIMAL이다. NUMBER가 아니면 NULL이다. 기본 10종 전용 필드의 개수형은 INTEGER이고 사무소가 추가한 NUMBER 필드는 DECIMAL이다';
COMMENT ON COLUMN property_custom_field_definition.unit IS '입력창에 붙여 보여주는 단위다. 층, 원, m, kW, % 등이며 단위가 없으면 NULL이다. 사무소가 추가한 필드는 NULL이다';
COMMENT ON COLUMN property_custom_field_definition.min_value IS 'NUMBER 타입의 입력 가능한 최솟값이다. NULL이면 하한이 없다. 기본 10종 전용 필드는 분양권 프리미엄만 NULL이라 음수를 받고 그 밖의 기본 숫자 필드는 0이다. 사무소가 추가한 필드는 NULL이다';
COMMENT ON COLUMN property_custom_field_definition.max_value IS 'NUMBER 타입의 입력 가능한 최댓값이다. NULL이면 상한이 없다. 상가·사무실 전용률은 100이고 그 밖의 필드는 NULL이다';
COMMENT ON COLUMN property_custom_field_definition.active IS '활성 여부';
COMMENT ON COLUMN property_custom_field_definition.created_at IS '생성 일시';
COMMENT ON TABLE property IS '매물 자체 정보다. 임시저장 상태인 DRAFT는 매물명과 카테고리만 있으면 된다. 활성등록 상태인 ACTIVE로 전환하려면 주소와 담당 공인중개사가 필수다. 방문확정이나 계약연결 이전에 이 정보를 보완한다. 담당자가 실제로 공인중개사 자격인 OWNER나 AGENT를 가졌는지는 서비스 계층이 검사한다. 중개보조원이 배정된 방문에서 최소 정보만 보는 규칙과는 별개다';
COMMENT ON COLUMN property.id IS '매물 내부 식별자';
COMMENT ON COLUMN property.office_id IS '소속 사무소';
COMMENT ON COLUMN property.category_id IS '대상 카테고리';
COMMENT ON COLUMN property.name IS '이름';
COMMENT ON COLUMN property.address IS '주소';
COMMENT ON COLUMN property.address_detail IS '상세주소';
COMMENT ON COLUMN property.exclusive_area_sqm IS '전용면적 제곱미터';
COMMENT ON COLUMN property.supply_area_sqm IS '공급면적 제곱미터';
COMMENT ON COLUMN property.land_area_sqm IS '대지면적 제곱미터';
COMMENT ON COLUMN property.gross_floor_area_sqm IS '연면적 제곱미터';
COMMENT ON COLUMN property.move_in_date IS '입주 가능일. 협의인 경우 NULL로 두고 move_in_negotiable을 true로 설정한다';
COMMENT ON COLUMN property.move_in_negotiable IS '입주 가능일을 협의로 정했는지 여부';
COMMENT ON COLUMN property.maintenance_fee_amount IS '관리비 금액 원 단위';
COMMENT ON COLUMN property.maintenance_fee_items IS '관리비 포함 항목 설명';
COMMENT ON COLUMN property.occupancy_status IS 'VACANT 공실, OWNER_OCCUPIED 소유자 거주, TENANT_OCCUPIED 임차인 거주, UNKNOWN 미확인';
COMMENT ON COLUMN property.description IS '매물 설명';
COMMENT ON COLUMN property.memo IS '사무소 내부 매물 메모';
COMMENT ON COLUMN property.reference_lease_end_date IS '계약이 없을 때만 표시하는 출처 확인 참고 만기일';
COMMENT ON COLUMN property.reference_lease_end_source IS '참고 만기일의 확인 출처';
COMMENT ON COLUMN property.managing_membership_id IS '담당자 소속';
COMMENT ON COLUMN property.duplicate_override_reason IS '같은 주소나 호실이 중복 경고를 받았지만 다른 권리·거래단위로 판단해 별도 등록할 때의 사유';
COMMENT ON COLUMN property.registration_stage IS '등록 단계';
COMMENT ON COLUMN property.created_at IS '생성 일시';
COMMENT ON COLUMN property.updated_at IS '마지막 수정 일시';
COMMENT ON COLUMN property.deleted_at IS '현재 보관 중이면 마지막 보관 전환 시각이고 복원하면 NULL이다. 이전 보관·복원 사건은 entity_lifecycle_event에 보존한다. 진행 중인 방문이나 유효한 계약이 있으면 보관 전에 재배정, 취소, 연결확인이 필요하다. 참조가 없는 DRAFT 매물만 물리 삭제할 수 있다';
COMMENT ON TABLE property_field_value IS '매물별 커스텀 필드 값이다. 필드 타입에 맞는 value_* 컬럼 하나만 채운다. 매물의 카테고리가 바뀌어도 기존 값은 삭제하지 않는다. is_archived=true로 표시해 이전 카테고리 값으로 보관한다. value_* 컬럼은 모두 NULL을 허용한다. 값을 null로 비우는 요청은 서비스 계층이 해당 행을 삭제해 처리한다';
COMMENT ON COLUMN property_field_value.id IS '매물 커스텀 필드 값 내부 식별자';
COMMENT ON COLUMN property_field_value.property_id IS '대상 매물';
COMMENT ON COLUMN property_field_value.field_definition_id IS '대상 커스텀 필드 정의';
COMMENT ON COLUMN property_field_value.value_text IS '텍스트 타입 값';
COMMENT ON COLUMN property_field_value.value_number IS '숫자 타입 값';
COMMENT ON COLUMN property_field_value.value_boolean IS '참거짓 타입 값';
COMMENT ON COLUMN property_field_value.value_date IS '날짜 타입 값';
COMMENT ON COLUMN property_field_value.is_archived IS '보관 여부';
COMMENT ON COLUMN property_field_value.created_at IS '생성 일시';
COMMENT ON TABLE property_photo IS '매물 사진이다. 매물당 최대 20장, 장당 10MB, JPG·PNG·WebP 형식만 허용한다. 업로드 시 EXIF 위치정보를 서버에서 제거한다. 이 제거 처리는 서비스 계층이 수행한다';
COMMENT ON COLUMN property_photo.id IS '매물 사진 내부 식별자';
COMMENT ON COLUMN property_photo.property_id IS '대상 매물';
COMMENT ON COLUMN property_photo.object_key IS '스토리지 객체 키';
COMMENT ON COLUMN property_photo.description IS '사진 설명';
COMMENT ON COLUMN property_photo.sort_order IS '정렬 순서';
COMMENT ON COLUMN property_photo.created_at IS '생성 일시';
COMMENT ON TABLE property_offer IS '매물의 매매·전세·월세 거래제안이다. 유형별로 독립된 가격과 상태를 갖는다. 거래가능이나 협의중 상태인 활성 제안은 유형당 1개만 허용한다. 한 유형이 거래완료돼도 다른 유형의 제안은 자동으로 취소되지 않는다. 유형마다 독립적으로 전이한다';
COMMENT ON COLUMN property_offer.id IS '매물 거래제안 내부 식별자';
COMMENT ON COLUMN property_offer.property_id IS '대상 매물';
COMMENT ON COLUMN property_offer.deal_type IS '거래유형';
COMMENT ON COLUMN property_offer.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN property_offer.sale_price IS '매매가';
COMMENT ON COLUMN property_offer.deposit_amount IS '보증금';
COMMENT ON COLUMN property_offer.monthly_rent_amount IS '월세';
COMMENT ON COLUMN property_offer.premium_amount IS '거래제안에서 합의한 프리미엄이다. 분양권 매물 전용 필드 프리미엄과는 별개의 값이다. 분양권 카테고리 매물에서만 음수를 허용한다. 이 검증은 서비스 계층이 수행한다';
COMMENT ON COLUMN property_offer.created_at IS '생성 일시';
COMMENT ON COLUMN property_offer.updated_at IS '마지막 수정 일시';
COMMENT ON TABLE customer IS '사무소가 관리하는 고객이다. 수요 고객, 소유자, 점유자, 기타 역할은 이 표를 참조하는 다른 테이블의 존재 여부로 판단하며 별도 role 컬럼을 두지 않는다. 참조 없는 오입력은 물리 삭제하고 참조 있는 행은 보관·복원한다. 주민등록번호나 전체 금융계좌 등 민감정보는 일반 필드에 입력하지 않는다. 이 검증은 서비스 계층이 수행한다. 동일 이름과 전화번호만으로는 자동 병합하지 않는다';
COMMENT ON COLUMN customer.id IS '고객 내부 식별자';
COMMENT ON COLUMN customer.office_id IS '소속 사무소';
COMMENT ON COLUMN customer.is_corporation IS '법인 여부';
COMMENT ON COLUMN customer.name IS '이름';
COMMENT ON COLUMN customer.managing_membership_id IS '담당 대표 또는 소속공인중개사 소속 ID. 승인 상태와 자격은 서비스에서 검증한다';
COMMENT ON COLUMN customer.phone IS '연락처';
COMMENT ON COLUMN customer.secondary_phone IS '보조 연락처';
COMMENT ON COLUMN customer.email IS '이메일';
COMMENT ON COLUMN customer.memo IS '고객 업무 메모. 민감정보와 전체 금융계좌는 입력하지 않는다';
COMMENT ON COLUMN customer.data_source IS '정보를 받은 경로다. 방문상담, 전화문의, 지인소개처럼 사무소가 적는다. 법적 처리 근거는 processing_basis가 가진다. 개인정보 처리방침과 연동하는 메타데이터다';
COMMENT ON COLUMN customer.data_purpose IS '정보수집 목적';
COMMENT ON COLUMN customer.retention_until IS '개인정보 보유기한';
COMMENT ON COLUMN customer.deleted_at IS '현재 보관 중이면 마지막 보관 전환 시각이고 복원하면 NULL이다. 이전 보관·복원 사건은 entity_lifecycle_event에 보존한다';
COMMENT ON COLUMN customer.created_at IS '생성 일시';
COMMENT ON COLUMN customer.processing_basis IS '사무소가 이 고객 정보를 처리하는 근거로 고른 값이다. 새로 등록하는 고객은 UNSPECIFIED를 쓸 수 없고 서비스 계층이 거절한다. 이 컬럼을 추가하기 전의 행만 UNSPECIFIED다';
COMMENT ON TABLE entity_lifecycle_event IS '매물·고객 생성·보관·복원과 매물 카테고리 변경의 추가 전용 사건이다. 각 명령은 대상 행 변경과 사건 삽입을 같은 트랜잭션에서 처리한다. 정정은 기존 행을 덮지 않고 supersedes_event_id가 가리키는 사건을 대체한다. 집계 시 대체된 행은 제외한다. 물리 삭제된 참조 없는 오입력의 사건은 함께 삭제한다';
COMMENT ON COLUMN entity_lifecycle_event.id IS '사건 내부 식별자';
COMMENT ON COLUMN entity_lifecycle_event.office_id IS '대상 사무소';
COMMENT ON COLUMN entity_lifecycle_event.entity_type IS 'PROPERTY는 매물, CUSTOMER는 고객';
COMMENT ON COLUMN entity_lifecycle_event.property_id IS '매물 사건이면 대상 매물 ID';
COMMENT ON COLUMN entity_lifecycle_event.customer_id IS '고객 사건이면 대상 고객 ID';
COMMENT ON COLUMN entity_lifecycle_event.event_type IS '생성 CREATED, 보관 ARCHIVED, 복원 RESTORED, 매물 카테고리 변경 CATEGORY_CHANGED';
COMMENT ON COLUMN entity_lifecycle_event.creation_source IS 'CREATED 사건이 직접 입력으로 생겼는지 데이터 이전으로 생겼는지 구분한다. MANUAL은 직접 입력, IMPORT는 이전 실행이 만든 CREATED 사건이다. CREATED가 아닌 사건은 항상 MANUAL이다. 상세 내역의 isMigrated와 월말결산의 이전 등록 수가 이 값을 쓴다';
COMMENT ON COLUMN entity_lifecycle_event.previous_category_id IS '카테고리 변경 직전 카테고리';
COMMENT ON COLUMN entity_lifecycle_event.new_category_id IS '카테고리 변경 직후 카테고리';
COMMENT ON COLUMN entity_lifecycle_event.effective_at IS '집계에 적용하는 실제 효력시각';
COMMENT ON COLUMN entity_lifecycle_event.recorded_at IS '사건이 데이터베이스에 기록된 시각';
COMMENT ON COLUMN entity_lifecycle_event.recorded_by_membership_id IS '사건을 입력한 사무소 소속. 시스템 이력은 NULL이다';
COMMENT ON COLUMN entity_lifecycle_event.correction_reason IS '과거 효력시각을 정정할 때 남기는 사유';
COMMENT ON COLUMN entity_lifecycle_event.supersedes_event_id IS '정정으로 대체되는 기존 사건 ID. 같은 대상·사건 유형인지 서비스에서 검사한다';
COMMENT ON TABLE property_owner_occupant IS '매물의 소유자·점유자 연결이다. 현재 점유 또는 소유 여부는 조회 시점에 start_date가 오늘 이하이고 end_date가 NULL이거나 오늘 이상인 조건으로 계산한다. 미래 시작일은 화면에서 예정계약으로 별도 표시한다. 이 계산과 표시는 서비스 계층이 수행한다. 계약 체결만으로 이 표가 자동 갱신되지 않는다. 담당자가 수동으로 확인하고 갱신한다';
COMMENT ON COLUMN property_owner_occupant.id IS '매물 소유자·점유자 연결 내부 식별자';
COMMENT ON COLUMN property_owner_occupant.office_id IS '소속 사무소';
COMMENT ON COLUMN property_owner_occupant.property_id IS '대상 매물';
COMMENT ON COLUMN property_owner_occupant.customer_id IS '대상 고객';
COMMENT ON COLUMN property_owner_occupant.role IS '역할';
COMMENT ON COLUMN property_owner_occupant.start_date IS '시작일';
COMMENT ON COLUMN property_owner_occupant.end_date IS '종료일';
COMMENT ON COLUMN property_owner_occupant.confirmed_by_membership_id IS '확인한 담당자';
COMMENT ON COLUMN property_owner_occupant.confirmed_at IS '확인 처리 일시';
COMMENT ON COLUMN property_owner_occupant.created_at IS '생성 일시';
COMMENT ON TABLE customer_property_interest IS '고객이 관심을 표한 매물과 그 관계의 유효기간이다. 소유·점유 관계나 계약 당사자 관계로 간주하지 않는다';
COMMENT ON COLUMN customer_property_interest.id IS '관심 관계 내부 식별자';
COMMENT ON COLUMN customer_property_interest.office_id IS '고객과 매물이 속한 사무소';
COMMENT ON COLUMN customer_property_interest.customer_id IS '관심 고객';
COMMENT ON COLUMN customer_property_interest.property_id IS '관심 매물';
COMMENT ON COLUMN customer_property_interest.start_date IS '관심 관계 시작일';
COMMENT ON COLUMN customer_property_interest.end_date IS '관심 관계 종료일';
COMMENT ON COLUMN customer_property_interest.note IS '관심 관계 메모';
COMMENT ON COLUMN customer_property_interest.created_at IS '관심 관계 기록시각';
COMMENT ON TABLE customer_demand_condition IS '수요 고객의 희망조건이다. 후보 추천은 이 조건으로 매물을 필터링할 뿐 적합성을 보증하지 않는다. 단순 필터 쿼리이며 매칭 알고리즘은 두지 않는다';
COMMENT ON COLUMN customer_demand_condition.id IS '고객 희망조건 내부 식별자';
COMMENT ON COLUMN customer_demand_condition.customer_id IS '대상 고객';
COMMENT ON COLUMN customer_demand_condition.deal_type IS '거래유형';
COMMENT ON COLUMN customer_demand_condition.category_id IS '대상 카테고리';
COMMENT ON COLUMN customer_demand_condition.price_min IS '희망 매매가 하한';
COMMENT ON COLUMN customer_demand_condition.price_max IS '희망 매매가 상한';
COMMENT ON COLUMN customer_demand_condition.deposit_min IS '희망 보증금 하한';
COMMENT ON COLUMN customer_demand_condition.deposit_max IS '희망 보증금 상한';
COMMENT ON COLUMN customer_demand_condition.rent_min IS '희망 월세 하한';
COMMENT ON COLUMN customer_demand_condition.rent_max IS '희망 월세 상한';
COMMENT ON COLUMN customer_demand_condition.area_min IS '희망 면적 하한';
COMMENT ON COLUMN customer_demand_condition.area_max IS '희망 면적 상한';
COMMENT ON COLUMN customer_demand_condition.move_in_date IS '입주 희망일';
COMMENT ON COLUMN customer_demand_condition.created_at IS '생성 일시';
COMMENT ON TABLE customer_demand_region IS '희망조건 하나에 딸린 복수 희망 지역';
COMMENT ON COLUMN customer_demand_region.id IS '희망 지역 내부 식별자';
COMMENT ON COLUMN customer_demand_region.demand_condition_id IS '소속 희망조건';
COMMENT ON COLUMN customer_demand_region.region_name IS '희망 지역명';
COMMENT ON TABLE customer_consultation IS '상담이력이다. 고객 등록이나 데이터 이전 자체는 문의 발생으로 간주하지 않으며 자동 생성하지 않는다. 이 규칙은 서비스 계층이 강제한다';
COMMENT ON COLUMN customer_consultation.id IS '상담 내부 식별자';
COMMENT ON COLUMN customer_consultation.customer_id IS '대상 고객';
COMMENT ON COLUMN customer_consultation.occurred_at IS '발생 일시';
COMMENT ON COLUMN customer_consultation.author_membership_id IS '작성한 담당자. 요청 입력이 아니라 로그인한 구성원으로 서버가 채운다';
COMMENT ON COLUMN customer_consultation.content IS '내용';
COMMENT ON COLUMN customer_consultation.consultation_type IS '상담 종류';
COMMENT ON COLUMN customer_consultation.created_at IS '생성 일시';
COMMENT ON COLUMN customer_consultation.updated_at IS '마지막 수정시각';
COMMENT ON COLUMN customer_consultation.version IS '낙관적 잠금 버전';
COMMENT ON INDEX uq_customer_first_inquiry IS '최초문의는 고객별로 정확히 1건이다. 고객을 병합할 때 두 최초문의가 충돌하면 대표가 1건을 지정하고 통계를 재계산한다. 이 처리는 서비스 계층이 수행한다';
COMMENT ON TABLE customer_consultation_revision IS '상담 수정 전 값을 남기는 이력이다. 상담 본문을 수정할 때 이전 값과 수정 사유를 같은 트랜잭션에 기록한다. 개인정보 파기 대상이면 원문 이력도 함께 파기한다';
COMMENT ON COLUMN customer_consultation_revision.id IS '상담 수정 이력 내부 식별자';
COMMENT ON COLUMN customer_consultation_revision.consultation_id IS '수정한 상담';
COMMENT ON COLUMN customer_consultation_revision.previous_occurred_at IS '수정 전 상담 발생시각';
COMMENT ON COLUMN customer_consultation_revision.previous_content IS '수정 전 상담 내용';
COMMENT ON COLUMN customer_consultation_revision.previous_consultation_type IS '수정 전 최초문의 또는 후속상담 유형';
COMMENT ON COLUMN customer_consultation_revision.correction_reason IS '수정 사유';
COMMENT ON COLUMN customer_consultation_revision.corrected_by_membership_id IS '수정한 사무소 구성원';
COMMENT ON COLUMN customer_consultation_revision.corrected_at IS '수정 기록시각';
COMMENT ON TABLE customer_merge_log IS '고객 병합 이력이다. 대표만 실행할 수 있다. 병합 후 merged_customer_id 고객의 상세 조회는 200 응답으로 status=MERGED와 mergedIntoCustomerId를 돌려준다. 이 응답은 서비스 계층이 처리한다';
COMMENT ON COLUMN customer_merge_log.id IS '고객 병합 내부 식별자';
COMMENT ON COLUMN customer_merge_log.primary_customer_id IS '병합 후 유지되는 고객';
COMMENT ON COLUMN customer_merge_log.merged_customer_id IS '병합되어 사라지는 고객. 고객은 한 번만 병합되어 사라지므로 값이 유일하다. 고객 상세 조회의 status=MERGED 판정과 mergedIntoCustomerId 조회에 쓴다';
COMMENT ON COLUMN customer_merge_log.executed_by_membership_id IS '병합을 실행한 대표';
COMMENT ON COLUMN customer_merge_log.executed_at IS '실행 처리 일시';
COMMENT ON COLUMN customer_merge_log.conflict_resolution_note IS '값 충돌 해결 메모';
COMMENT ON TABLE visit_coordination IS '조율 1건은 수요 고객 1명, 후보 매물 1개에서 20개, 담당자, 방문가능기간으로 구성된다. 후보 매물 20개는 서비스 계층이 강제하는 내부 판단상한이다. 방문가능기간은 현재부터 최대 30일이다. 이 표 하나가 9단계 상태값을 갖는다. 정합화 전에는 8단계였고 APPLYING 신청 진행이 추가됐다. 신청 개체와 신청별 상태는 visit_request가 갖는다. 과거 모델은 매물 1개당 세입자·구매자 응답이 여러 개였는데 이 모델은 그 반대 방향이다';
COMMENT ON COLUMN visit_coordination.id IS '조율 건 내부 식별자';
COMMENT ON COLUMN visit_coordination.office_id IS '소속 사무소';
COMMENT ON COLUMN visit_coordination.customer_id IS '대상 고객';
COMMENT ON COLUMN visit_coordination.manager_membership_id IS '담당자 소속';
COMMENT ON COLUMN visit_coordination.status IS 'TIME_COLLECTING 시간 수집 중, COORDINATABLE 조율 가능, FINAL_CONFIRMATION_REQUIRED 최종 확정 필요, APPLYING 신청 진행, CONFIRMED 확정 완료, RESCHEDULE_REQUIRED 재조율 필요, VISIT_COMPLETED 방문 완료, VISIT_INCOMPLETE 미방문 종료, CANCELLED 취소. FINAL_CONFIRMATION_REQUIRED는 일정 구성이 끝나 매물별 신청 또는 신청 결과에 따른 확정이 필요한 상태다. APPLYING은 하나 이상의 매물에 신청 대기 또는 선택 상태의 신규 신청(대체 대상이 없는 신청)이 있는 상태이며 정합화로 추가한 값이다. 확정 변경 신청은 판정에 넣지 않는다. 모든 대상 매물이 확정되면 CONFIRMED다';
COMMENT ON COLUMN visit_coordination.period_start_date IS '방문가능기간 시작일';
COMMENT ON COLUMN visit_coordination.period_end_date IS '방문가능기간 종료일';
COMMENT ON COLUMN visit_coordination.cancelled_at IS '취소 처리 일시';
COMMENT ON COLUMN visit_coordination.cancel_reason IS '실행 전 전체 취소 사유. 일부 결과 기록 후 남은 예정만 취소하는 경우는 이 컬럼을 쓰지 않고 개별 visit_schedule_item.result로 표현한다';
COMMENT ON COLUMN visit_coordination.reschedule_trigger_type IS '재조율 경보를 일으킨 원인이다. SCHEDULE_CHANGED는 일정 변경, ACCESS_REVOKED는 출입승인 철회, OCCUPANT_CHANGED는 점유자 변경이다. 조율현황이 RESCHEDULE_REQUIRED일 때만 값이 있고 다른 상태로 옮기면 비운다. 상태 전이 사실은 visit_coordination_status_history에 남는다';
COMMENT ON COLUMN visit_coordination.reschedule_reason IS '재조율 경보의 사유 문구다. 조율현황이 RESCHEDULE_REQUIRED일 때만 값이 있고 사유를 받지 못한 경보는 NULL이다';
COMMENT ON COLUMN visit_coordination.reschedule_raised_at IS '재조율 경보가 발생한 시각이다. 조율현황이 RESCHEDULE_REQUIRED일 때만 값이 있다';
COMMENT ON COLUMN visit_coordination.reschedule_approval_id IS '출입승인 철회로 생긴 경보에서 철회된 출입승인이다. reschedule_trigger_type이 ACCESS_REVOKED일 때만 값이 있다. property_access_approval이 이 표보다 뒤에 만들어지므로 FK는 그 표를 만든 뒤에 추가한다';
COMMENT ON COLUMN visit_coordination.created_at IS '생성 일시';
COMMENT ON COLUMN visit_coordination.updated_at IS '마지막 수정 일시';
COMMENT ON TABLE visit_candidate_property IS '조율 건에 담긴 후보 매물이다. 최대 20개 상한은 서비스 계층이 강제한다. 소요시간과 이동시간은 지도 API로 자동계산하지 않고 담당자가 직접 입력한 기본값을 쓴다';
COMMENT ON COLUMN visit_candidate_property.id IS '조율 후보 매물 내부 식별자';
COMMENT ON COLUMN visit_candidate_property.coordination_id IS '소속 조율 건';
COMMENT ON COLUMN visit_candidate_property.office_id IS '소속 사무소';
COMMENT ON COLUMN visit_candidate_property.property_id IS '대상 매물';
COMMENT ON COLUMN visit_candidate_property.sort_order IS '정렬 순서';
COMMENT ON COLUMN visit_candidate_property.visit_duration_minutes IS '방문 소요시간(분)';
COMMENT ON COLUMN visit_candidate_property.travel_duration_minutes IS '이동 소요시간(분)';
COMMENT ON COLUMN visit_candidate_property.property_office_id IS '후보 매물을 가진 사무소다. 자기 사무소 매물이면 office_id와 같고 허용받은 다른 사무소 매물이면 다르다. (property_id, property_office_id) 복합 외래키로 매물의 실제 소유 사무소와 일치를 검증한다. 다른 사무소 매물을 담을 수 있는지는 활성 허용 여부를 서비스 계층이 검사한다';
COMMENT ON TABLE property_access_approval IS '매물별 출입승인자와 유효기간의 버전이다. 출입승인자는 점유자, 소유자, 위임관리인 중 하나다. 공실이어도 출입승인이 필요하며 자동 상시허용은 없다. 승인과 가능시간 등록이 필수라는 이전 서술은 정합화 전 서술이며 정합화 후 가능 시간은 승인자 조건으로 입력한다. source가 PROXY인 대리입력은 확인자와 확인시각을 함께 기록한다. 보유기한이 지나면 행을 지우지 않고 익명화한다. 승인자 조건, 방문 신청, 신청 허용, 승인자 매물 링크, 프로필 연결, 인증 사건이 이 행을 참조하기 때문이다';
COMMENT ON COLUMN property_access_approval.id IS '매물 출입승인 내부 식별자';
COMMENT ON COLUMN property_access_approval.property_id IS '대상 매물';
COMMENT ON COLUMN property_access_approval.approver_type IS '승인자 유형';
COMMENT ON COLUMN property_access_approval.approver_name IS '승인자 이름이다. 익명화하면 NULL이 되며 익명화하지 않은 행은 항상 값이 있다';
COMMENT ON COLUMN property_access_approval.approver_phone IS '승인자 연락처. DIRECT 승인은 필수이고 PROXY 대리입력은 NULL을 허용한다. 익명화하면 DIRECT 승인도 NULL이 된다';
COMMENT ON COLUMN property_access_approval.valid_from IS '유효 시작 시각';
COMMENT ON COLUMN property_access_approval.valid_until IS '유효 종료 시각';
COMMENT ON COLUMN property_access_approval.source IS '입력·전이 출처';
COMMENT ON COLUMN property_access_approval.recorded_by_membership_id IS '기록한 담당자';
COMMENT ON COLUMN property_access_approval.confirmed_at IS '대리입력(PROXY)에서 담당자가 승인자에게 확인을 받은 실제 시각이다. PROXY일 때만 값이 있고 확인한 담당자는 recorded_by_membership_id다';
COMMENT ON COLUMN property_access_approval.recorded_at IS '기록 일시';
COMMENT ON COLUMN property_access_approval.revoked_at IS '실제 출입승인 철회 시각';
COMMENT ON COLUMN property_access_approval.revocation_reason IS '철회 사실의 접수 사유';
COMMENT ON COLUMN property_access_approval.revocation_recorded_at IS '철회 사실을 시스템에 기록한 시각';
COMMENT ON COLUMN property_access_approval.revoked_by_user_id IS '철회 사실을 기록한 사용자. 반환권한자는 활성 소속 없이 사용자로 식별한다';
COMMENT ON COLUMN property_access_approval.approval_role IS '승인 역할이다. PRIMARY는 대표 승인자로 조건 등록과 신청 선택 권한을 가지고 CO_APPROVER는 공동 승인자로 활성 조건과 확정 일정을 읽기만 한다. 한 매물에 같은 기간 유효한 PRIMARY 출입승인은 하나이며 서비스 계층이 매물 행을 잠근 뒤 검사한다';
COMMENT ON COLUMN property_access_approval.approver_phone_hash IS '승인자 연락처를 정규화한 번호의 HMAC-SHA256 해시다. 승인자 계정 연결 판정에만 쓰며 응답에 넣지 않는다. 연락처가 없는 대리입력 출입승인은 NULL이다. 익명화하면 NULL이 된다';
COMMENT ON COLUMN property_access_approval.retention_until IS '승인자 이름·연락처를 지워 익명화하고 승인자 조건의 입력 계정 연결을 끊는 날이다. 이 날은 행 삭제일이 아니라 익명화 처리일이다. 출입승인이 끝난 날 또는 철회한 날에 GUEST_INPUT_AFTER_APPROVAL_END 일수를 더해 서비스 계층이 정한다';
COMMENT ON COLUMN property_access_approval.anonymized_at IS '익명화한 시각이다. 값이 있으면 이름, 연락처, 연락처 해시가 비어 있고 철회했거나 유효 종료 시각이 지난 출입승인이다. 출입승인 행은 지우지 않으므로 승인자 조건, 방문 신청, 신청 허용, 승인자 매물 링크, 프로필 연결, 인증 사건이 이 행을 계속 참조한다';
COMMENT ON CONSTRAINT ck_property_access_approval_anonymized ON property_access_approval IS '익명화한 행만 이름이 비어 있고 익명화한 행은 연락처와 연락처 해시가 비어 있으며 철회했거나 유효 종료 시각이 지난 행이다';
COMMENT ON TABLE property_access_time_slot IS '출입승인 버전에 딸린 가능 시간대. 같은 승인·유효기간이면 여러 조율 건이 재사용할 수 있다. 정합화 전 구조이며 정합화 후 출입승인 요청의 timeSlots[]는 저장하지 않고 가능 시간은 승인자 조건이 정한다';
COMMENT ON COLUMN property_access_time_slot.id IS '출입 가능 시간대 내부 식별자';
COMMENT ON COLUMN property_access_time_slot.approval_id IS '대상 출입승인';
COMMENT ON COLUMN property_access_time_slot.starts_at IS '시작 시각';
COMMENT ON COLUMN property_access_time_slot.ends_at IS '종료 시각';
COMMENT ON TABLE visit_customer_link IS '조율당 1개인 고객용 공개 링크다. 토큰 원문은 저장하지 않고 해시만 저장한다. 응답기한은 담당자 입력 없이 서버가 정하며 첫 방문 후보 시각 24시간 전이고 후보가 이미 24시간 이내이면 발급 후 6시간이다. 만료는 발급 후 7일과 응답기한 중 더 빠른 시각이다. 이 규칙에 따라 expires_at은 발급 시점에 서비스 계층이 계산해 저장하며 응답기한용 컬럼은 따로 없다. 조율 상세 응답의 customerLink는 issued_at, expires_at, revoked_at으로 채운다. 재발급, 취소, 담당변경, 접근중단이 일어나면 이전 토큰의 revoked_at을 채워 폐기하고 새 행을 추가한다';
COMMENT ON COLUMN visit_customer_link.id IS '고객 공개 링크 내부 식별자';
COMMENT ON COLUMN visit_customer_link.coordination_id IS '소속 조율 건';
COMMENT ON COLUMN visit_customer_link.token_hash IS '토큰 원문의 해시';
COMMENT ON COLUMN visit_customer_link.issued_at IS '발급 일시';
COMMENT ON COLUMN visit_customer_link.expires_at IS '발급 후 7일과 응답기한 중 더 빠른 시각. 응답기한은 담당자 입력 없이 서버가 정하며 첫 방문 후보 시각 24시간 전이고 후보가 이미 24시간 이내이면 발급 후 6시간이다';
COMMENT ON COLUMN visit_customer_link.revoked_at IS '폐기 일시';
COMMENT ON COLUMN visit_customer_link.response_version IS '고객이 시간대를 제출할 때마다 1씩 증가하는 응답 버전이다. 링크 행을 잠근 뒤 증가시킨다';
COMMENT ON COLUMN visit_customer_link.responded_at IS '마지막 고객 시간대 제출 시각이다. 제출 전에는 NULL이다';
COMMENT ON COLUMN visit_customer_link.retention_until IS '링크 행과 고객이 제출한 시간대를 지우는 날이다. 처음에는 링크 만료일에 보관 일수를 더하고 조율이 끝나면 종료일 기준으로 늦은 쪽으로 갱신한다';
COMMENT ON TABLE visit_customer_time_slot IS '고객 공개 링크에서 제출한 가능 시간대의 버전별 원본이다. 현재 응답은 링크의 response_version과 일치하는 행만 조회한다. 수정 시 이전 버전 행은 보존한다';
COMMENT ON COLUMN visit_customer_time_slot.id IS '고객 제출 시간대 내부 식별자';
COMMENT ON COLUMN visit_customer_time_slot.customer_link_id IS '제출에 사용한 고객 링크';
COMMENT ON COLUMN visit_customer_time_slot.response_version IS '제출 버전 번호';
COMMENT ON COLUMN visit_customer_time_slot.starts_at IS '가능 시간대 시작 시각';
COMMENT ON COLUMN visit_customer_time_slot.ends_at IS '가능 시간대 종료 시각';
COMMENT ON COLUMN visit_customer_time_slot.created_at IS '시간대 접수 시각';
COMMENT ON TABLE visit_approver_link IS '조율 건과 매물 출입승인 버전에 연결된 승인자 공개 링크다. 토큰 원문은 저장하지 않는다. 재발급 시 이전 링크를 폐기하고 새 행을 만든다. 응답기한은 담당자 입력 없이 서버가 정하며 첫 방문 후보 시각 24시간 전이고 후보가 이미 24시간 이내이면 발급 후 6시간이다. 만료는 발급 후 7일과 응답기한 중 더 빠른 시각이며 서비스 계층이 발급 시점에 계산해 expires_at에 저장한다. 조율 상세 응답의 승인자 링크 정보는 issued_at, expires_at, revoked_at으로 채운다. 정합화 전 구조다. 대체 구조는 출입승인 단위 링크 visit_approver_property_link와 승인자 조건 visit_approver_condition이며 이 테이블은 이번 스키마 버전에서 지우지 않고 신규 코드는 쓰지 않는다';
COMMENT ON COLUMN visit_approver_link.id IS '승인자 링크 내부 식별자';
COMMENT ON COLUMN visit_approver_link.coordination_id IS '대상 조율 건';
COMMENT ON COLUMN visit_approver_link.approval_id IS '해당 승인자의 매물 출입승인 버전';
COMMENT ON COLUMN visit_approver_link.token_hash IS '승인자 링크 토큰 원문의 SHA-256 해시';
COMMENT ON COLUMN visit_approver_link.issued_at IS '링크 발급 시각';
COMMENT ON COLUMN visit_approver_link.expires_at IS '링크 만료 시각. 발급 후 7일과 응답기한 중 더 빠른 시각이며 응답기한은 담당자 입력 없이 서버가 정하며 첫 방문 후보 시각 24시간 전이고 후보가 이미 24시간 이내이면 발급 후 6시간이다';
COMMENT ON COLUMN visit_approver_link.revoked_at IS '링크 폐기 시각';
COMMENT ON COLUMN visit_approver_link.response_version IS '승인자 시간대 제출 때마다 증가하는 응답 버전';
COMMENT ON COLUMN visit_approver_link.responded_at IS '마지막 승인자 시간대 제출 시각';
COMMENT ON TABLE visit_approver_time_slot IS '승인자가 공개 링크에서 직접 제출한 시간대의 버전별 원본이다. 현재 응답은 승인자 링크의 response_version과 일치하는 행만 조회한다. 정합화 전 구조다. 대체 구조는 visit_approver_condition_window이며 이 테이블은 이번 스키마 버전에서 지우지 않고 신규 코드는 쓰지 않는다';
COMMENT ON COLUMN visit_approver_time_slot.id IS '승인자 제출 시간대 내부 식별자';
COMMENT ON COLUMN visit_approver_time_slot.approver_link_id IS '제출에 사용한 승인자 링크';
COMMENT ON COLUMN visit_approver_time_slot.response_version IS '제출 버전 번호';
COMMENT ON COLUMN visit_approver_time_slot.starts_at IS '가능 시간대 시작 시각';
COMMENT ON COLUMN visit_approver_time_slot.ends_at IS '가능 시간대 종료 시각';
COMMENT ON COLUMN visit_approver_time_slot.created_at IS '시간대 접수 시각';
COMMENT ON TABLE visit_schedule_item IS '후보 매물별 개별 방문 일정과 결과다. 완료는 담당자가 수동으로 입력하며 예정시각이 지났다고 자동으로 완료되지 않는다. 정정할 때는 previous_result와 correction_reason을 남긴다. 과거 결과를 정정한다고 예약이 부활하지 않는다. 재방문은 새 행으로 만든다';
COMMENT ON COLUMN visit_schedule_item.id IS '방문 일정 항목 내부 식별자';
COMMENT ON COLUMN visit_schedule_item.coordination_id IS '소속 조율 건';
COMMENT ON COLUMN visit_schedule_item.office_id IS '소속 사무소';
COMMENT ON COLUMN visit_schedule_item.candidate_property_id IS '대상 후보 매물';
COMMENT ON COLUMN visit_schedule_item.scheduled_start_at IS '확정된 방문 시작 시각';
COMMENT ON COLUMN visit_schedule_item.scheduled_end_at IS '확정된 방문 종료 시각';
COMMENT ON COLUMN visit_schedule_item.sort_order IS '정렬 순서';
COMMENT ON COLUMN visit_schedule_item.result IS '처리 결과';
COMMENT ON COLUMN visit_schedule_item.result_recorded_at IS '결과 기록 일시';
COMMENT ON COLUMN visit_schedule_item.actual_visited_at IS '실제 방문 완료 시각. 월말 방문 완료 집계는 이 시각의 KST 날짜를 사용한다';
COMMENT ON COLUMN visit_schedule_item.result_recorded_by_membership_id IS '결과를 입력한 담당자';
COMMENT ON COLUMN visit_schedule_item.correction_reason IS '정정 사유';
COMMENT ON COLUMN visit_schedule_item.previous_result IS '정정 전 결과 값';
COMMENT ON COLUMN visit_schedule_item.created_at IS '생성 일시';
COMMENT ON COLUMN visit_schedule_item.confirmed_request_id IS '확정 근거가 된 방문 신청이며 visit_request를 참조한다. 확정 근거 신청이 없는 일정은 NULL이다';
COMMENT ON COLUMN visit_schedule_item.travel_starts_at IS '확정 시점에 저장한 이동 구간 시작 시각이다. 이 방문의 종료 시각과 같고 다음 방문이 없으면 NULL이다';
COMMENT ON COLUMN visit_schedule_item.travel_ends_at IS '확정 시점에 저장한 이동 구간 종료 시각이다. 이동 구간 시작 시각에 확정 시점 후보 매물의 다음 방문까지 이동시간을 더한 값이며 다음 방문이 없으면 NULL이다';
COMMENT ON CONSTRAINT uq_visit_schedule_item_confirmed_request ON visit_schedule_item IS '방문 평가가 방문 일정 항목과 확정 근거 신청의 일치를 검증하도록 복합 외래키가 참조하는 UNIQUE 제약이다';
COMMENT ON INDEX ix_visit_schedule_item_confirmed_request IS '확정 근거 신청에서 방문 일정 항목을 찾는 집계용 인덱스다';
COMMENT ON TABLE visit_schedule_item_result_history IS '방문 결과의 추가 전용 이력이다. 정정은 기존 이력 ID를 대체 대상으로 가리키고 실제 방문시각·효력시각·기록시각을 분리한다. 월말 집계는 대체되지 않은 결과만 사용한다';
COMMENT ON COLUMN visit_schedule_item_result_history.id IS '방문 결과 이력 내부 식별자';
COMMENT ON COLUMN visit_schedule_item_result_history.schedule_item_id IS '대상 방문 일정';
COMMENT ON COLUMN visit_schedule_item_result_history.previous_result IS '정정 전 결과';
COMMENT ON COLUMN visit_schedule_item_result_history.result IS '기록하거나 정정한 결과';
COMMENT ON COLUMN visit_schedule_item_result_history.previous_actual_visited_at IS '정정 전 실제 방문 완료 시각';
COMMENT ON COLUMN visit_schedule_item_result_history.actual_visited_at IS '완료 결과의 실제 방문시각';
COMMENT ON COLUMN visit_schedule_item_result_history.effective_at IS '업무 결과가 실제로 발생한 효력시각';
COMMENT ON COLUMN visit_schedule_item_result_history.recorded_at IS '시스템에 입력한 시각';
COMMENT ON COLUMN visit_schedule_item_result_history.recorded_by_membership_id IS '결과를 입력하거나 정정한 담당자';
COMMENT ON COLUMN visit_schedule_item_result_history.correction_reason IS '과거 결과 정정 사유';
COMMENT ON COLUMN visit_schedule_item_result_history.cancel_reason_code IS '취소 결과를 기록할 때의 사유 코드다. USER_CANCEL은 직원이 취소한 경우이고 CHANGE_REPLACED는 변경 신청 확정으로 기존 방문을 대체한 시스템 취소이며 APPROVER_REASON은 승인자 사유로 취소한 경우이고 CUSTOMER_REASON은 고객 사유로 취소한 경우이며 OTHER는 그 밖의 사유다. 신청자 이력의 취소 건수는 USER_CANCEL과 OTHER만 센다. 결과가 CANCELLED가 아니면 NULL이다';
COMMENT ON COLUMN visit_schedule_item_result_history.supersedes_history_id IS '정정으로 대체하는 이전 결과 사건';
COMMENT ON TABLE visit_coordination_status_history IS '조율 상태 전이 감사 이력이다. 확정완료에서 재조율필요로 가는 전이는 승인철회나 일정변경이 원인이다. 이런 전이 조합은 서비스 계층이 강제한다';
COMMENT ON COLUMN visit_coordination_status_history.id IS '조율 상태 이력 내부 식별자';
COMMENT ON COLUMN visit_coordination_status_history.coordination_id IS '소속 조율 건';
COMMENT ON COLUMN visit_coordination_status_history.from_status IS '변경 전 상태';
COMMENT ON COLUMN visit_coordination_status_history.to_status IS '변경 후 상태';
COMMENT ON COLUMN visit_coordination_status_history.actor_membership_id IS '전이를 발생시킨 직원의 소속. 고객이나 시스템이 발생시킨 전이는 NULL이다';
COMMENT ON COLUMN visit_coordination_status_history.source IS '입력·전이 출처';
COMMENT ON COLUMN visit_coordination_status_history.reason IS '사유';
COMMENT ON COLUMN visit_coordination_status_history.effective_at IS '조율 상태가 실제로 바뀐 효력시각. 최종결과 월말 집계의 기준이다';
COMMENT ON COLUMN visit_coordination_status_history.supersedes_history_id IS '오기록 정정으로 대체하는 이전 상태 사건';
COMMENT ON COLUMN visit_coordination_status_history.created_at IS '생성 일시';
COMMENT ON TABLE visit_confirmation_delivery IS '담당자가 기록한 확정 일정 안내의 전달 여부·채널·시각이다. 고객에게는 전체 동선을, 승인자에게는 해당 매물 방문시각만 안내한다. 기록 자체는 실제 수신이나 법적 동의를 증명하지 않는다';
COMMENT ON COLUMN visit_confirmation_delivery.id IS '전달 기록 내부 식별자';
COMMENT ON COLUMN visit_confirmation_delivery.coordination_id IS '안내 대상 조율 건';
COMMENT ON COLUMN visit_confirmation_delivery.candidate_property_id IS '승인자 안내일 때 해당 후보 매물';
COMMENT ON COLUMN visit_confirmation_delivery.schedule_version IS '안내한 확정 일정 버전';
COMMENT ON COLUMN visit_confirmation_delivery.recipient_type IS '고객 또는 매물 출입 승인자';
COMMENT ON COLUMN visit_confirmation_delivery.delivered IS '담당자가 기록한 전달 여부';
COMMENT ON COLUMN visit_confirmation_delivery.channel IS '전달했을 때의 KAKAO 카카오, SMS 문자, PHONE 전화, IN_PERSON 대면, EMAIL 이메일 채널';
COMMENT ON COLUMN visit_confirmation_delivery.delivered_at IS '담당자가 기록한 실제 전달 시각';
COMMENT ON COLUMN visit_confirmation_delivery.recorded_by_membership_id IS '전달 기록 작성자';
COMMENT ON COLUMN visit_confirmation_delivery.recorded_at IS '전달 기록 입력시각';
COMMENT ON TABLE visit_assistant_notice_log IS '중개보조원 배정 방문의 법정 신분 고지 기록. 고지는 원칙적으로 안내 전에 기록하며, 사후입력은 recorded_after_the_fact로 구분 표시하고 누락 시 missing_exception_reason이 필요하다. 감독 공인중개사가 confirmed_by_membership_id로 확인';
COMMENT ON COLUMN visit_assistant_notice_log.id IS '보조원 고지 기록 내부 식별자';
COMMENT ON COLUMN visit_assistant_notice_log.schedule_item_id IS '대상 방문 일정';
COMMENT ON COLUMN visit_assistant_notice_log.deputy_membership_id IS '배정된 중개보조원';
COMMENT ON COLUMN visit_assistant_notice_log.recipient_type IS '고지 대상의 고객·출입 승인자·현장 추가 상대 유형';
COMMENT ON COLUMN visit_assistant_notice_log.recipient_name IS '실제로 고지한 상대의 이름';
COMMENT ON COLUMN visit_assistant_notice_log.notice_method IS '고지 방법. KAKAO 카카오, SMS 문자, PHONE 전화, IN_PERSON 대면, EMAIL 이메일';
COMMENT ON COLUMN visit_assistant_notice_log.notified_at IS '실제 고지 시각';
COMMENT ON COLUMN visit_assistant_notice_log.recorded_after_the_fact IS '사후 입력 여부';
COMMENT ON COLUMN visit_assistant_notice_log.missing_exception_reason IS '고지를 하지 못했을 때의 예외 사유';
COMMENT ON COLUMN visit_assistant_notice_log.followup_action IS '누락 또는 사후입력 때의 후속 조치';
COMMENT ON COLUMN visit_assistant_notice_log.confirmed_by_membership_id IS '확인한 담당자';
COMMENT ON COLUMN visit_assistant_notice_log.confirmed_at IS '확인 처리 일시';
COMMENT ON COLUMN visit_assistant_notice_log.created_at IS '생성 일시';
COMMENT ON TABLE visit_approver_condition IS '승인자 조건의 버전을 출입승인 아래에 담는다. 조건은 매물과 승인자 단위인 출입승인에 속하며 조율 건에 속하지 않는다. 새 버전을 등록하면 이전 활성 버전은 SUPERSEDED가 된다. 활성 버전은 출입승인당 하나다. 하루 최대 방문 횟수, 방문 간 최소 간격, 최소 사전 신청 시간, 1회 허용 시간, 적용 기간은 필수 조건 항목이며 값이 NULL이면 그 항목은 제한하지 않는다. 연속·분산 선호는 정렬 참고다. 보유기한이 지나도 행을 지우지 않는다. 방문 신청과 재검증 이력이 판정에 쓴 조건 버전을 참조하기 때문이다. 이 표에는 이름과 연락처가 없다. 출입승인을 익명화할 때 입력 계정 연결만 NULL로 바꾸고 가능 시간, 횟수, 간격 같은 시간 규칙 값은 판정 이력의 근거이므로 그대로 남긴다';
COMMENT ON COLUMN visit_approver_condition.id IS '조건 버전 식별자';
COMMENT ON COLUMN visit_approver_condition.approval_id IS '매물과 승인자 단위인 출입승인';
COMMENT ON COLUMN visit_approver_condition.version_no IS '출입승인별 1부터 증가. (approval_id, version_no) UNIQUE';
COMMENT ON COLUMN visit_approver_condition.status IS 'ACTIVE, SUPERSEDED 중 하나. ACTIVE는 출입승인당 부분 UNIQUE';
COMMENT ON COLUMN visit_approver_condition.applies_from IS '적용 기간 시작';
COMMENT ON COLUMN visit_approver_condition.applies_until IS '적용 시작보다 늦어야 함';
COMMENT ON COLUMN visit_approver_condition.max_visits_per_day IS '필수 조건. NULL이면 제한 없음. 값이 있으면 1 이상이며 서비스 계층이 20 이하만 받는다. 서버와 DB는 숫자 기본값을 두지 않는다. 화면이 기본값 3을 미리 채워 보여줄 수 있고 승인자는 바꾸거나 비울 수 있다';
COMMENT ON COLUMN visit_approver_condition.min_gap_minutes IS '필수 조건. NULL이면 제한 없음. 값이 있으면 0 이상. 숫자 기본값을 두지 않는다';
COMMENT ON COLUMN visit_approver_condition.min_lead_minutes IS '필수 조건. NULL이면 제한 없음. 값이 있으면 0 이상. 숫자 기본값을 두지 않는다';
COMMENT ON COLUMN visit_approver_condition.single_visit_max_minutes IS '필수 조건. NULL이면 제한 없음. 값이 있으면 1 이상. 숫자 기본값을 두지 않는다';
COMMENT ON COLUMN visit_approver_condition.grouping_preference IS '선호이며 정렬 참고다. CONSECUTIVE(연속), SPREAD(분산) 중 하나';
COMMENT ON COLUMN visit_approver_condition.source IS 'DIRECT, PROXY 중 하나. DIRECT는 승인자 본인 링크 입력이고 PROXY는 중개사가 전화 등으로 받은 조건의 대리 입력이다. 대리 입력은 유지하며 승인자 본인 입력이 활성이면 대리 입력은 거절한다';
COMMENT ON COLUMN visit_approver_condition.recorded_by_membership_id IS 'PROXY일 때만 값 존재';
COMMENT ON COLUMN visit_approver_condition.registered_at IS '조건 버전 등록 시각';
COMMENT ON COLUMN visit_approver_condition.superseded_at IS 'SUPERSEDED와 동치';
COMMENT ON INDEX uq_visit_approver_condition_active IS '출입승인당 활성 조건 버전은 하나만 둔다. 새 버전을 등록할 때 이전 활성 버전을 같은 트랜잭션에서 SUPERSEDED로 바꾼다';
COMMENT ON COLUMN visit_approver_condition.approval_role IS '항상 PRIMARY다. 조건은 대표 승인자 출입승인에만 둘 수 있다는 규칙을 (approval_id, approval_role) 복합 외래키로 검증하기 위한 컬럼이다';
COMMENT ON COLUMN visit_approver_condition.entered_by_profile_id IS '승인자 계정(프로필)으로 입력한 조건 버전이면 그 프로필이다. 링크 입력과 대리 입력이면 NULL이다. 값이 있으면 source는 DIRECT다. 출입승인을 익명화하면 NULL로 바꾸며 이때 source는 DIRECT로 남는다';
COMMENT ON TABLE visit_approver_condition_window IS '조건 버전에 딸린 요일별·날짜별 가능 시간과 날짜 예외를 담는다. 요일별 복수 시간은 같은 조건의 여러 행으로 표현한다. 보유기한이 지나도 조건 버전과 함께 지우지 않고 값을 그대로 남긴다. 신청 판정 이력의 근거이기 때문이다';
COMMENT ON COLUMN visit_approver_condition_window.id IS '시간대 식별자';
COMMENT ON COLUMN visit_approver_condition_window.condition_id IS '소속 조건 버전';
COMMENT ON COLUMN visit_approver_condition_window.window_type IS 'WEEKDAY(요일 반복), DATE(특정 날짜) 중 하나';
COMMENT ON COLUMN visit_approver_condition_window.weekday IS '1 월요일에서 7 일요일. WEEKDAY일 때만 값 존재';
COMMENT ON COLUMN visit_approver_condition_window.window_date IS 'DATE일 때만 값 존재';
COMMENT ON COLUMN visit_approver_condition_window.starts_time IS '한국 표준시 기준';
COMMENT ON COLUMN visit_approver_condition_window.ends_time IS '시작 시각보다 늦어야 함. 24:00 허용';
COMMENT ON COLUMN visit_approver_condition_window.is_exception IS 'true이면 해당 시간대는 방문 불가로 제외한다. DATE 행이 있는 날짜에서는 false 행이 그 날짜의 가능 시간이 되어 요일별 가능 시간을 대체한다';
COMMENT ON TABLE visit_approver_property_link IS '출입승인 단위 승인자 공개 링크를 담는다. 한 링크로 조건 등록, 신청 비교·선택, 확정 일정 확인을 처리한다. 확정 일정의 변경이 필요하면 승인자는 발급 사무소 문의처로 연락한다. 토큰 원문은 저장하지 않는다. 활성 링크는 출입승인당 하나다. 조율 건에 묶인 기존 visit_approver_link는 정합화 전 구조이며 이 테이블이 대체 구조다. 보유기한이 지나면 행을 지우지 않고 익명화한다. 방문 평가, 선호 중개사, 승인자 선택 기록이 이 행을 참조하기 때문이다';
COMMENT ON COLUMN visit_approver_property_link.id IS '링크 식별자';
COMMENT ON COLUMN visit_approver_property_link.approval_id IS '링크가 묶인 출입승인';
COMMENT ON COLUMN visit_approver_property_link.token_hash IS 'SHA-256 해시. 익명화하면 NULL이 되며 NULL인 행은 어떤 토큰으로도 찾을 수 없다';
COMMENT ON COLUMN visit_approver_property_link.issued_by_membership_id IS '매물을 가진 사무소의 발급 직원';
COMMENT ON COLUMN visit_approver_property_link.issued_at IS '링크 발급 시각';
COMMENT ON COLUMN visit_approver_property_link.expires_at IS '링크 만료 시각';
COMMENT ON COLUMN visit_approver_property_link.revoked_at IS 'NULL이면 활성';
COMMENT ON COLUMN visit_approver_property_link.last_accessed_at IS '마지막 유효 접속 시각. 익명화하면 NULL이 된다';
COMMENT ON INDEX uq_visit_approver_property_link_active IS '출입승인당 활성 승인자 링크는 하나만 둔다. 재발급하면 이전 링크를 폐기한 뒤 새 행을 만든다';
COMMENT ON CONSTRAINT uq_visit_approver_property_link_approval ON visit_approver_property_link IS '방문 평가와 선호 중개사 지정이 링크와 출입승인의 일치를 검증하도록 복합 외래키가 참조하는 UNIQUE 제약이다';
COMMENT ON COLUMN visit_approver_property_link.retention_until IS '링크를 익명화하는 날이다. 이 날은 행 삭제일이 아니라 익명화 처리일이다. 처음에는 링크 만료일에 보관 일수를 더하고 출입승인의 보관 만료일과 비교해 늦은 쪽으로 갱신한다. 익명화 처리일에 배치가 이 링크의 안내 확인 기록을 지우고 토큰 해시와 마지막 접속 시각을 비운다';
COMMENT ON COLUMN visit_approver_property_link.anonymized_at IS '익명화한 시각이다. 값이 있으면 토큰 해시와 마지막 접속 시각이 비어 있고 폐기 상태다. 링크 행은 지우지 않으므로 방문 평가, 선호 중개사, 승인자 선택 기록이 이 행을 계속 참조한다';
COMMENT ON CONSTRAINT ck_visit_approver_property_link_anonymized ON visit_approver_property_link IS '익명화한 행만 토큰 해시가 비어 있고 익명화한 행은 폐기 상태이며 마지막 접속 시각이 비어 있다';
COMMENT ON TABLE visit_request IS '중개사가 매물별로 낸 방문 신청을 담는다. 신청은 승인 대기 상태로 공존할 수 있으며 확정이나 점유가 아니다. 같은 후보 매물에 PENDING, SELECTED 신청은 부분 UNIQUE로 한 건만 허용한다. 신청 상태는 이 테이블이 가지며 조율 건 상태는 집계 상태다';
COMMENT ON COLUMN visit_request.id IS '신청 식별자';
COMMENT ON COLUMN visit_request.condition_id IS '신청 시점에 맞춘 조건 버전. 출입승인 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request.approval_id IS '신청 대상 출입승인. 조건과 매물의 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request.property_id IS '신청 대상 매물. 출입승인의 매물과 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request.applicant_office_id IS '신청한 사무소. 조율 건과 신청자 소속의 사무소 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request.applicant_membership_id IS '신청한 직원';
COMMENT ON COLUMN visit_request.coordination_id IS '신청이 속한 조율 건';
COMMENT ON COLUMN visit_request.candidate_property_id IS '조율 건의 후보 매물. 조율 건 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request.request_kind IS 'NEW(신규), CHANGE(확정 변경) 중 하나';
COMMENT ON COLUMN visit_request.replaces_schedule_item_id IS 'CHANGE일 때만 값 존재';
COMMENT ON COLUMN visit_request.requested_start_at IS '희망 방문 시작';
COMMENT ON COLUMN visit_request.requested_end_at IS '시작보다 늦어야 함';
COMMENT ON COLUMN visit_request.expected_duration_minutes IS '1 이상';
COMMENT ON COLUMN visit_request.party_size IS '값이 있으면 1 이상';
COMMENT ON COLUMN visit_request.request_note IS '승인자에게 보이는 요청사항. 고객 이름과 연락처를 넣지 않는다';
COMMENT ON COLUMN visit_request.status IS '3장의 8개 값 중 하나';
COMMENT ON COLUMN visit_request.status_reason IS '종결 상태의 사유';
COMMENT ON COLUMN visit_request.submitted_at IS '신청 제출 시각';
COMMENT ON COLUMN visit_request.closed_at IS '종결 상태와 동치';
COMMENT ON COLUMN visit_request.updated_at IS '마지막 상태 변경 일시';
COMMENT ON COLUMN visit_request.version IS '낙관적 잠금 버전';
COMMENT ON INDEX uq_visit_request_active_candidate IS '같은 후보 매물에 신청 대기와 선택됨 신청을 합쳐 한 건만 둔다. 이 신청은 확정 예약이나 점유가 아니다';
COMMENT ON COLUMN visit_request.property_office_id IS '신청 대상 매물을 가진 사무소다. (property_id, property_office_id) 복합 외래키로 매물의 실제 소유 사무소와 일치를 검증한다. applicant_office_id와 같으면 자기 사무소 매물이고 다르면 허용받은 다른 사무소 매물이다';
COMMENT ON COLUMN visit_request.access_grant_id IS '다른 사무소 매물 신청의 근거 허용이다. 신청 사무소와 소유 사무소가 다르면 반드시 값이 있고 같으면 반드시 NULL이다. (access_grant_id, approval_id, applicant_office_id) 복합 외래키로 허용이 신청의 출입승인과 신청 사무소에 속하는지 검증한다. 허용의 회수·만료 여부는 시간에 따라 변하므로 서비스 계층이 신청과 선택 때 검사한다';
COMMENT ON CONSTRAINT uq_visit_request_review_ref ON visit_request IS '방문 평가가 신청의 출입승인, 신청 구성원, 신청 사무소를 한 번에 검증하도록 복합 외래키가 참조하는 UNIQUE 제약이다';
COMMENT ON INDEX ix_visit_request_applicant_membership IS '신뢰 요약과 신청자 이력을 신청 구성원 단위로 집계하는 인덱스다';
COMMENT ON INDEX ix_visit_request_applicant_open IS '구성원 한 명의 동시 신청 대기 한도 검사가 신청 대기·선택됨 신청 수를 세는 데 쓴다';
COMMENT ON INDEX ix_visit_request_approval_open IS '출입승인 하나의 동시 신청 대기 한도 검사가 신청 대기·선택됨 신청 수를 세는 데 쓴다';
COMMENT ON TABLE visit_request_status_history IS '신청 상태의 모든 전이를 기록하는 추가 전용 이력이다';
COMMENT ON COLUMN visit_request_status_history.id IS '이력 식별자';
COMMENT ON COLUMN visit_request_status_history.request_id IS '대상 신청';
COMMENT ON COLUMN visit_request_status_history.from_status IS '최초 제출 때 NULL';
COMMENT ON COLUMN visit_request_status_history.to_status IS '3장의 8개 값 중 하나';
COMMENT ON COLUMN visit_request_status_history.source IS 'BROKER, APPROVER, SYSTEM 중 하나';
COMMENT ON COLUMN visit_request_status_history.actor_membership_id IS 'BROKER일 때만 값 존재';
COMMENT ON COLUMN visit_request_status_history.reason IS '전이 사유';
COMMENT ON COLUMN visit_request_status_history.effective_at IS '상태가 실제로 바뀐 시각';
COMMENT ON COLUMN visit_request_status_history.created_at IS '기록 일시';
COMMENT ON TABLE visit_request_selection IS '승인자가 신청을 선택한 사건과 비교 근거를 담는다. 재검증 실패 뒤 다시 선택하면 새 행이다';
COMMENT ON COLUMN visit_request_selection.id IS '선택 사건 식별자';
COMMENT ON COLUMN visit_request_selection.request_id IS '선택된 신청';
COMMENT ON COLUMN visit_request_selection.approver_link_id IS '선택에 쓴 링크다. 승인자 계정으로 선택했으면 NULL이고 approver_profile_id가 값을 가진다';
COMMENT ON COLUMN visit_request_selection.compared_request_count IS '선택 시점에 비교 화면에 있던 신청 수. 1 이상';
COMMENT ON COLUMN visit_request_selection.selection_note IS '승인자 입력 메모';
COMMENT ON COLUMN visit_request_selection.selected_at IS '선택 시각';
COMMENT ON COLUMN visit_request_selection.approver_profile_id IS '선택한 승인자 프로필이다. 링크로 선택했으면 NULL이다. approver_link_id와 둘 중 하나만 값을 가진다';
COMMENT ON TABLE visit_request_revalidation IS '선택 시점의 재검증 결과를 담는다. 최신 조건, 권한, 일정 충돌을 다시 확인한 결과이며 고객과 중개사의 충돌은 방문과 이동 구간, 매물의 충돌은 실제 방문 구간을 기준으로 한다';
COMMENT ON COLUMN visit_request_revalidation.id IS '재검증 식별자';
COMMENT ON COLUMN visit_request_revalidation.request_id IS '검증 대상 신청';
COMMENT ON COLUMN visit_request_revalidation.selection_id IS '선택에서 시작된 재검증이면 값 존재. 값이 있으면 선택과 신청의 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_request_revalidation.condition_id IS '검증 시점의 활성 조건 버전';
COMMENT ON COLUMN visit_request_revalidation.result IS 'PASSED, FAILED 중 하나';
COMMENT ON COLUMN visit_request_revalidation.failure_code IS 'FAILED일 때만 값 존재. 3장의 12개 값 중 하나이며 MIN_LEAD는 신청 제출 검증에서만 쓰므로 재검증 기록에는 남지 않는다';
COMMENT ON COLUMN visit_request_revalidation.failure_detail IS '사유와 대안 안내에 쓰는 상세';
COMMENT ON COLUMN visit_request_revalidation.checked_at IS '검증 시각';
COMMENT ON TABLE visit_request_notice IS '신청 마감·선택 결과·조건 변경 영향 같은 알림 사건을 담는다. 출시 기준에서는 앱 내 알림만 두므로 channel은 항상 NULL이다. 이 알림은 끌 수 없고 알림 수신 설정 키에 묶지 않는다';
COMMENT ON COLUMN visit_request_notice.id IS '알림 식별자';
COMMENT ON COLUMN visit_request_notice.request_id IS '관련 신청';
COMMENT ON COLUMN visit_request_notice.recipient_membership_id IS '알림 수신 직원';
COMMENT ON COLUMN visit_request_notice.notice_type IS '3장의 8개 값 중 하나다. GRANT_REVOKED는 신청 허용의 회수·만료로 신청 대기 신청이 종결됐을 때 신청자에게 남기는 알림이다';
COMMENT ON COLUMN visit_request_notice.channel IS '출시 기준에서는 앱 내 알림만 두므로 항상 NULL이다';
COMMENT ON COLUMN visit_request_notice.created_at IS '알림 사건 생성 시각';
COMMENT ON COLUMN visit_request_notice.read_at IS '직원이 확인한 시각';
COMMENT ON TABLE contract IS '계약 등록·이력이다. 초안은 당사자·체결일·금액·잔금·임대일정의 부분 입력을 허용하고 체결 시 필수값을 검증한다. 계약상태, 임대기간상태, 잔금상태가 독립적으로 전이한다. 잔금 완료는 계약 종료나 보수 수납 완료를 의미하지 않는다. 매매는 임대기간 트랙이 없고 TERMINATED로 전이하지 않는다. 재계약은 previous_contract_id로 새 계약을 연결하며 기존 계약을 자동 종료하거나 덮어쓰지 않는다';
COMMENT ON COLUMN contract.id IS '계약 내부 식별자';
COMMENT ON COLUMN contract.office_id IS '소속 사무소';
COMMENT ON COLUMN contract.property_id IS '대상 매물';
COMMENT ON COLUMN contract.previous_contract_id IS '재계약 시 직전 계약';
COMMENT ON COLUMN contract.deal_type IS '거래유형';
COMMENT ON COLUMN contract.managing_membership_id IS '담당자 소속';
COMMENT ON COLUMN contract.seller_landlord_name IS '매도인·임대인 측 sequence_no=1 당사자의 조회용 이름 스냅샷. 초안에서 당사자 미입력 시 NULL이다';
COMMENT ON COLUMN contract.seller_landlord_phone IS '매도인·임대인 측 sequence_no=1 당사자의 조회용 연락처 스냅샷';
COMMENT ON COLUMN contract.buyer_tenant_name IS '매수인·임차인 측 sequence_no=1 당사자의 조회용 이름 스냅샷. 초안에서 당사자 미입력 시 NULL이다';
COMMENT ON COLUMN contract.buyer_tenant_phone IS '매수인·임차인 측 sequence_no=1 당사자의 조회용 연락처 스냅샷';
COMMENT ON COLUMN contract.signed_date IS '계약 체결일. 초안에서는 NULL일 수 있고 체결 시 필수다';
COMMENT ON COLUMN contract.sale_price IS '매매가';
COMMENT ON COLUMN contract.deposit_amount IS '보증금';
COMMENT ON COLUMN contract.monthly_rent_amount IS '월세';
COMMENT ON COLUMN contract.memo IS '계약 업무 메모. 계약서 원문이나 민감정보를 중복 저장하지 않는다. 2000자 이하다';
COMMENT ON COLUMN contract.balance_due_date IS '잔금 예정일';
COMMENT ON COLUMN contract.balance_due_date_pending_reason IS '잔금 예정일이 미정일 때의 사유다. 사유 없이 임의 날짜를 입력하는 것은 금지한다. 2000자 이하다';
COMMENT ON COLUMN contract.payment_amount_mismatch_reason IS '계약대금 예정 합계가 매매가나 보증금과 다를 때 받은 불일치 사유다. 공백만 있는 값은 둘 수 없다. 예정 합계가 대조 기준 금액과 같아지면 NULL로 비운다';
COMMENT ON COLUMN contract.lease_start_date IS '임대 시작일';
COMMENT ON COLUMN contract.lease_end_date IS '임대 만기일';
COMMENT ON COLUMN contract.contract_status IS 'DRAFT는 초안이며 삭제할 수 있다. SIGNED는 체결이다. ENDED는 종료다. TERMINATED는 해제이며 매매에는 쓰지 않는다. CANCELLED는 취소다. VOID는 무효이며 오기록 정정 대상이다';
COMMENT ON COLUMN contract.lease_period_status IS '전세·월세만 사용하는 표시값이다. 만기가 지나도 자동으로 전이하지 않는다. BEFORE_START는 시작 전, IN_PROGRESS는 기간 중, MATURITY_CONFIRMATION_NEEDED는 만기 도래와 확인필요를 뜻한다';
COMMENT ON COLUMN contract.settlement_status IS '잔금 상태';
COMMENT ON COLUMN contract.duplicate_of_contract_id IS '중복 제외 때 지정한 중복 대상 계약이다. 같은 사무소의 다른 계약이어야 하며 자기 자신은 불가하다';
COMMENT ON COLUMN contract.duplicate_excluded_at IS '대표가 단순 중복 입력 계약을 업무 목록에서 제외한 시각이다. duplicateExcluded는 이 값이 있는지로 계산한다. 초안 계약은 제외할 수 없다. 월말결산 체결 계약 집계는 이 값이 있는 계약을 뺀다';
COMMENT ON COLUMN contract.duplicate_exclusion_reason IS '중복 제외 사유다. 공백만 있는 값은 불가하고 2000자 이하다';
COMMENT ON COLUMN contract.duplicate_excluded_by_membership_id IS '중복 제외를 실행한 대표의 소속이다. 네 중복 제외 컬럼은 모두 NULL이거나 모두 값이 있다';
COMMENT ON COLUMN contract.created_at IS '생성 일시';
COMMENT ON TABLE contract_party IS '계약의 양측 공동당사자를 저장한다. 체결 전 양쪽 각각 한 명 이상을 검사한다. 당사자 정정에서 기존 ID가 유지되면 내용을 갱신하고 제외된 행은 removed_at을 채워 보수 원장의 참조를 보존한다. 현재 목록은 removed_at IS NULL인 행만 조회한다. customer_id의 사무소 일치는 서비스가 검사한다. contract의 단일 이름·전화 컬럼은 각 측 현재 첫 번째 당사자의 조회용 스냅샷으로 동기화한다';
COMMENT ON COLUMN contract_party.id IS '계약 당사자 내부 식별자';
COMMENT ON COLUMN contract_party.contract_id IS '당사자가 속한 계약';
COMMENT ON COLUMN contract_party.side IS 'SELLER_LANDLORD는 매도인·임대인 측, BUYER_TENANT는 매수인·임차인 측';
COMMENT ON COLUMN contract_party.sequence_no IS '각 측 안에서 1부터 시작하는 표시 순서';
COMMENT ON COLUMN contract_party.name IS '계약서에 기재된 당사자 이름';
COMMENT ON COLUMN contract_party.phone IS '당사자 연락처';
COMMENT ON COLUMN contract_party.customer_id IS '사무소 고객 기록과 연결된 경우의 고객 ID';
COMMENT ON COLUMN contract_party.created_at IS '당사자 등록 시각';
COMMENT ON COLUMN contract_party.removed_at IS '정정으로 현재 당사자 목록에서 제외한 시각. 과거 보수 지급의무자 참조를 보존한다';
COMMENT ON TABLE contract_revision IS '체결 당시 및 체결 후 오기록 정정의 전체값 스냅샷이다. JSON 키는 signedDate, dealType, salePrice, depositAmount, monthlyRentAmount, balanceDueDate, balanceDueDatePendingReason, leaseStartDate, leaseEndDate, sellerLandlordParties, buyerTenantParties다. 두 당사자 배열의 각 항목은 partyId, sequenceNo, name, phone, customerId다. 이전 버전을 수정하지 않고 새 행에 정정 사유·실제 효력시각·입력시각을 남긴다';
COMMENT ON COLUMN contract_revision.id IS '계약 핵심정보 버전 내부 식별자';
COMMENT ON COLUMN contract_revision.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_revision.revision_no IS '계약별 1부터 증가하는 핵심정보 버전';
COMMENT ON COLUMN contract_revision.revision_type IS '최초 체결 SIGNED 또는 오기록 정정 CORRECTED';
COMMENT ON COLUMN contract_revision.previous_snapshot IS '정정 전 계약 필드·공동당사자 JSON 스냅샷';
COMMENT ON COLUMN contract_revision.current_snapshot IS '이 버전의 계약 필드·공동당사자 JSON 스냅샷';
COMMENT ON COLUMN contract_revision.effective_at IS '이 계약 핵심정보가 실제로 유효한 효력시각';
COMMENT ON COLUMN contract_revision.recorded_at IS '시스템에 버전을 입력한 시각';
COMMENT ON COLUMN contract_revision.recorded_by_membership_id IS '체결 또는 정정을 입력한 담당자';
COMMENT ON COLUMN contract_revision.reason IS '정정 사유. 2000자 이하다';
COMMENT ON COLUMN contract_revision.supersedes_revision_id IS '정정으로 대체하는 이전 계약 버전';
COMMENT ON TABLE contract_status_history IS '계약·임대기간·잔금 3트랙의 전이 및 오기록 정정 이력을 track 컬럼으로 구분해 한 표에 담는다. 정정 시에도 이전 상태·사유·정정자를 남기고 삭제하지 않는다';
COMMENT ON COLUMN contract_status_history.id IS '계약 상태 이력 내부 식별자';
COMMENT ON COLUMN contract_status_history.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_status_history.track IS '상태 이력이 속한 트랙이다. CONTRACT는 계약 상태, LEASE_PERIOD는 임대기간 상태, SETTLEMENT는 잔금 상태다';
COMMENT ON COLUMN contract_status_history.from_status IS '변경 전 상태';
COMMENT ON COLUMN contract_status_history.to_status IS '변경 후 상태';
COMMENT ON COLUMN contract_status_history.reason IS '사유. 2000자 이하다';
COMMENT ON COLUMN contract_status_history.changed_by_membership_id IS '변경을 실행한 담당자';
COMMENT ON COLUMN contract_status_history.effective_at IS '계약·임대기간·잔금 상태가 실제로 바뀐 효력시각';
COMMENT ON COLUMN contract_status_history.supersedes_history_id IS '오기록 정정으로 대체하는 이전 상태 사건';
COMMENT ON COLUMN contract_status_history.created_at IS '생성 일시';
COMMENT ON TABLE contract_document IS '거래계약서는 5년, 중개대상물확인설명서는 3년의 보존기간을 각각 갖는다. 생성 24시간 이내라도 임의 삭제를 금지한다. 주민등록번호 등의 포함 여부와 처리근거를 업로드 전에 확인한다. 근거가 없으면 마스킹 사본만 업로드하고 pii_masking_confirmed로 표시한다. 이 경우 법정원본보존이 완료됐다고 간주하지 않는다. 정정본 행도 written_date, delivered_date, date_pending_reason, retention_years, pii_masking_confirmed를 모두 채우며 정정본 응답이 이 값들을 그대로 반환한다';
COMMENT ON COLUMN contract_document.id IS '계약 서류 내부 식별자';
COMMENT ON COLUMN contract_document.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_document.contract_revision_id IS '이 파일이 반영하는 체결 또는 정정 당시 계약 핵심정보 버전';
COMMENT ON COLUMN contract_document.document_type IS '서류 종류';
COMMENT ON COLUMN contract_document.version_no IS '같은 계약과 서류 종류 안에서 증가하는 버전 번호';
COMMENT ON COLUMN contract_document.supersedes_document_id IS '정정 전 문서 버전의 ID. 정정 원문은 삭제하지 않는다';
COMMENT ON COLUMN contract_document.written_date IS '실제 서류 작성일. DB 업로드일로 대체하지 않는다';
COMMENT ON COLUMN contract_document.delivered_date IS '실제 서류 교부일. DB 업로드일로 대체하지 않는다';
COMMENT ON COLUMN contract_document.date_pending_reason IS '실제 작성·교부일을 아직 확인하지 못한 사유';
COMMENT ON COLUMN contract_document.retention_end_date IS '작성·교부일 중 늦은 날부터 서류 종류별 보존 연수를 적용한 내부 보존 종료일. 날짜 확인 전에는 NULL이다';
COMMENT ON COLUMN contract_document.retention_years IS '법정 보존 연수';
COMMENT ON COLUMN contract_document.object_key IS '스토리지 객체 키';
COMMENT ON COLUMN contract_document.pii_masking_confirmed IS '마스킹 사본 여부';
COMMENT ON COLUMN contract_document.uploaded_by_membership_id IS '업로드한 담당자';
COMMENT ON COLUMN contract_document.uploaded_at IS '서류 업로드 일시';
COMMENT ON TABLE contract_fee IS '중개보수 청구 단위다. contract_payment_*로 관리하는 부동산 대금과는 분리해서 관리한다';
COMMENT ON COLUMN contract_fee.id IS '중개보수 청구 내부 식별자';
COMMENT ON COLUMN contract_fee.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_fee.payer_type IS '지급의무자 구분';
COMMENT ON COLUMN contract_fee.payer_party_id IS '계약의 실제 지급의무자 당사자 ID. 미수금과 초과수납은 이 ID별로 계산한다';
COMMENT ON COLUMN contract_fee.agreed_fee_amount IS '약정보수 금액';
COMMENT ON COLUMN contract_fee.vat_included IS '부가세 포함 여부';
COMMENT ON COLUMN contract_fee.supply_amount IS '공급가액';
COMMENT ON COLUMN contract_fee.tax_amount IS '세액';
COMMENT ON COLUMN contract_fee.total_amount IS '청구 합계';
COMMENT ON COLUMN contract_fee.billed_at IS '청구발생일';
COMMENT ON COLUMN contract_fee.due_at IS '납부·지급 기한';
COMMENT ON COLUMN contract_fee.created_at IS '생성 일시';
COMMENT ON TABLE contract_fee_revision IS '약정보수의 최초 청구·정상 조정·과거 오입력 정정을 효력일과 입력시각으로 분리한 추가 전용 원장이다. contract_fee의 금액 컬럼은 최신 조회용 스냅샷이며 월말 집계는 대체되지 않은 이 원장을 사용한다';
COMMENT ON COLUMN contract_fee_revision.id IS '보수 변경 사건 내부 식별자';
COMMENT ON COLUMN contract_fee_revision.fee_id IS '대상 보수 청구';
COMMENT ON COLUMN contract_fee_revision.revision_type IS '최초 청구 INITIAL, 정상 조정 ADJUSTED, 과거 오류 정정 CORRECTED';
COMMENT ON COLUMN contract_fee_revision.effective_date IS '청구 또는 조정이 실제 효력을 갖는 날짜';
COMMENT ON COLUMN contract_fee_revision.agreed_fee_amount IS '해당 효력일의 약정보수 전체 금액';
COMMENT ON COLUMN contract_fee_revision.supply_amount IS '해당 효력일의 공급가액';
COMMENT ON COLUMN contract_fee_revision.tax_amount IS '해당 효력일의 세액';
COMMENT ON COLUMN contract_fee_revision.total_amount IS '해당 효력일의 VAT 포함 청구액';
COMMENT ON COLUMN contract_fee_revision.reason IS '조정 또는 정정의 사유';
COMMENT ON COLUMN contract_fee_revision.recorded_by_membership_id IS '사건을 입력한 담당자';
COMMENT ON COLUMN contract_fee_revision.recorded_at IS '사건 입력시각';
COMMENT ON COLUMN contract_fee_revision.supersedes_revision_id IS '과거 오류 정정으로 대체하는 기존 사건';
COMMENT ON TABLE contract_fee_transaction IS '수납, 환급, 정정을 append-only 원장으로 기록한다. 청구잔액은 유효 청구합계에서 순수납액을 뺀 값이며 조회 시점에 계산한다. 취소는 REFUND나 ADJUSTMENT 같은 반대거래로 정정한다. 계약을 취소하거나 해제해도 기수납액은 삭제하지 않는다';
COMMENT ON COLUMN contract_fee_transaction.id IS '중개보수 거래 내부 식별자';
COMMENT ON COLUMN contract_fee_transaction.fee_id IS '대상 중개보수 청구';
COMMENT ON COLUMN contract_fee_transaction.transaction_type IS '거래 종류';
COMMENT ON COLUMN contract_fee_transaction.amount IS '금액';
COMMENT ON COLUMN contract_fee_transaction.actual_date IS '실제 수납·환급 또는 조정 효력일. 월말 순수납 집계의 기준이다';
COMMENT ON COLUMN contract_fee_transaction.memo IS '메모';
COMMENT ON COLUMN contract_fee_transaction.supersedes_transaction_id IS '오입력 정정으로 대체하는 이전 거래 ID';
COMMENT ON COLUMN contract_fee_transaction.correction_reason IS '오입력 정정 사유';
COMMENT ON COLUMN contract_fee_transaction.recorded_by_membership_id IS '기록한 담당자';
COMMENT ON COLUMN contract_fee_transaction.recorded_at IS '기록 일시';
COMMENT ON TABLE contract_payment_schedule IS '계약금, 복수 중도금, 잔금의 지급 예정을 기록한다. 복수 중도금은 sequence_no로 구분한다. 매매가나 보증금 합계와의 대조, 불일치 사유 기록은 서비스 계층이 수행한다';
COMMENT ON COLUMN contract_payment_schedule.id IS '계약대금 지급예정 내부 식별자';
COMMENT ON COLUMN contract_payment_schedule.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_payment_schedule.installment_type IS '분할 종류';
COMMENT ON COLUMN contract_payment_schedule.sequence_no IS '분할 지급 순번';
COMMENT ON COLUMN contract_payment_schedule.scheduled_date IS '예정일';
COMMENT ON COLUMN contract_payment_schedule.scheduled_amount IS '예정 금액';
COMMENT ON COLUMN contract_payment_schedule.created_at IS '생성 일시';
COMMENT ON TABLE contract_payment_transaction IS '계약대금 실지급 기록. 정정 시 correction_reason과 잔금 확인자·시각을 남긴다. 정정 거래는 supersedes_transaction_id로 대체할 이전 거래를 가리키며 기존 행을 덮어쓰지 않는다';
COMMENT ON COLUMN contract_payment_transaction.id IS '계약대금 실지급 내부 식별자';
COMMENT ON COLUMN contract_payment_transaction.schedule_id IS '대상 지급예정';
COMMENT ON COLUMN contract_payment_transaction.actual_amount IS '실지급 금액';
COMMENT ON COLUMN contract_payment_transaction.actual_date IS '실지급일';
COMMENT ON COLUMN contract_payment_transaction.supersedes_transaction_id IS '오입력 정정으로 대체하는 이전 실지급 거래 ID. 같은 schedule_id의 거래인지는 서비스 계층이 검사한다. 값이 있으면 correction_reason이 공백이 아니어야 한다';
COMMENT ON COLUMN contract_payment_transaction.confirmed_by_membership_id IS '확인한 담당자';
COMMENT ON COLUMN contract_payment_transaction.confirmed_at IS '확인 처리 일시';
COMMENT ON COLUMN contract_payment_transaction.correction_reason IS '정정 사유';
COMMENT ON TABLE contract_followup_task IS '서류작성과 교부, 신고대상, 근거, 기한을 체크한다. 잔금일과 만기일에 맞춰 자동 생성한다. 이 생성은 서비스 계층이 수행한다. 자동 신고는 수행하지 않는다. 모든 거래에 동일한 신고기한을 강제하지 않는다';
COMMENT ON COLUMN contract_followup_task.id IS '계약 후속업무 내부 식별자';
COMMENT ON COLUMN contract_followup_task.contract_id IS '대상 계약';
COMMENT ON COLUMN contract_followup_task.task_type IS '업무 종류. D90_FOLLOWUP은 임대 만기 90일 전 후속업무다';
COMMENT ON COLUMN contract_followup_task.report_target IS '신고 대상 기관';
COMMENT ON COLUMN contract_followup_task.report_basis IS '신고 근거';
COMMENT ON COLUMN contract_followup_task.report_deadline IS '신고 기한';
COMMENT ON COLUMN contract_followup_task.submitted IS '제출 여부';
COMMENT ON COLUMN contract_followup_task.submitted_at IS '제출 처리 일시';
COMMENT ON COLUMN contract_followup_task.created_at IS '생성 일시';
COMMENT ON TABLE monthly_settlement IS '월말결산 11개 지표군의 세부 집계값 18개를 저장한다. 현재월은 현재 시각까지 계산해 집계중 상태로 표시하며 is_finalized는 false다. 이 표시는 서비스 계층이 처리한다. 미수금과 초과수납은 지급의무자별로 계산하고 이 표에는 사무소 합계만 저장한다. 부가 표시값으로 신규 이전 등록 수 두 개와 잔금 예정일이 없는 계약 수를 함께 저장하며 세부 집계값 18개에는 포함하지 않는다';
COMMENT ON COLUMN monthly_settlement.id IS '월말결산 내부 식별자';
COMMENT ON COLUMN monthly_settlement.office_id IS '소속 사무소';
COMMENT ON COLUMN monthly_settlement.year_month IS '결산·메모 대상 연월';
COMMENT ON COLUMN monthly_settlement.property_count_total IS '월말 보유매물 수';
COMMENT ON COLUMN monthly_settlement.customer_count_total IS '월말 보유고객 수';
COMMENT ON COLUMN monthly_settlement.property_count_new IS '이번 달 신규 등록된 매물 수';
COMMENT ON COLUMN monthly_settlement.property_count_new_migrated IS '이번 달 신규 매물 중 데이터 이전으로 등록된 수다. property_count_new에 포함되며 18개 세부 값에는 들지 않는 부가 표시값이다';
COMMENT ON COLUMN monthly_settlement.customer_count_new IS '이번 달 신규 등록된 고객 수';
COMMENT ON COLUMN monthly_settlement.customer_count_new_migrated IS '이번 달 신규 고객 중 데이터 이전으로 등록된 수다. customer_count_new에 포함되며 18개 세부 값에는 들지 않는 부가 표시값이다';
COMMENT ON COLUMN monthly_settlement.first_inquiry_count IS '이번 달 최초문의 수';
COMMENT ON COLUMN monthly_settlement.visit_completed_count IS '이번 달 방문완료 횟수';
COMMENT ON COLUMN monthly_settlement.visit_completed_property_count IS '이번 달 방문완료 매물 수';
COMMENT ON COLUMN monthly_settlement.coordination_ended_count IS '이번 달 종료된 조율 수';
COMMENT ON COLUMN monthly_settlement.coordination_visit_completed_count IS '이번 달 방문 완료로 종료된 조율 수';
COMMENT ON COLUMN monthly_settlement.coordination_visit_incomplete_count IS '이번 달 미방문으로 종료된 조율 수';
COMMENT ON COLUMN monthly_settlement.contract_signed_count IS '이번 달 체결계약 수. contract.duplicate_excluded_at이 있는 중복 제외 계약은 뺀다';
COMMENT ON COLUMN monthly_settlement.contract_signed_property_count IS '이번 달 체결매물 수. 중복 제외 계약은 뺀 계약의 매물만 센다';
COMMENT ON COLUMN monthly_settlement.lease_maturity_count IS '이번 달 만기인 유효 임대계약 수';
COMMENT ON COLUMN monthly_settlement.lease_maturity_property_count IS '이번 달 만기인 유효 임대계약의 매물 ID 중복 제거 수';
COMMENT ON COLUMN monthly_settlement.agreed_fee_total IS '잔금 기준 약정보수 합계';
COMMENT ON COLUMN monthly_settlement.agreed_fee_undated_count IS '잔금 예정일이 없어 agreed_fee_total에 들어가지 않은 유효 계약 수다. 18개 세부 값에는 들지 않는 부가 표시값이다';
COMMENT ON COLUMN monthly_settlement.actual_fee_received_total IS '실제 중개보수 순수납 합계';
COMMENT ON COLUMN monthly_settlement.outstanding_amount IS '미수금이다. 청구합계에서 순수납을 뺀 값과 0 중 큰 값을 사무소 단위로 합산한다';
COMMENT ON COLUMN monthly_settlement.overcollected_amount IS '초과수납이다. 순수납에서 청구합계를 뺀 값과 0 중 큰 값을 사무소 단위로 합산한다. 미수금과 상계하지 않는다';
COMMENT ON COLUMN monthly_settlement.is_finalized IS '마감 여부';
COMMENT ON COLUMN monthly_settlement.generated_at IS '집계 생성 일시';
COMMENT ON TABLE monthly_memo IS '사무소와 월 조합당 1개 메모다. version으로 낙관적 락을 건다. 수정 요청 시 클라이언트가 읽은 version과 다르면 충돌로 처리한다';
COMMENT ON COLUMN monthly_memo.id IS '월간 메모 내부 식별자';
COMMENT ON COLUMN monthly_memo.office_id IS '소속 사무소';
COMMENT ON COLUMN monthly_memo.year_month IS '결산·메모 대상 연월';
COMMENT ON COLUMN monthly_memo.content IS '내용. 2000자 이하다';
COMMENT ON COLUMN monthly_memo.version IS '버전 번호';
COMMENT ON COLUMN monthly_memo.updated_by_membership_id IS '마지막으로 수정한 담당자';
COMMENT ON COLUMN monthly_memo.updated_at IS '마지막 수정 일시';
COMMENT ON TABLE task IS '홈 업무 목록이다. source_type이 VISIT인 방문 업무, CONTRACT_BALANCE인 잔금예정 업무, CONTRACT_MATURITY인 만기 업무는 원천 데이터에서 자동 생성하며 수동으로 삭제할 수 없다. 이 생성과 삭제 제한은 서비스 계층이 수행한다. 원천이 수정되거나 취소되면 같은 source_type과 source_id의 업무를 갱신한다. 업무를 체크하는 것만으로 원천인 계약 잔금이나 방문 결과는 바뀌지 않는다. 완료일이 지나도 이력은 유지한다. 기한을 초과한 미완료 업무는 미완료 영역에 남는다. source_type이 MANUAL이 아닌 행의 title, assignee_membership_id, due_date 변경과 삭제는 서비스 계층이 막는다';
COMMENT ON COLUMN task.id IS '업무 내부 식별자';
COMMENT ON COLUMN task.office_id IS '소속 사무소';
COMMENT ON COLUMN task.title IS '제목';
COMMENT ON COLUMN task.assignee_membership_id IS '담당 직원';
COMMENT ON COLUMN task.due_date IS '예정일';
COMMENT ON COLUMN task.due_time IS '예정 시각(시간 지정 시)';
COMMENT ON COLUMN task.related_customer_id IS '관련 고객';
COMMENT ON COLUMN task.related_property_id IS '관련 매물';
COMMENT ON COLUMN task.memo IS '메모';
COMMENT ON COLUMN task.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN task.source_type IS '원천 종류';
COMMENT ON COLUMN task.source_id IS 'MANUAL이 아니면 visit_schedule_item이나 contract 등 원천 레코드의 ID다. source_type으로 어느 테이블인지 판별한다. 이 판별은 서비스 계층이 수행한다';
COMMENT ON COLUMN task.completed_at IS '완료 처리 일시';
COMMENT ON COLUMN task.created_at IS '생성 일시';
COMMENT ON TABLE notification IS '알림함 알림이다. 수신자 본인 알림만 최근 발생순으로 조회한다. 읽음 여부는 read_at이 있는지로 판정하고 unreadOnly 조회와 미읽음 수 집계는 read_at이 비어 있는 행을 쓴다. notification_type은 OFFICE_REVIEW(심사), MEMBERSHIP_APPROVAL_NEEDED(참여 승인 필요), INVITATION(초대), ASSIGNEE_CHANGED(담당 변경), VISIT_SCHEDULED(방문 일정), VISIT_CONFIRMED(방문 확정), VISIT_RESCHEDULE_NEEDED(재조율 필요), VISIT_COMPLETION_PENDING(방문 완료 처리 대기), VISIT_SUPERVISION_CHECK(감독 확인), SECURITY_ALERT(로그인·보안), NOTICE(공지·혜택), TRIAL_ENDING(체험 종료), PLAN_CHANGED(요금 변경), PAYMENT(결제), RETURN_SCHEDULED(반환 예정), DELETION_SCHEDULED(삭제 예정), SUPPORT_REPLY(지원 답변)의 열일곱 가지다. target_type은 눌렀을 때 이동할 화면의 대상 종류이고 target_id가 가리키는 표는 target_type으로 판별한다. 알림 수신 설정은 app_user_notification_preference가 맡는다';
COMMENT ON COLUMN notification.id IS '알림 내부 식별자';
COMMENT ON COLUMN notification.office_id IS '알림이 발생한 사무소다. 가입 전 알림처럼 사무소가 없으면 NULL이다';
COMMENT ON COLUMN notification.recipient_user_id IS '알림을 받는 사용자다. 알림함은 이 값이 본인인 알림만 조회한다';
COMMENT ON COLUMN notification.notification_type IS '알림 종류다. 열일곱 가지 코드 중 하나이며 코드별 의미는 표 설명을 따른다';
COMMENT ON COLUMN notification.message IS '알림함에 표시하는 알림 문구';
COMMENT ON COLUMN notification.target_type IS '눌렀을 때 이동할 화면의 대상 종류다. OFFICE_REGISTRATION, MEMBERSHIP, VISIT_COORDINATION, PROPERTY, CUSTOMER, SUBSCRIPTION, DATA_RETURN, SUPPORT_TICKET 중 하나이고 이동 대상이 없으면 NONE이다';
COMMENT ON COLUMN notification.target_id IS '이동 대상 식별값이다. target_type이 SUBSCRIPTION, DATA_RETURN, NONE이면 NULL이고 그 밖에는 반드시 값이 있다';
COMMENT ON COLUMN notification.read_at IS '읽음 처리 일시다. NULL이면 읽지 않은 알림이다';
COMMENT ON COLUMN notification.created_at IS '알림 발생 일시';
COMMENT ON COLUMN notification.updated_at IS '알림 상태를 마지막으로 바꾼 일시';
COMMENT ON INDEX ix_notification_recipient_created IS '수신자 본인 알림을 최근 발생순으로 조회한다';
COMMENT ON INDEX ix_notification_recipient_unread IS '수신자 본인의 읽지 않은 알림 조회와 미읽음 수 집계에 쓴다';
COMMENT ON TABLE subscription IS '사무소당 구독은 1개다. 결제전, 체험, 구독중, 미납유예, 미납제한, 인증중단, 종료의 7개 상태값을 갖는다. 반환 상태는 별도 컬럼을 두지 않는다. ended_at이 있고 현재시각이 ended_at에 30일을 더한 시각보다 이르면 반환기간으로 판정한다. 이 판정은 서비스 계층이 수행하는 파생 조건이다';
COMMENT ON COLUMN subscription.id IS '구독 내부 식별자';
COMMENT ON COLUMN subscription.office_id IS '소속 사무소';
COMMENT ON COLUMN subscription.plan IS '요금제';
COMMENT ON COLUMN subscription.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN subscription.trial_started_at IS '체험 시작 시각';
COMMENT ON COLUMN subscription.trial_ends_at IS '무료체험 종료 시각이다. 기간 방식이면 시작 후 60일이고 고정 종료 방식이면 이벤트의 고정 종료 시각이다. 시작 시각은 최초 인증완료 시각이다. 기간 방식의 60일 계산은 서비스 계층이 수행하고 DDL은 종료 시각이 시작 시각보다 늦다는 것만 검사한다';
COMMENT ON COLUMN subscription.trial_event_id IS '최초 체험 수혜를 부여한 이벤트 ID. 이벤트 종료 뒤에도 기존 수혜 근거를 유지한다';
COMMENT ON COLUMN subscription.current_period_start IS '현재 유료기간 시작 시각';
COMMENT ON COLUMN subscription.current_period_end IS '현재 유료기간 종료 시각';
COMMENT ON COLUMN subscription.cycle_anchor_at IS '현재 유료 회차의 기준 시각이다. 무료 종료 시각에 예정된 첫 청구에서는 그 무료 종료 시각이고 결제 전 상태에서 대표가 직접 결제한 첫 청구에서는 최초 성공시각이다. Asia/Seoul의 일자와 시각으로 매월 경계를 계산하며 없는 일자는 그달 말일을 사용하고 다음 달에는 원래 일자를 복원한다';
COMMENT ON COLUMN subscription.past_due_since IS '미납 유예 시작 시각이며 D0이라고 부른다. D0+8일 미만이면 PAST_DUE_GRACE, D0+8일 이상이면 PAST_DUE_RESTRICTED, D0+30일이면 ENDED로 전이한다. 이 전이는 서비스 계층이 수행한다';
COMMENT ON COLUMN subscription.suspended_at IS '정지 처리 일시';
COMMENT ON COLUMN subscription.trial_remaining_seconds IS '인증 중단 때 보존하는 체험 잔여 초다. 중단 당시 체험 중이었을 때만 값이 있고 SUSPENDED 상태에서만 둔다. 재개하면 비운다';
COMMENT ON COLUMN subscription.ended_at IS '종료 처리 일시';
COMMENT ON COLUMN subscription.created_at IS '생성 일시';
COMMENT ON TABLE subscription_purchase_consent IS '구독 구매·정기청구 조건별 명시적 동의와 철회를 append-only로 저장한다. 사무소의 최신 agreed=true 행이 현재 요금·한도·기간을 승인했는지 청구 전에 재검사한다';
COMMENT ON COLUMN subscription_purchase_consent.id IS '구매 동의 사건 내부 식별자';
COMMENT ON COLUMN subscription_purchase_consent.subscription_id IS '동의 대상 구독';
COMMENT ON COLUMN subscription_purchase_consent.user_id IS '동의한 대표 사용자';
COMMENT ON COLUMN subscription_purchase_consent.terms_agreement_id IS '구독 구매 약관 동의 사건';
COMMENT ON COLUMN subscription_purchase_consent.plan IS '동의한 요금제';
COMMENT ON COLUMN subscription_purchase_consent.member_count IS '화면에 표시한 이용 인원';
COMMENT ON COLUMN subscription_purchase_consent.total_amount_incl_vat IS '화면에 표시한 VAT 포함 청구 금액 원화';
COMMENT ON COLUMN subscription_purchase_consent.vat_amount IS '화면에 표시한 부가세액 원화다. VAT 포함 청구 금액 total_amount_incl_vat에 들어 있는 세액이다';
COMMENT ON COLUMN subscription_purchase_consent.amount_limit IS '대표가 승인한 VAT 포함 청구 한도 원화다. VAT 포함 청구 금액 total_amount_incl_vat 이상이어야 한다';
COMMENT ON COLUMN subscription_purchase_consent.period_start IS '화면에 표시한 이용기간 시작 시각';
COMMENT ON COLUMN subscription_purchase_consent.period_end IS '화면에 표시한 이용기간 종료 시각';
COMMENT ON COLUMN subscription_purchase_consent.next_charge_at IS '화면에 표시한 다음 자동청구 시각';
COMMENT ON COLUMN subscription_purchase_consent.agreed IS '동의 또는 철회 여부';
COMMENT ON COLUMN subscription_purchase_consent.recorded_at IS '동의·철회 기록 시각';
COMMENT ON TABLE billing_customer IS '토스페이먼츠 billingKey를 사무소별 customerKey와 암호화해 연결 저장한다. 카드 원문은 토스 결제창에서만 취급하고 사이로는 저장하지 않는다. 새 카드 등록이 성공하면 이전 키를 폐기한다. 처리 중인 청구가 있으면 결과를 확인한 뒤 교체한다. 이 교체 절차는 서비스 계층이 수행한다';
COMMENT ON COLUMN billing_customer.id IS '결제 고객 내부 식별자';
COMMENT ON COLUMN billing_customer.office_id IS '소속 사무소';
COMMENT ON COLUMN billing_customer.toss_customer_key IS '토스페이먼츠 customerKey';
COMMENT ON COLUMN billing_customer.customer_key_issued_at IS '카드 등록창을 열기 전에 사무소별 customerKey를 발급한 시각이다';
COMMENT ON COLUMN billing_customer.customer_key_expires_at IS '발급한 customerKey를 쓸 수 있는 마감 시각이다. 이 시각이 지난 customerKey로는 카드 등록 요청을 받지 않는다';
COMMENT ON COLUMN billing_customer.billing_key_encrypted IS '암호화해 저장한 토스페이먼츠 billingKey';
COMMENT ON COLUMN billing_customer.billing_key_registered_at IS '결제키 등록 시각';
COMMENT ON COLUMN billing_customer.card_issuer IS '토스 빌링키 발급 응답의 카드사 이름이다. 선택 값이다';
COMMENT ON COLUMN billing_customer.card_last4 IS '토스 빌링키 발급 응답의 마스킹 번호에서 끝 4자리만 저장한다. 카드 원문은 저장하지 않는다. 선택 값이다';
COMMENT ON COLUMN billing_customer.previous_billing_key_encrypted IS '교체 대기 중인 이전 billingKey. 처리 중 청구 결과 확인 후 폐기한다';
COMMENT ON COLUMN billing_customer.replaced_at IS '키 교체 시각';
COMMENT ON TABLE billing_invoice IS '청구서다. member_count_snapshot은 청구 시점의 과금 인원이다. 활성·정상접근 구성원 수를 세며 대표를 포함한다. 대기, 초대, 소속해제, 접근정지, 계정없는 고용인은 제외한다. 일회성(ONE_TIME) 청구서는 기업 견적 수락 때 만들며 구독이 없어 subscription_id, billing_period_start, consent_version, purchase_consent_id가 NULL이다. 이 경우 member_count_snapshot, price_version, consent_amount_limit, consented_at에는 수락한 견적의 값을 넣는다. 환불 완료 금액은 COMPLETED 환불 신청의 refund_amount 합계로 계산하고 환불 가능 금액은 amount에서 그 합계를 뺀 값으로 계산하며 별도 컬럼을 두지 않는다. 보관 기간이 지나도 세금 증빙 기록이 이 청구서를 참조하는 동안은 지우지 않고 증빙 기록의 보관이 끝난 뒤 지운다. 기업도입 견적이 이 청구서를 연결했으면 청구서를 지우기 전에 견적의 청구서 연결만 NULL로 바꾼다';
COMMENT ON COLUMN billing_invoice.id IS '청구서 내부 식별자';
COMMENT ON COLUMN billing_invoice.office_id IS '소속 사무소';
COMMENT ON COLUMN billing_invoice.invoice_kind IS 'SUBSCRIPTION은 구독 월 이용기간 청구서, ONE_TIME은 기업 견적 수락으로 만드는 일회성 청구서다. ONE_TIME일 때만 subscription_id, billing_period_start, consent_version, purchase_consent_id가 NULL이다';
COMMENT ON COLUMN billing_invoice.subscription_id IS '대상 구독. 일회성 청구서는 NULL이다';
COMMENT ON COLUMN billing_invoice.billing_period_start IS '시작 포함 청구기간의 정확한 시각. 일회성 청구서는 NULL이다';
COMMENT ON COLUMN billing_invoice.billing_period_end IS '종료 제외 청구기간의 정확한 시각. 일회성 청구서는 구독 기간이 없어 청구 확정 시각을 넣는다';
COMMENT ON COLUMN billing_invoice.amount IS 'VAT 포함 원화 청구 확정액';
COMMENT ON COLUMN billing_invoice.member_count_snapshot IS '청구 시점의 과금 인원 스냅샷';
COMMENT ON COLUMN billing_invoice.unit_price_snapshot IS '청구에 적용한 기준 단가 원화. 다인 요금은 인원별 산식과 price_version으로 재현한다';
COMMENT ON COLUMN billing_invoice.vat_included_amount IS 'VAT 포함 총액 스냅샷이며 amount와 같아야 한다';
COMMENT ON COLUMN billing_invoice.price_version IS '청구에 적용한 가격표 버전';
COMMENT ON COLUMN billing_invoice.consent_version IS '청구에 적용한 구매·정기결제 동의 문안 버전. 일회성 청구서는 NULL이다';
COMMENT ON COLUMN billing_invoice.consent_amount_limit IS '대표가 동의한 VAT 포함 청구 한도 원화';
COMMENT ON COLUMN billing_invoice.consented_at IS '대표의 해당 금액·한도 동의 시각';
COMMENT ON COLUMN billing_invoice.purchase_consent_id IS '청구 근거가 된 구매 동의 사건 ID. 일회성 청구서는 NULL이다';
COMMENT ON COLUMN billing_invoice.status IS 'UNBILLED 미청구, PROCESSING 처리 중, VERIFYING 확인 중, PAID 성공, FAILED 실패, PARTIALLY_REFUNDED 일부 환불, FULLY_REFUNDED 전액 환불, CANCELLED 취소';
COMMENT ON COLUMN billing_invoice.due_at IS '납부·지급 기한';
COMMENT ON COLUMN billing_invoice.paid_at IS '납부 완료 시각';
COMMENT ON COLUMN billing_invoice.next_retry_at IS '다음 자동 재시도 예정 시각이다. 자동 재시도가 남아 있지 않으면 NULL이다. D0, D0+1시간, D0+3일, D0+7일 재시도 일정에 따라 서비스 계층이 채운다';
COMMENT ON COLUMN billing_invoice.created_at IS '생성 일시';
COMMENT ON INDEX uq_billing_invoice_subscription_period IS '같은 구독의 같은 청구기간에는 정기(SUBSCRIPTION) 청구서가 한 건만 있다. 일회성(ONE_TIME) 청구서는 구독과 청구기간이 없어 이 인덱스의 대상이 아니다';
COMMENT ON COLUMN billing_invoice.supply_amount IS '청구 확정 시점에 서버가 나눈 공급가액이다. 총액에서 부가세액을 뺀 값이며 이 컬럼을 추가하기 전의 청구서는 비어 있다';
COMMENT ON COLUMN billing_invoice.vat_amount IS '청구 확정 시점에 서버가 계산한 부가세액이다. 원 단위 처리 방식은 세무사 확인 전 초안이다';
COMMENT ON COLUMN billing_invoice.vat_rate_bp_snapshot IS '계산에 쓴 부가세율을 만분율로 고정한 값이다. 코드에 세율을 고정하지 않고 계산 시점의 설정 값을 복사한다';
COMMENT ON COLUMN billing_invoice.supplier_info_version IS '이 청구서에 표시한 공급자 정보의 회사 제공 정보 버전이다. 청구서를 연 뒤 회사 정보가 바뀌어도 당시 표시를 다시 만들 수 있다';
COMMENT ON TABLE billing_charge_attempt IS '자동 결제 재시도 기록이다. D0, D0+1시간, D0+3일, D0+7일에 최대 4회 시도한다. 이 스케줄은 서비스 계층이 관리한다';
COMMENT ON COLUMN billing_charge_attempt.id IS '결제 시도 내부 식별자';
COMMENT ON COLUMN billing_charge_attempt.invoice_id IS '대상 청구서';
COMMENT ON COLUMN billing_charge_attempt.attempt_no IS '같은 청구서 안에서의 결제 시도 회차';
COMMENT ON COLUMN billing_charge_attempt.attempted_at IS '시도 일시';
COMMENT ON COLUMN billing_charge_attempt.result IS 'PROCESSING 요청 중, VERIFYING PG 결과 확인 중, SUCCESS 승인 성공, FAILED 확정 실패';
COMMENT ON COLUMN billing_charge_attempt.failure_reason IS '결제 실패 사유';
COMMENT ON COLUMN billing_charge_attempt.failure_category IS '시도 실패 분류다. CARD_UNUSABLE은 카드 사용 불가, INSUFFICIENT_FUNDS는 잔액 부족, TIMEOUT은 응답 지연, OTHER는 그 밖의 사유다. result가 FAILED일 때만 값이 있다';
COMMENT ON COLUMN billing_charge_attempt.pg_transaction_id IS '토스 결제 paymentKey. 최대 200자이며 결제 조회·취소에 사용한다';
COMMENT ON COLUMN billing_charge_attempt.pg_order_id IS '시도별 고유 토스 주문 ID. 영문 대소문자·숫자·하이픈·밑줄 6자에서 64자만 허용한다';
COMMENT ON COLUMN billing_charge_attempt.idempotency_key IS '동일 시도 재전송에 재사용하는 UUID v4 형식의 PG 멱등키';
COMMENT ON COLUMN billing_charge_attempt.pg_response IS '비밀값과 카드 원문을 제거한 PG 응답 스냅샷';
COMMENT ON COLUMN billing_charge_attempt.resolved_at IS 'PG 결과를 성공이나 확정 실패로 판정한 시각';
COMMENT ON TABLE subscription_cancellation IS '해지예약. effective_at은 현재 유료기간 종료 시각. 기간 끝 전에는 revoked_at으로 예약취소 가능';
COMMENT ON COLUMN subscription_cancellation.id IS '구독 해지예약 내부 식별자';
COMMENT ON COLUMN subscription_cancellation.subscription_id IS '대상 구독';
COMMENT ON COLUMN subscription_cancellation.requested_at IS '요청 일시';
COMMENT ON COLUMN subscription_cancellation.effective_at IS '시행 시각';
COMMENT ON COLUMN subscription_cancellation.cancelled_by_membership_id IS '해지를 요청한 대표';
COMMENT ON COLUMN subscription_cancellation.revoked_at IS '폐기 일시';
COMMENT ON TABLE refund_request IS '청구 ID와 환불 사유 사건으로 한 번만 권리금액을 산정한다. 환불액 예약과 PG 취소요청은 청구 행 잠금 아래 직렬화한다. PG 결과가 불확실하면 VERIFYING을 유지하고 동일 멱등키와 PG 취소내역을 확인한다. reviewed_by_operator_id는 도메인 11에서 operator_account 테이블을 만든 뒤 FK를 추가한다. 중복결제와 오청구는 서버가 reason_event_id를 invoice_id 값으로 채워 접수하고 그 밖의 사유는 NULL로 접수한 뒤 운영자가 검토 때 채운다. reason_event_type은 요청이 생략하면 서버가 reason_code로 채운다. 환불 금액 계산 근거는 스냅샷 컬럼에 남긴다';
COMMENT ON COLUMN refund_request.id IS '환불 신청 내부 식별자';
COMMENT ON COLUMN refund_request.office_id IS '소속 사무소';
COMMENT ON COLUMN refund_request.invoice_id IS '대상 청구서';
COMMENT ON COLUMN refund_request.reason_code IS '해지, 인증 중단, 중복·오청구, 서비스 미제공, 늦은 승인, 정책 외 보상 중 환불 사유';
COMMENT ON COLUMN refund_request.reason_event_type IS '해지·인증 중단·장애 등 환불 원인 사건 종류다. INVOICE, SUBSCRIPTION_CANCELLATION, AUTH_SUSPENSION, SERVICE_INCIDENT, LATE_APPROVAL, POLICY_COMPENSATION 중 하나다. 요청이 생략하면 서버가 reason_code로 채우며 NULL은 허용하지 않는다. reason_code의 CANCELLATION은 SUBSCRIPTION_CANCELLATION, DUPLICATE_CHARGE와 INCORRECT_CHARGE는 INVOICE, SERVICE_FAILURE는 SERVICE_INCIDENT에 대응하고 나머지는 같은 이름이다';
COMMENT ON COLUMN refund_request.reason_event_id IS '동일 사건 재요청을 식별하는 원인 사건 ID. 중복·오청구 외 사유는 접수 때 비어 있고 운영자가 검토 때 채운다';
COMMENT ON COLUMN refund_request.requested_at IS '요청 일시';
COMMENT ON COLUMN refund_request.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN refund_request.reviewed_by_operator_id IS '검토한 운영자';
COMMENT ON COLUMN refund_request.reviewed_at IS '심사 처리 일시';
COMMENT ON COLUMN refund_request.refund_amount IS '산정된 환불 금액';
COMMENT ON COLUMN refund_request.entitlement_amount IS '사건별 총 환불 권리금액';
COMMENT ON COLUMN refund_request.previous_refund_amount IS '해당 사건에서 이미 완료한 환불 누계';
COMMENT ON COLUMN refund_request.reserved_amount IS '다른 진행 중 환불 요청에 예약된 금액';
COMMENT ON COLUMN refund_request.pg_idempotency_key IS '동일 PG 취소요청 재전송에 쓰는 UUID v4 멱등키';
COMMENT ON COLUMN refund_request.pg_refund_id IS 'PG 취소 거래 식별자';
COMMENT ON COLUMN refund_request.pg_cancel_response IS '비밀값을 제거한 PG 취소 응답 스냅샷';
COMMENT ON COLUMN refund_request.resolved_at IS 'PG 환불 결과를 확정한 시각';
COMMENT ON COLUMN refund_request.rejection_reason IS '거절 사유';
COMMENT ON COLUMN refund_request.failure_reason IS 'PG 환불이 확정 실패했을 때의 사유다. status가 FAILED일 때만 값이 있다';
COMMENT ON COLUMN refund_request.original_approved_amount IS '환불 계산 근거 스냅샷이다. 원래 PG가 승인한 청구 금액 원화';
COMMENT ON COLUMN refund_request.total_period_seconds IS '환불 계산 근거 스냅샷이다. 환불 대상 이용기간 전체의 초 수';
COMMENT ON COLUMN refund_request.remaining_period_seconds IS '환불 계산 근거 스냅샷이다. 환불 대상 이용기간 중 남은 초 수';
COMMENT ON COLUMN refund_request.coupon_excluded_amount IS '환불 계산 근거 스냅샷이다. 쿠폰 등으로 결제되지 않아 환불 산정에서 뺀 금액 원화';
COMMENT ON COLUMN refund_request.prior_compensation_amount IS '환불 계산 근거 스냅샷이다. 같은 이용기간에 이미 지급한 보상 금액 원화';
COMMENT ON COLUMN refund_request.effective_end_at IS '환불 계산 근거 스냅샷이다. 환불 기준이 되는 이용 종료 효력 시각';
COMMENT ON INDEX uq_refund_request_reason_without_event IS '원인 사건 ID가 아직 없는 접수 건은 같은 청구서에서 같은 환불 사유로 하나만 둔다. UNIQUE 제약은 NULL을 서로 다른 값으로 보므로 이 부분 인덱스가 중복 접수를 막는다';
COMMENT ON TABLE return_grant IS '구독종료나 탈퇴 직후 대표에게 발급하는 반환권한이다. 회원 세션과 분리된 별도 재인증 경로로 종료시각 T 이상, T+30×24시간 미만에 자료 반환 전용 접근을 허용한다. 이 접근 통제는 서비스 계층이 수행한다. 권한자를 바꿀 때는 기존 권한을 폐기해 replaced_by_grant_id로 새 권한을 가리키고 새 권한에 본인 확인 증빙과 등록관계 확인 증빙의 참조를 남긴다';
COMMENT ON COLUMN return_grant.id IS '반환권한 내부 식별자';
COMMENT ON COLUMN return_grant.office_id IS '소속 사무소';
COMMENT ON COLUMN return_grant.granted_to_user_id IS '발급 대상 사용자';
COMMENT ON COLUMN return_grant.granted_at IS '발급 일시';
COMMENT ON COLUMN return_grant.expires_at IS '만료 일시';
COMMENT ON COLUMN return_grant.revoked_at IS '폐기 일시';
COMMENT ON COLUMN return_grant.revoked_reason IS '권한을 폐기한 사유다. 권한자 변경으로 폐기한 경우를 포함하며 revoked_at이 있을 때만 값이 있다';
COMMENT ON COLUMN return_grant.identity_evidence_reference IS '권한자 변경 때 받은 본인 확인 증빙의 참조다';
COMMENT ON COLUMN return_grant.registration_relation_reference IS '권한자 변경 때 받은 사무소 등록관계 확인 증빙의 참조다';
COMMENT ON COLUMN return_grant.replaced_by_grant_id IS '권한자 변경으로 이 권한을 대체한 새 권한이다. 같은 사무소의 권한이어야 하며 값이 있으면 revoked_at가 있다';
COMMENT ON TABLE archive_grant IS '탈퇴 후 법정보존문서 전용 별도 보관계약이다. expires_at이 NULL이면 영구 계약이다. 보관계약을 거절하면 대표가 직접 보존한다. 수탁 사본은 반환기한 종료 후 파기한다. 이 처리는 서비스 계층이 수행한다. 권한자를 바꿀 때는 기존 권한을 폐기해 replaced_by_grant_id로 새 권한을 가리키고 새 권한에 본인 확인 증빙과 등록관계 확인 증빙의 참조를 남긴다';
COMMENT ON COLUMN archive_grant.id IS '보관권한 내부 식별자';
COMMENT ON COLUMN archive_grant.office_id IS '소속 사무소';
COMMENT ON COLUMN archive_grant.granted_to_user_id IS '발급 대상 사용자';
COMMENT ON COLUMN archive_grant.contract_reference IS '별도 보관계약 참조. 권한자가 바뀌면 새 권한의 contract_reference에 새 보관계약 참조를 저장한다';
COMMENT ON COLUMN archive_grant.granted_at IS '발급 일시';
COMMENT ON COLUMN archive_grant.expires_at IS '만료 일시';
COMMENT ON COLUMN archive_grant.terminated_at IS '계약 종료 처리 시각';
COMMENT ON COLUMN archive_grant.terminated_reason IS '계약을 종료한 사유다. 권한자 변경으로 종료한 경우를 포함하며 terminated_at이 있을 때만 값이 있다';
COMMENT ON COLUMN archive_grant.identity_evidence_reference IS '권한자 변경 때 받은 본인 확인 증빙의 참조다';
COMMENT ON COLUMN archive_grant.registration_relation_reference IS '권한자 변경 때 받은 사무소 등록관계 확인 증빙의 참조다';
COMMENT ON COLUMN archive_grant.replaced_by_grant_id IS '권한자 변경으로 이 권한을 대체한 새 권한이다. 같은 사무소의 권한이어야 하며 값이 있으면 terminated_at가 있다';
COMMENT ON TABLE import_batch IS '데이터 이전 실행 단위다. 대표만 업로드할 수 있다. 신규생성과 기존레코드연결만 지원하며 대량 덮어쓰기는 지원하지 않는다. 완료 후 24시간 이내면 취소할 수 있다. 외부연결, 후속수정, 법정보존서류가 생긴 데이터는 취소할 수 없다. 이 제한은 서비스 계층이 수행한다. 월 5회 한도는 실제 데이터가 1건 이상 반영된 실행 묶음을 기준으로 서비스 계층이 카운트한다. 실행 결과 건수와 취소 결과는 이 표에 요약하고 행 단위 성공·실패는 import_row_result에 남긴다';
COMMENT ON COLUMN import_batch.id IS '이전 실행 단위 내부 식별자';
COMMENT ON COLUMN import_batch.office_id IS '소속 사무소';
COMMENT ON COLUMN import_batch.uploaded_by_membership_id IS '업로드한 담당자';
COMMENT ON COLUMN import_batch.source_system IS '원본 시스템 이름';
COMMENT ON COLUMN import_batch.target_type IS '대상 종류';
COMMENT ON COLUMN import_batch.file_object_key IS '업로드 파일 객체 키';
COMMENT ON COLUMN import_batch.file_name IS '업로드한 원본 파일 이름이다. 상세 응답의 fileName이다';
COMMENT ON COLUMN import_batch.selected_sheet_name IS '엑셀 파일에서 대표가 고른 시트 이름이다. 시트가 하나뿐인 파일과 CSV는 NULL이다';
COMMENT ON COLUMN import_batch.sheets IS '업로드 파일의 시트 목록이다. 항목마다 name, row_count, column_count를 담는 JSON 배열이다. CSV는 NULL이다';
COMMENT ON COLUMN import_batch.row_count IS '처리 대상 행 수';
COMMENT ON COLUMN import_batch.succeeded_count IS '실행 결과의 성공 건수다. 실행 전에는 NULL이다';
COMMENT ON COLUMN import_batch.failed_count IS '실행 결과의 실패 건수다. 실행 전에는 NULL이다. 실패한 줄은 import_row_result에 사유와 함께 남는다';
COMMENT ON COLUMN import_batch.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN import_batch.executed_at IS '실행 처리 일시';
COMMENT ON COLUMN import_batch.cancellable_until IS '이 실행을 취소할 수 있는 기한. 실행 완료 후 24시간';
COMMENT ON COLUMN import_batch.cancelled_at IS '취소 처리 일시';
COMMENT ON COLUMN import_batch.cancelled_count IS '취소로 되돌린 항목 수다. 취소 전에는 NULL이고 취소하면 1 이상이다';
COMMENT ON COLUMN import_batch.not_cancelled_items IS '취소에서 제외된 항목과 사유 목록이다. entityType, entityId, reason을 담는 JSON 배열이며 reason은 EXTERNAL_LINK, FOLLOW_UP_EDIT, LEGAL_RETENTION 중 하나다. 취소 전에는 NULL이고 제외 항목이 없으면 빈 배열이다';
COMMENT ON COLUMN import_batch.failure_reason IS '실패 사유 요약이다. 상태가 FAILED이거나 실패 건수가 있을 때 값이 있다';
COMMENT ON COLUMN import_batch.created_at IS '생성 일시';
COMMENT ON TABLE import_mapping_version IS '이전 실행 단위별 매핑 확정 버전이다. 매핑을 바꿀 때마다 version_no를 올린 새 행을 만들고 이전 행은 고치지 않는다. 직접 실행은 가장 최근 버전으로 미리보기와 실행을 하며, 유료 지원은 대표가 승인한 버전만 실행한다. 확정 주체가 소속 구성원이면 membership 쪽, 이전담당 운영자면 operator 쪽 컬럼만 채운다';
COMMENT ON COLUMN import_mapping_version.id IS '매핑 버전 내부 식별자';
COMMENT ON COLUMN import_mapping_version.import_batch_id IS '대상 실행 단위';
COMMENT ON COLUMN import_mapping_version.office_id IS '소속 사무소';
COMMENT ON COLUMN import_mapping_version.version_no IS '실행 단위별 1부터 증가';
COMMENT ON COLUMN import_mapping_version.source_system IS '연결키 구성용 원본 시스템 이름';
COMMENT ON COLUMN import_mapping_version.target_type IS '`CUSTOMER`, `PROPERTY`, `CONTRACT` 중 하나';
COMMENT ON COLUMN import_mapping_version.confirmed_by_type IS '`MEMBERSHIP`, `OPERATOR` 중 하나';
COMMENT ON COLUMN import_mapping_version.confirmed_by_membership_id IS '대표가 확정한 경우의 소속';
COMMENT ON COLUMN import_mapping_version.confirmed_by_operator_id IS '이전담당 운영자가 확정한 경우의 운영자';
COMMENT ON COLUMN import_mapping_version.created_at IS '버전 생성 일시';
COMMENT ON TABLE import_mapping_item IS '매핑 버전 한 건에 속한 열 대응이다. 같은 버전 안에서 원본 열은 한 번만 쓴다. 제안에서 받은 신뢰도는 참고값이며 직접 입력한 대응은 신뢰도가 없다';
COMMENT ON COLUMN import_mapping_item.id IS '매핑 항목 내부 식별자';
COMMENT ON COLUMN import_mapping_item.mapping_version_id IS '소속 매핑 버전';
COMMENT ON COLUMN import_mapping_item.source_column IS '업로드 파일의 열 이름';
COMMENT ON COLUMN import_mapping_item.target_field IS '사이로 대상 필드 이름';
COMMENT ON COLUMN import_mapping_item.confidence IS 'AI 제안에서 가져온 0~1 신뢰도. 직접 입력한 대응은 NULL';
COMMENT ON TABLE import_record_link IS '사무소, 원본시스템, 원본유형, 원본ID로 이루어진 연결키로 재실행 시 같은 원본 레코드를 다시 찾는다. 다른 원본시스템의 동일 번호는 자동으로 연결하지 않는다';
COMMENT ON COLUMN import_record_link.id IS '이전 레코드 연결 내부 식별자';
COMMENT ON COLUMN import_record_link.batch_id IS '실행한 배치';
COMMENT ON COLUMN import_record_link.office_id IS '소속 사무소';
COMMENT ON COLUMN import_record_link.source_system IS '원본 시스템 이름';
COMMENT ON COLUMN import_record_link.source_type IS '원천 종류';
COMMENT ON COLUMN import_record_link.source_id IS '원천 레코드 ID';
COMMENT ON COLUMN import_record_link.target_entity_type IS '대상 엔터티 종류';
COMMENT ON COLUMN import_record_link.target_entity_id IS '사이로 쪽 대상 레코드의 ID';
COMMENT ON COLUMN import_record_link.created_at IS '생성 일시';
COMMENT ON TABLE import_row_result IS '이전 실행의 행 단위 결과다. 원본 파일의 행 번호마다 성공 또는 실패와 실패 사유를 보존한다. 실패한 줄만 다시 처리하는 재처리와 import_batch의 실패 건수 집계에 쓴다. 재처리로 성공하면 result를 SUCCEEDED로 바꾸고 failure_reason을 비운다';
COMMENT ON COLUMN import_row_result.id IS '이전 행 결과 내부 식별자';
COMMENT ON COLUMN import_row_result.batch_id IS '행이 속한 이전 실행 단위';
COMMENT ON COLUMN import_row_result.office_id IS '소속 사무소';
COMMENT ON COLUMN import_row_result.source_row_number IS '업로드 파일에서의 원본 행 번호. 1부터 센다';
COMMENT ON COLUMN import_row_result.result IS '행 단위 실행 결과다. SUCCEEDED는 성공, FAILED는 실패다';
COMMENT ON COLUMN import_row_result.failure_reason IS '행이 실패한 사유다. result가 FAILED일 때만 값이 있다';
COMMENT ON COLUMN import_row_result.created_at IS '행 결과 기록 일시';
COMMENT ON COLUMN import_row_result.updated_at IS '행 결과를 마지막으로 바꾼 일시. 재처리로 결과가 바뀌면 갱신한다';
COMMENT ON INDEX ix_import_row_result_failed IS '실패한 줄만 다시 처리하거나 실패 건수를 셀 때 쓴다';
COMMENT ON TABLE import_support_request IS '유료 이전 지원이다. 기본 가격은 VAT 포함 22만 원이며, 원본시스템 1종에 최대 5만 레코드, 수정요청 1회를 포함한다. 표준 범위는 결제 후 5영업일 목표다. 이 목표는 내부 목표이며 법정 기한은 아니다. 신청 때 업로드한 이전 파일의 실행 단위를 연결하며 한 실행 단위에는 취소·거절되지 않은 신청이 하나만 있을 수 있다. 신청부터 취소 또는 거절 전까지 그 실행 단위는 대표가 직접 매핑·실행할 수 없고 취소(결제 전 대표)나 거절(견적 수락 전 운영자)이 일어나는 순간 직접 권한이 돌아온다. 결제 후 이전담당이 매핑을 정제하고 대표에게 검수를 제출하며 대표가 승인한 매핑 버전으로만 실행한다. 승인 뒤에는 매핑을 바꿀 수 없다. 일반결제 주문과 PG 결제 정보는 payment_order_id, payment_amount, pg_transaction_id, paid_at에 남긴다. 실행 결과 요약은 연결된 import_batch의 succeeded_count와 failed_count로 대신하고 이 표에 따로 두지 않는다';
COMMENT ON COLUMN import_support_request.id IS '유료 이전 지원 내부 식별자';
COMMENT ON COLUMN import_support_request.office_id IS '소속 사무소';
COMMENT ON COLUMN import_support_request.source_system IS '원본 시스템 이름';
COMMENT ON COLUMN import_support_request.estimated_row_count IS '견적용 예상 행 수';
COMMENT ON COLUMN import_support_request.quote_amount IS '견적 금액';
COMMENT ON COLUMN import_support_request.quote_scope_note IS '견적 범위 비고다. 운영자가 견적을 낼 때 원본 시스템 수와 레코드 수의 조정을 적으며 응답의 scopeNote로 돌려준다. QUOTED 이후에만 값이 있다';
COMMENT ON COLUMN import_support_request.payment_order_id IS '일반결제용 PG 주문 ID다. 견적 수락 때 서버가 만들고 영문 대소문자·숫자·하이픈·밑줄 6자에서 64자만 허용한다. 결제 확정 요청의 주문 ID와 대조한다';
COMMENT ON COLUMN import_support_request.payment_amount IS '결제할 VAT 포함 금액이다. 견적 수락 때 정해지며 quote_amount와 같다';
COMMENT ON COLUMN import_support_request.pg_transaction_id IS 'PG 결제 키다. 결제 확정이 성공했을 때 저장하며 최대 200자다. 결제 조회와 취소에 쓴다';
COMMENT ON COLUMN import_support_request.paid_at IS '결제 확정 시각이다. PAID 이후 상태에서만 값이 있다';
COMMENT ON COLUMN import_support_request.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN import_support_request.requested_at IS '요청 일시';
COMMENT ON COLUMN import_support_request.delivered_at IS '납품 일시';
COMMENT ON COLUMN import_support_request.import_batch_id IS '신청 때 대표가 올린 이전 파일의 실행 단위. 취소·거절된 신청을 뺀 활성 신청 하나에만 연결할 수 있다';
COMMENT ON COLUMN import_support_request.assigned_operator_id IS '처리를 시작한 이전담당 운영자';
COMMENT ON COLUMN import_support_request.processing_started_at IS '결제 후 이전담당이 처리를 시작한 시각';
COMMENT ON COLUMN import_support_request.submitted_mapping_version_id IS '대표 검수에 제출한 매핑 버전';
COMMENT ON COLUMN import_support_request.submitted_at IS '대표 검수를 요청한 시각';
COMMENT ON COLUMN import_support_request.change_request_count IS '대표가 검수에서 수정을 요청한 횟수. 표준 범위에 포함된 수정요청은 1회다';
COMMENT ON COLUMN import_support_request.change_requested_at IS '대표가 수정을 요청한 시각';
COMMENT ON COLUMN import_support_request.change_request_reason IS '대표가 적은 수정 요청 내용';
COMMENT ON COLUMN import_support_request.approved_mapping_version_id IS '대표가 승인한 매핑 버전. 실행은 이 버전으로만 한다';
COMMENT ON COLUMN import_support_request.approved_by_membership_id IS '승인한 대표의 소속';
COMMENT ON COLUMN import_support_request.approved_at IS '대표 승인 시각';
COMMENT ON COLUMN import_support_request.cancelled_by_membership_id IS '결제 전 신청을 취소한 대표의 소속';
COMMENT ON COLUMN import_support_request.cancelled_at IS '대표가 결제 전에 신청을 취소한 시각. 취소하면 그 순간 대표의 직접 매핑·실행 권한이 돌아온다';
COMMENT ON COLUMN import_support_request.cancel_reason IS '대표가 적은 취소 사유. 선택 입력';
COMMENT ON COLUMN import_support_request.rejected_by_operator_id IS '신청을 거절한 이전담당 운영자';
COMMENT ON COLUMN import_support_request.rejected_at IS '운영자가 견적 수락 전에 신청을 거절한 시각. 거절하면 그 순간 대표의 직접 매핑·실행 권한이 돌아온다';
COMMENT ON COLUMN import_support_request.reject_reason IS '운영자가 적은 거절 사유. 대표에게 공개한다';
COMMENT ON COLUMN import_support_request.updated_at IS '이전 지원 집계의 마지막 변경 시각';
COMMENT ON COLUMN import_support_request.version IS '이전 지원 집계의 낙관적 잠금 버전';
COMMENT ON TABLE export_job IS '자료 내보내기 작업이다. scope가 FULL이면 전체 자료와 첨부를 ZIP으로 만들며 대표만 요청할 수 있다. TABLES이면 table_codes에 담은 표만 내보내며 소속공인중개사는 office_export_table_policy가 허용한 표만 요청할 수 있다. 생성 파일은 file_expires_at에 삭제하고 다운로드 URL은 저장하지 않으며 매 다운로드 요청마다 권한을 다시 검사한다. 표 코드의 전체 집합은 PROPERTY, CUSTOMER, CONTRACT, FEE, PAYMENT, TASK, VISIT 일곱 가지다';
COMMENT ON COLUMN export_job.id IS '내보내기 작업 내부 식별자';
COMMENT ON COLUMN export_job.office_id IS '소속 사무소';
COMMENT ON COLUMN export_job.created_by_membership_id IS '내보내기를 요청한 구성원의 소속. 사무소 일치를 복합 FK로 검증한다';
COMMENT ON COLUMN export_job.scope IS '내보내기 범위다. FULL은 전체 자료와 첨부 ZIP으로 대표만 요청할 수 있고 TABLES는 table_codes에 담은 표만 내보낸다';
COMMENT ON COLUMN export_job.table_codes IS 'TABLES 범위의 대상 표 코드 목록이다. PROPERTY, CUSTOMER, CONTRACT, FEE, PAYMENT, TASK, VISIT 중 하나 이상을 담는 JSON 배열이다. FULL이면 NULL이다';
COMMENT ON COLUMN export_job.status IS '처리 상태다. PENDING은 생성 중, COMPLETED는 완료, FAILED는 실패다';
COMMENT ON COLUMN export_job.file_object_key IS '생성한 파일의 비공개 저장소 키다. COMPLETED일 때만 값이 있고 공개 URL이 아니다';
COMMENT ON COLUMN export_job.file_expires_at IS '생성 파일 삭제 시각이다. 요청 시각에서 정확히 24시간 뒤다';
COMMENT ON COLUMN export_job.failure_reason IS '생성 실패 사유다. FAILED일 때만 값이 있다';
COMMENT ON COLUMN export_job.created_at IS '내보내기 요청 일시';
COMMENT ON COLUMN export_job.updated_at IS '처리 상태를 마지막으로 바꾼 일시';
COMMENT ON INDEX ix_export_job_office_created IS '대표가 사무소 전체 내보내기 목록을 최근순으로 조회한다';
COMMENT ON INDEX ix_export_job_creator_created IS '소속공인중개사가 본인이 만든 내보내기 목록을 최근순으로 조회한다';
COMMENT ON TABLE office_export_table_policy IS '사무소별 내보내기 허용 표 정책이다. 소속공인중개사는 이 표에 행이 있는 표 코드만 내보낼 수 있고 대표는 모든 표를 내보낼 수 있다. 대표가 허용 목록을 저장하면 보낸 목록이 기존 목록 전체를 대체하며 행이 없으면 허용된 표가 없다. 내보낼 수 있는 표 코드의 전체 집합은 PROPERTY, CUSTOMER, CONTRACT, FEE, PAYMENT, TASK, VISIT 일곱 가지다';
COMMENT ON COLUMN office_export_table_policy.id IS '내보내기 허용 표 내부 식별자';
COMMENT ON COLUMN office_export_table_policy.office_id IS '정책을 가진 사무소';
COMMENT ON COLUMN office_export_table_policy.table_code IS '내보내기를 허용한 표 코드다. PROPERTY 매물, CUSTOMER 고객, CONTRACT 계약, FEE 수수료, PAYMENT 잔금·지급, TASK 업무, VISIT 방문이다';
COMMENT ON COLUMN office_export_table_policy.created_at IS '허용 표를 저장한 일시';
COMMENT ON TABLE operator_account IS '사이로팀 운영자 계정이다. app_user, office_membership과 완전히 분리하며 공개 가입을 두지 않는다. 화이트리스트에 등록된 계정만 로그인할 수 있다. MFA를 필수로 한다. 세션은 30분 미활동 또는 8시간 절대만료로 종료한다. 고위험작업은 5분 이내 재인증이 필요하다. 이 세션과 재인증 규칙은 서비스 계층이 구현한다. 계정은 운영자 초대를 수락해야만 만들어지며 최초 운영자 2명만 서비스 공개 전 배포책임자가 일회성으로 만든다. 2차 인증은 TOTP이며 로그인과 고위험작업 재인증에 같은 비밀값을 쓴다';
COMMENT ON COLUMN operator_account.id IS '운영자 계정 내부 식별자';
COMMENT ON COLUMN operator_account.kakao_provider_key IS '카카오 고유 회원번호';
COMMENT ON COLUMN operator_account.name IS '이름';
COMMENT ON COLUMN operator_account.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN operator_account.mfa_enabled IS 'MFA 사용 여부';
COMMENT ON COLUMN operator_account.created_at IS '생성 일시';
COMMENT ON COLUMN operator_account.totp_secret_encrypted IS 'TOTP 비밀값을 앱 암호화 키로 암호화한 값. 로그·응답·감사 로그에 남기지 않는다';
COMMENT ON COLUMN operator_account.mfa_failed_count IS '2차 인증 코드를 연속으로 틀린 횟수. 성공하면 0으로 돌아간다';
COMMENT ON COLUMN operator_account.mfa_locked_until IS '5회 연속 실패 시 15분 잠금의 만료 시각';
COMMENT ON TABLE operator_role_assignment IS '운영자 8역할이다. 보안관리자, 심사담당, 고객지원, 결제담당, 이전담당, 개인정보담당, 운영담당, 경영조회로 구성된다. 한 운영자가 여러 역할을 겸할 수 있다. 복수 역할로 자기승인을 우회하지 못하도록 하는 검사는 서비스 계층이 수행한다';
COMMENT ON COLUMN operator_role_assignment.id IS '운영자 역할 배정 내부 식별자';
COMMENT ON COLUMN operator_role_assignment.operator_account_id IS '대상 운영자';
COMMENT ON COLUMN operator_role_assignment.role IS '역할';
COMMENT ON COLUMN operator_role_assignment.assigned_at IS '배정 일시';
COMMENT ON TABLE operator_invitation IS '운영자 초대 기록이다. 보안관리자가 이름, 이메일, 부여할 역할을 지정해 만든다. 초대 유효기간은 생성 후 72시간이다. 수락자는 초대 링크, 카카오 인증, 2차 인증 등록과 확인 코드 입력을 모두 마친 뒤에만 운영자 계정과 역할 배정이 생긴다. 카카오 식별값은 초대 수락 전에는 operator_account에 넣지 않고 이 표에만 둔다. 같은 이메일의 대기 중 초대는 1건만 허용한다. 만료 판정은 expires_at 기준으로 서비스 계층이 수행하고 상태값은 정리 작업이 EXPIRED로 바꾼다';
COMMENT ON COLUMN operator_invitation.id IS '초대 내부 식별자';
COMMENT ON COLUMN operator_invitation.invitee_name IS '수락하면 운영자 계정의 표시 이름이 된다';
COMMENT ON COLUMN operator_invitation.invitee_email IS '초대 링크를 보내는 주소. 소문자로 저장하며 운영자 계정에는 저장하지 않는다';
COMMENT ON COLUMN operator_invitation.token_hash IS '초대 토큰의 SHA-256 해시. 원문은 이메일 링크로만 전달하고 저장하지 않는다';
COMMENT ON COLUMN operator_invitation.status IS '`PENDING`, `ACCEPTED`, `EXPIRED`, `CANCELLED` 중 하나';
COMMENT ON COLUMN operator_invitation.invited_by_operator_id IS '초대를 만든 보안관리자';
COMMENT ON COLUMN operator_invitation.expires_at IS '생성 후 정확히 72시간';
COMMENT ON COLUMN operator_invitation.kakao_provider_key IS '수락자가 카카오 인증을 마친 뒤 저장하는 카카오 고유 회원번호. 수락 완료 시 운영자 계정으로 옮긴다';
COMMENT ON COLUMN operator_invitation.pending_totp_secret_encrypted IS '2차 인증 등록 중인 TOTP 비밀값을 앱 암호화 키로 암호화한 값. 수락 완료나 만료 때 삭제한다';
COMMENT ON COLUMN operator_invitation.enrollment_expires_at IS '카카오 인증 완료 후 15분. 이 시각까지 확인 코드를 입력해야 수락된다';
COMMENT ON COLUMN operator_invitation.accepted_operator_id IS '수락 완료 시 생성된 운영자 계정';
COMMENT ON COLUMN operator_invitation.accepted_at IS '수락 완료 일시';
COMMENT ON COLUMN operator_invitation.cancelled_by_operator_id IS '대기 중 초대를 취소한 보안관리자';
COMMENT ON COLUMN operator_invitation.cancelled_at IS '초대 취소 일시';
COMMENT ON COLUMN operator_invitation.created_at IS '초대 생성 일시';
COMMENT ON COLUMN operator_invitation.updated_at IS '초대 집계의 마지막 변경 시각';
COMMENT ON COLUMN operator_invitation.version IS '초대 집계의 낙관적 잠금 버전';
COMMENT ON INDEX uq_operator_invitation_pending_email IS '대기 중 초대는 같은 이메일로 1건만 허용한다';
COMMENT ON TABLE operator_invitation_role IS '초대 수락 시 operator_role_assignment로 옮길 역할 목록이다. 초대 한 건에 같은 역할을 두 번 담을 수 없다. 초대 생성 뒤에는 수정하지 않으며 바꾸려면 초대를 취소하고 다시 만든다';
COMMENT ON COLUMN operator_invitation_role.id IS '초대 역할 내부 식별자';
COMMENT ON COLUMN operator_invitation_role.invitation_id IS '대상 초대';
COMMENT ON COLUMN operator_invitation_role.role IS '8개 운영 역할 중 하나';
COMMENT ON TABLE ops_approval_request IS '원문 접근과 고위험 작업의 운영 승인 워크플로다. 승인자는 요청자·수혜자와 달라야 하며 이 규칙은 DB CHECK로 강제한다. 승인 유효기간은 24시간이다. 승인자의 권한이 회수되거나 대상계정이 정지되면 미실행 승인을 무효화하고 실행 직전에 재검사한다. 이 무효화와 재검사는 서비스 계층이 수행한다. 원문 접근의 request_type은 RAW_VIEW(열람)와 RAW_DOWNLOAD(파일 다운로드)이며 두 종류는 서로 다른 승인 요청으로 받는다. 요청에는 근거 유형과 근거 기록을 함께 남기며 대표 요청 근거는 연결된 문의가 있어야 한다. 운영자 접근·감사 기록의 보관 기간(OPS_AUDIT_LOG)을 따라 지운다. 그 승인으로 실행한 원문 접근 기록이 남아 있는 동안은 지우지 않고 그 기록을 먼저 지운다';
COMMENT ON COLUMN ops_approval_request.id IS '운영 승인 요청 내부 식별자';
COMMENT ON COLUMN ops_approval_request.request_type IS '요청 종류';
COMMENT ON COLUMN ops_approval_request.requested_by_operator_id IS '요청한 운영자';
COMMENT ON COLUMN ops_approval_request.beneficiary_operator_id IS '요청 결과의 수혜자 운영자';
COMMENT ON COLUMN ops_approval_request.target_type IS '대상 종류';
COMMENT ON COLUMN ops_approval_request.target_id IS '대상 레코드의 ID';
COMMENT ON COLUMN ops_approval_request.purpose IS '목적';
COMMENT ON COLUMN ops_approval_request.scope IS '범위·권한 범위';
COMMENT ON COLUMN ops_approval_request.basis_type IS '승인 요청의 근거 유형이다. REPRESENTATIVE_REQUEST는 사무소 대표의 요청이고 LEGAL_BASIS는 법령상 근거다';
COMMENT ON COLUMN ops_approval_request.basis_note IS '근거를 설명하는 기록이다. 대표 요청이면 요청 경위를, 법령상 근거이면 근거 법령과 내용을 적는다. 공백만 있는 값은 둘 수 없다';
COMMENT ON COLUMN ops_approval_request.linked_inquiry_id IS '근거가 된 대표 요청 문의다. basis_type이 REPRESENTATIVE_REQUEST이면 반드시 값이 있다. support_inquiry가 이 표보다 뒤에 만들어지므로 FK는 그 표를 만든 뒤에 추가한다';
COMMENT ON COLUMN ops_approval_request.office_id IS '승인 요청 대상 사무소다. 사무소와 무관한 작업이면 NULL이다';
COMMENT ON COLUMN ops_approval_request.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN ops_approval_request.approved_by_operator_id IS '승인한 운영자';
COMMENT ON COLUMN ops_approval_request.approved_at IS '승인 처리 일시';
COMMENT ON COLUMN ops_approval_request.expires_at IS '만료 일시';
COMMENT ON COLUMN ops_approval_request.created_at IS '생성 일시';
COMMENT ON COLUMN ops_approval_request.rejected_by_operator_id IS '승인 요청을 거절한 개인정보담당 운영자';
COMMENT ON COLUMN ops_approval_request.rejected_at IS '승인 요청을 거절한 시각';
COMMENT ON COLUMN ops_approval_request.reject_reason IS '승인자가 적은 거절 사유';
COMMENT ON TABLE ops_raw_access_grant IS '승인된 원문 접근을 실제로 실행한 기록이다. 5분 재인증 후 1회 실행한다. 원문 접근 창은 정확히 60분이다. 운영 승인 유효기간 24시간과는 별개의 타이머다. 열람 승인과 다운로드 승인은 별개이며 열람 승인으로는 파일을 받을 수 없다. 승인 1건은 1회만 실행하며 다운로드 파일은 실행한 운영자가 60분 안에 한 번만 받을 수 있다';
COMMENT ON COLUMN ops_raw_access_grant.id IS '원문 접근 실행 내부 식별자';
COMMENT ON COLUMN ops_raw_access_grant.approval_request_id IS '근거가 된 승인 요청';
COMMENT ON COLUMN ops_raw_access_grant.target_type IS '대상 종류';
COMMENT ON COLUMN ops_raw_access_grant.target_id IS '대상 레코드의 ID';
COMMENT ON COLUMN ops_raw_access_grant.executed_by_operator_id IS '실행한 운영자';
COMMENT ON COLUMN ops_raw_access_grant.executed_at IS '실행 처리 일시';
COMMENT ON COLUMN ops_raw_access_grant.expires_at IS '만료 일시';
COMMENT ON COLUMN ops_raw_access_grant.request_type IS '`RAW_VIEW`(열람), `RAW_DOWNLOAD`(파일 다운로드). 승인 요청의 종류와 같아야 한다';
COMMENT ON COLUMN ops_raw_access_grant.file_object_key IS '다운로드 접근에서 서버가 만든 비공개 파일의 저장소 키. 외부에 공개하는 URL이 아니다';
COMMENT ON COLUMN ops_raw_access_grant.file_sha256 IS '다운로드 파일의 SHA-256. 전달 파일 무결성 확인용';
COMMENT ON COLUMN ops_raw_access_grant.downloaded_at IS '파일을 실제로 내려받은 시각. 승인 1건당 1회만 허용한다';
COMMENT ON COLUMN ops_raw_access_grant.revoked_at IS '보안관리자가 접근을 회수한 시각';
COMMENT ON COLUMN ops_raw_access_grant.revoked_by_operator_id IS '접근을 회수한 보안관리자';
COMMENT ON COLUMN ops_raw_access_grant.revoke_reason IS '회수 사유';
COMMENT ON TABLE ops_audit_log IS '운영자 행위 감사 이력이다. 적법 보유기간이 만료되어 자동으로 파기하는 경우를 제외하면 임의로 삭제하지 않는다. 이 규칙은 서비스 계층이 강제한다';
COMMENT ON COLUMN ops_audit_log.id IS '운영자 감사 로그 내부 식별자';
COMMENT ON COLUMN ops_audit_log.operator_account_id IS '대상 운영자';
COMMENT ON COLUMN ops_audit_log.action_type IS '행위 종류';
COMMENT ON COLUMN ops_audit_log.target_type IS '대상 종류';
COMMENT ON COLUMN ops_audit_log.target_id IS '대상 레코드의 ID';
COMMENT ON COLUMN ops_audit_log.detail IS '상세 내용';
COMMENT ON COLUMN ops_audit_log.created_at IS '생성 일시';
COMMENT ON TABLE office_registration_review_check IS '사무소 인증 심사의 필수 확인 항목 체크다. 신청의 제출 버전마다 REVISION_MATCH, SOURCE_VERIFIED, REGISTRATION_RELATION, QUALIFICATION_EDUCATION, EMPLOYMENT_ROSTER 다섯 항목을 둔다. 재제출로 revision_no가 늘면 새 행으로 시작하며 이전 버전의 확인 상태를 이어받지 않는다. 다섯 항목이 모두 checked일 때만 승인할 수 있고 이 검사는 서비스 계층이 수행한다. 확인한 운영자와 시각은 서버가 세션의 운영자와 서버 시각으로 채우고 확인을 해제하면 비운다';
COMMENT ON COLUMN office_registration_review_check.id IS '심사 확인 체크 내부 식별자';
COMMENT ON COLUMN office_registration_review_check.registration_id IS '대상 사업자 인증 신청';
COMMENT ON COLUMN office_registration_review_check.revision_no IS '확인 상태가 적용되는 제출 버전. 신청의 재제출 버전 번호와 같다';
COMMENT ON COLUMN office_registration_review_check.item_code IS '필수 확인 항목 코드다. REVISION_MATCH는 제출 버전, SOURCE_VERIFIED는 확인 출처, REGISTRATION_RELATION은 등록관계, QUALIFICATION_EDUCATION은 자격·교육, EMPLOYMENT_ROSTER는 고용명부 대조 항목이다';
COMMENT ON COLUMN office_registration_review_check.checked IS '확인 완료 여부다. 확인을 해제하면 false로 돌아가고 승인 가능 여부도 false가 된다';
COMMENT ON COLUMN office_registration_review_check.checked_by_operator_id IS '확인한 심사담당 운영자다. checked가 true일 때만 값이 있다';
COMMENT ON COLUMN office_registration_review_check.checked_at IS '확인한 서버 시각이다. checked가 true일 때만 값이 있다';
COMMENT ON COLUMN office_registration_review_check.created_at IS '체크 행 생성 일시';
COMMENT ON COLUMN office_registration_review_check.updated_at IS '체크 상태를 마지막으로 바꾼 일시';
COMMENT ON TABLE member_emergency_suspension IS '/ops 콘솔의 회원 긴급 접근 중단 실행 기록이다. 처리 즉시 대상 세션을 종료하고 소속 사무소 대표에게 통지한다. 회원 계정 상태는 바꾸지 않으며 app_user.account_status에 SUSPENDED를 저장하지 않는다. 회원 상세의 securityEvents가 이 표를 최근순으로 최대 20건 보여 준다. 세션 목록은 별도 세션 저장소가 관리하므로 session_id에는 세션 저장소가 목록용으로 내주는 불투명 식별자를 그대로 기록한다';
COMMENT ON COLUMN member_emergency_suspension.id IS '긴급 접근 중단 내부 식별자';
COMMENT ON COLUMN member_emergency_suspension.user_id IS '접근을 중단한 회원';
COMMENT ON COLUMN member_emergency_suspension.scope IS '중단 범위다. ALL_SESSIONS는 계정의 모든 세션, SPECIFIC_SESSION은 지정한 세션 하나다';
COMMENT ON COLUMN member_emergency_suspension.session_id IS 'SPECIFIC_SESSION일 때 끊은 세션의 불투명 식별자다. 회원 상세 응답 sessions[].sessionId의 값이며 ALL_SESSIONS이면 NULL이다';
COMMENT ON COLUMN member_emergency_suspension.reason IS '중단 사유다. 공백만 있는 값은 둘 수 없다';
COMMENT ON COLUMN member_emergency_suspension.suspended_at IS '세션을 무효화한 시각';
COMMENT ON COLUMN member_emergency_suspension.review_at IS '재검토 예정 시각이다. 중단 시각보다 늦어야 한다';
COMMENT ON COLUMN member_emergency_suspension.suspended_by_operator_id IS '중단을 실행한 운영자';
COMMENT ON INDEX ix_member_emergency_suspension_user IS '회원 상세의 긴급 접근 중단 기록을 최근순으로 조회한다';
COMMENT ON TABLE support_inquiry IS '유형별 문의 접수·배정·답변·마감. office_id는 가입 전 문의 등에서 NULL 가능. 보관 기간이 지나도 개인정보 권리 요청이나 운영 승인 요청이 이 문의를 참조하는 동안은 지우지 않고 참조하는 행의 보관이 끝난 뒤 지운다';
COMMENT ON COLUMN support_inquiry.id IS '고객 문의 내부 식별자';
COMMENT ON COLUMN support_inquiry.office_id IS '소속 사무소';
COMMENT ON COLUMN support_inquiry.requester_user_id IS '문의 작성자 사용자 ID다. 본인 이력 조회는 이 값과 세션 사용자 ID가 같아야 한다';
COMMENT ON COLUMN support_inquiry.category IS '문의 유형';
COMMENT ON COLUMN support_inquiry.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN support_inquiry.priority IS '지원 티켓 처리 우선순위다. LOW, NORMAL, HIGH 중 하나다';
COMMENT ON COLUMN support_inquiry.assigned_operator_id IS '배정된 운영자';
COMMENT ON COLUMN support_inquiry.request_scope IS '요청자가 명시한 처리 대상과 범위';
COMMENT ON COLUMN support_inquiry.content IS '내용';
COMMENT ON COLUMN support_inquiry.answer IS '최근 공개 답변의 조회용 스냅샷이다. 이전 답변은 메시지 원장에 남긴다';
COMMENT ON COLUMN support_inquiry.response_due_at IS '우선순위와 법정 기한을 반영한 첫 답변 목표 시각';
COMMENT ON COLUMN support_inquiry.answered_at IS '최근 공개 답변 시각';
COMMENT ON COLUMN support_inquiry.created_at IS '생성 일시';
COMMENT ON COLUMN support_inquiry.closed_at IS '종료 처리 일시';
COMMENT ON TABLE support_inquiry_message IS '지원 티켓의 공개 대화와 운영자 내부 메모를 생성 시각 순으로 남기는 원장이다. 최초 문의는 support_inquiry.content에 보관한다';
COMMENT ON COLUMN support_inquiry_message.id IS '문의 메시지 내부 식별자';
COMMENT ON COLUMN support_inquiry_message.inquiry_id IS '대상 지원 티켓';
COMMENT ON COLUMN support_inquiry_message.author_type IS 'REQUESTER는 문의 작성자, OPERATOR는 담당 운영자다';
COMMENT ON COLUMN support_inquiry_message.author_user_id IS '작성자 메시지의 사용자 ID';
COMMENT ON COLUMN support_inquiry_message.author_operator_id IS '운영자 메시지의 운영자 ID';
COMMENT ON COLUMN support_inquiry_message.visibility IS 'PUBLIC은 문의자에게 공개하고 INTERNAL은 운영자에게만 공개한다';
COMMENT ON COLUMN support_inquiry_message.content IS '추가 메시지 본문';
COMMENT ON COLUMN support_inquiry_message.created_at IS '메시지 작성 시각';
COMMENT ON TABLE support_inquiry_attachment IS '지원 티켓 원문이나 후속 메시지에 연결한 비공개 첨부다. 검사 완료 전에는 다운로드하지 못한다';
COMMENT ON COLUMN support_inquiry_attachment.id IS '지원 첨부 내부 식별자';
COMMENT ON COLUMN support_inquiry_attachment.inquiry_id IS '대상 지원 티켓';
COMMENT ON COLUMN support_inquiry_attachment.message_id IS '후속 메시지 첨부일 때의 메시지 ID다. 최초 문의 첨부는 NULL이다';
COMMENT ON COLUMN support_inquiry_attachment.object_key IS '비공개 객체 스토리지 키';
COMMENT ON COLUMN support_inquiry_attachment.file_name IS '업로드 당시 파일명';
COMMENT ON COLUMN support_inquiry_attachment.media_type IS '검사한 MIME 유형';
COMMENT ON COLUMN support_inquiry_attachment.size_bytes IS '파일 크기 바이트 수';
COMMENT ON COLUMN support_inquiry_attachment.uploaded_by_user_id IS '문의자가 업로드한 경우의 사용자 ID';
COMMENT ON COLUMN support_inquiry_attachment.uploaded_by_operator_id IS '운영자가 업로드한 경우의 운영자 ID';
COMMENT ON COLUMN support_inquiry_attachment.scan_status IS 'PENDING 검사 대기, CLEAN 다운로드 허용, REJECTED 차단';
COMMENT ON COLUMN support_inquiry_attachment.created_at IS '첨부 등록 시각';
COMMENT ON TABLE enterprise_lead IS '기업도입 문의다. 접수, 담당배정, 상담, 견적, 수락 또는 거절, 계약 또는 종료 순으로 진행한다. 견적 유효기한은 기본 14일이며 서비스 계층이 계산한다. 상태 전이는 접수 → 담당배정 → 상담 → 견적 → 고객의 수락 또는 거절 → 계약이며 종료는 계약 전 어느 단계에서나 가능하다. 운영자는 수락·거절 상태를 직접 만들 수 없다. 전이 이력은 enterprise_lead_status_history에 남긴다';
COMMENT ON COLUMN enterprise_lead.id IS '기업도입 문의 내부 식별자';
COMMENT ON COLUMN enterprise_lead.company_name IS '기업명';
COMMENT ON COLUMN enterprise_lead.contact_name IS '담당자 이름';
COMMENT ON COLUMN enterprise_lead.contact_phone IS '담당자 연락처';
COMMENT ON COLUMN enterprise_lead.contact_email IS '견적과 상담 회신을 받을 담당자 이메일';
COMMENT ON COLUMN enterprise_lead.branch_count IS '문의 시점의 도입 예상 지점 수';
COMMENT ON COLUMN enterprise_lead.expected_seats IS '문의 시점의 예상 이용 인원';
COMMENT ON COLUMN enterprise_lead.migration_needed IS '기존 자료 이전 지원 필요 여부';
COMMENT ON COLUMN enterprise_lead.content IS '기업도입 문의 원문';
COMMENT ON COLUMN enterprise_lead.tracking_key_hash IS '비회원 상태 조회용 조회키의 SHA-256 해시다. 원문은 생성 응답에서 한 번만 반환한다';
COMMENT ON COLUMN enterprise_lead.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN enterprise_lead.assigned_operator_id IS '배정된 운영자';
COMMENT ON COLUMN enterprise_lead.quote_amount IS '견적 금액';
COMMENT ON COLUMN enterprise_lead.quote_expires_at IS '견적 유효기한';
COMMENT ON COLUMN enterprise_lead.created_at IS '생성 일시';
COMMENT ON TABLE enterprise_quote IS '기업도입 견적의 불변 버전이다. 조건 변경은 새 version_no 행으로 재발행하며 수락한 버전을 청구와 연결한다. 수락·거절은 문의의 최신 버전이면서 대체되지 않았고 유효기한 전인 견적에만 할 수 있다';
COMMENT ON COLUMN enterprise_quote.id IS '기업 견적 내부 식별자';
COMMENT ON COLUMN enterprise_quote.lead_id IS '대상 기업도입 문의';
COMMENT ON COLUMN enterprise_quote.version_no IS '문의별 1부터 증가하는 견적 버전';
COMMENT ON COLUMN enterprise_quote.office_count IS '도입 사무소 수';
COMMENT ON COLUMN enterprise_quote.seat_count IS '도입 인원 수';
COMMENT ON COLUMN enterprise_quote.amount IS '견적 총액 원화';
COMMENT ON COLUMN enterprise_quote.service_scope IS '제공 서비스와 제외 범위';
COMMENT ON COLUMN enterprise_quote.tax_amount IS '견적에 포함된 세금 원화';
COMMENT ON COLUMN enterprise_quote.delivery_due_at IS '약정 납기';
COMMENT ON COLUMN enterprise_quote.payment_method IS '합의한 결제 방식';
COMMENT ON COLUMN enterprise_quote.refund_terms IS '합의한 환불 조건';
COMMENT ON COLUMN enterprise_quote.expires_at IS '견적 수락 종료 시각';
COMMENT ON COLUMN enterprise_quote.issued_at IS '견적 발행 시각';
COMMENT ON COLUMN enterprise_quote.accepted_at IS '비회원 조회키로 수락한 시각';
COMMENT ON COLUMN enterprise_quote.billing_invoice_id IS '수락한 견적을 청구할 때 연결한 청구서 ID. 청구서의 보관이 끝나 청구서를 지울 때 이 연결만 NULL로 바꾸고 견적 행은 남긴다';
COMMENT ON COLUMN enterprise_quote.issued_by_operator_id IS '견적을 발행한 운영자';
COMMENT ON COLUMN enterprise_quote.rejected_at IS '비회원 조회키로 거절한 시각. 유효기한 전에만 값이 있다';
COMMENT ON COLUMN enterprise_quote.superseded_at IS '같은 문의에 새 버전이 발행되어 더 이상 수락·거절할 수 없게 된 시각';
COMMENT ON TABLE enterprise_lead_status_history IS '기업도입 문의의 진행 사건 이력이다. 행을 수정하거나 삭제하지 않고 추가만 한다. 고객의 견적 수락·거절은 actor_type=CUSTOMER로 기록하며 이때 actor_operator_id는 비어 있다. 운영자가 상태를 직접 ACCEPTED나 REJECTED로 바꾼 사건은 존재할 수 없다';
COMMENT ON COLUMN enterprise_lead_status_history.id IS '이력 내부 식별자';
COMMENT ON COLUMN enterprise_lead_status_history.lead_id IS '대상 문의';
COMMENT ON COLUMN enterprise_lead_status_history.event_type IS '`RECEIVED`, `ASSIGNED`, `REASSIGNED`, `CONSULTATION_STARTED`, `QUOTE_ISSUED`, `QUOTE_ACCEPTED`, `QUOTE_REJECTED`, `CONTRACTED`, `CLOSED`, `REOPENED` 중 하나';
COMMENT ON COLUMN enterprise_lead_status_history.from_status IS '최초 접수 사건은 NULL. 담당만 바꾸는 재배정과 견적 재발행은 이전과 이후 상태가 같다';
COMMENT ON COLUMN enterprise_lead_status_history.to_status IS '사건 처리 뒤 문의 상태';
COMMENT ON COLUMN enterprise_lead_status_history.actor_type IS '`OPERATOR`, `CUSTOMER`, `SYSTEM` 중 하나';
COMMENT ON COLUMN enterprise_lead_status_history.actor_operator_id IS 'actor_type이 OPERATOR일 때만 값이 있다';
COMMENT ON COLUMN enterprise_lead_status_history.assigned_operator_id IS '배정·재배정 사건에서 새로 맡은 운영자';
COMMENT ON COLUMN enterprise_lead_status_history.quote_id IS '견적 발행·수락·거절 사건의 대상 견적';
COMMENT ON COLUMN enterprise_lead_status_history.reason IS '종료와 재개 사건의 사유. 계약 사건은 계약 근거 번호';
COMMENT ON COLUMN enterprise_lead_status_history.created_at IS '사건 발생 일시';
COMMENT ON INDEX ix_enterprise_lead_status_history_lead IS '문의별 진행 이력을 시간순으로 조회한다';
COMMENT ON TABLE policy_document IS '약관, 개인정보처리방침, 요금 등 정책 문서의 버전과 시행일을 관리한다. terms_agreement에 기록된 과거 동의는 당시 시행 버전을 계속 참조하므로 이 표의 과거 버전 행도 삭제하지 않는다. 가격 변경은 30일 전에 안내하고 동의를 받아야 한다. 이 절차는 서비스 계층이 수행한다';
COMMENT ON COLUMN policy_document.id IS '정책 문서 내부 식별자';
COMMENT ON COLUMN policy_document.doc_type IS '이용약관, 개인정보처리방침, 처리위탁 조건, 보관 조건, 환불 안내, 수탁업무 목록, 가격표 중 종류';
COMMENT ON COLUMN policy_document.version IS '버전 번호';
COMMENT ON COLUMN policy_document.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN policy_document.body IS '게시할 정책 본문 전체';
COMMENT ON COLUMN policy_document.change_summary IS '이전 버전과 달라진 내용';
COMMENT ON COLUMN policy_document.notice_at IS '고객에게 변경을 공지한 시각';
COMMENT ON COLUMN policy_document.requires_consent IS '새 버전 적용에 명시적 동의가 필요한지 여부';
COMMENT ON COLUMN policy_document.effective_at IS '시행 시각';
COMMENT ON COLUMN policy_document.published_at IS '게시 일시';
COMMENT ON COLUMN policy_document.created_by_operator_id IS '작성한 운영자';
COMMENT ON COLUMN policy_document.reviewed_by_operator_id IS '본문을 검토한 운영자';
COMMENT ON COLUMN policy_document.published_by_operator_id IS '게시를 승인한 운영자';
COMMENT ON TABLE platform_announcement IS '공지사항. 초안→검토→예약/게시→종료. 예약 상태에서 게시 전에 곧바로 종료로 갈 수 있다';
COMMENT ON COLUMN platform_announcement.id IS '공지사항 내부 식별자';
COMMENT ON COLUMN platform_announcement.title IS '제목';
COMMENT ON COLUMN platform_announcement.content IS '내용';
COMMENT ON COLUMN platform_announcement.version_no IS '원래 공지부터 증가하는 게시본 버전';
COMMENT ON COLUMN platform_announcement.previous_version_id IS '수정 전 게시본의 공지 ID';
COMMENT ON COLUMN platform_announcement.audience_type IS '전체, 구독 상태별, 특정 사무소 중 노출 대상';
COMMENT ON COLUMN platform_announcement.audience_status IS '구독 상태별 공지의 대상 상태 코드';
COMMENT ON COLUMN platform_announcement.audience_office_id IS '특정 사무소 공지의 대상 사무소';
COMMENT ON COLUMN platform_announcement.starts_at IS '노출 시작 시각';
COMMENT ON COLUMN platform_announcement.ends_at IS '노출 종료 시각';
COMMENT ON COLUMN platform_announcement.importance IS '일반, 중요, 긴급 중 중요도';
COMMENT ON COLUMN platform_announcement.detail_url IS '공지 상세 링크';
COMMENT ON COLUMN platform_announcement.is_marketing IS '선택 마케팅 공지 여부';
COMMENT ON COLUMN platform_announcement.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN platform_announcement.scheduled_at IS '게시 예약 시각';
COMMENT ON COLUMN platform_announcement.published_at IS '게시 일시';
COMMENT ON COLUMN platform_announcement.ended_at IS '종료 처리 일시. 공지 종료(end) 엔드포인트가 기록한다';
COMMENT ON COLUMN platform_announcement.created_by_operator_id IS '작성한 운영자';
COMMENT ON COLUMN platform_announcement.reviewed_by_operator_id IS '검토 단계로 올린 검토자';
COMMENT ON COLUMN platform_announcement.created_at IS '생성 일시';
COMMENT ON TABLE system_job_run IS '배치와 수동 재실행 작업의 멱등키 기록이다. 성공한 결제나 완료된 파기가 중복 실행되는 것을 막는다';
COMMENT ON COLUMN system_job_run.id IS '시스템 작업 실행 내부 식별자';
COMMENT ON COLUMN system_job_run.job_name IS '작업 이름';
COMMENT ON COLUMN system_job_run.office_id IS '고객사 범위가 있는 작업의 대상 사무소';
COMMENT ON COLUMN system_job_run.idempotency_key IS '중복 실행 방지 키';
COMMENT ON COLUMN system_job_run.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN system_job_run.scheduled_at IS '예약 실행 시각';
COMMENT ON COLUMN system_job_run.started_at IS '실행 시작 일시';
COMMENT ON COLUMN system_job_run.finished_at IS '실행 종료 일시';
COMMENT ON COLUMN system_job_run.attempt_count IS '원래 사건의 재실행 시도 회수';
COMMENT ON COLUMN system_job_run.error_code IS '마지막 실패 원인 코드';
COMMENT ON COLUMN system_job_run.next_run_at IS '다음 안전 재실행 예정 시각';
COMMENT ON COLUMN system_job_run.assigned_operator_id IS '작업 담당 운영자';
COMMENT ON TABLE incident_log IS '장애 감지→확인→대응→복구→종료';
COMMENT ON COLUMN incident_log.id IS '장애 기록 내부 식별자';
COMMENT ON COLUMN incident_log.title IS '제목';
COMMENT ON COLUMN incident_log.affected_services IS '영향받은 서비스 기능 목록';
COMMENT ON COLUMN incident_log.affected_offices IS '영향받은 사무소 ID 목록 또는 전체 범위';
COMMENT ON COLUMN incident_log.status IS '이 레코드의 현재 상태';
COMMENT ON COLUMN incident_log.detected_at IS '장애 감지 일시';
COMMENT ON COLUMN incident_log.started_at IS '장애 시작 추정 시각';
COMMENT ON COLUMN incident_log.recovered_at IS '서비스 복구 확인 시각';
COMMENT ON COLUMN incident_log.closed_at IS '종료 처리 일시';
COMMENT ON COLUMN incident_log.assigned_operator_id IS '장애 대응 담당 운영자';
COMMENT ON COLUMN incident_log.root_cause IS '조사로 확인한 장애 원인';
COMMENT ON COLUMN incident_log.response_actions IS '대응·복구 조치 이력';
COMMENT ON COLUMN incident_log.customer_notice IS '고객 안내 내용과 공지 식별자';
COMMENT ON COLUMN incident_log.prevention_tasks IS '재발 방지 작업과 책임자';
COMMENT ON COLUMN incident_log.summary IS '요약';
COMMENT ON TABLE deletion_queue IS '개인정보 파기 대상 큐다. 보존 예외는 근거, 기간, 재검토일을 함께 기록하고 result=EXCLUDED로 표시하며 별도 승인이 필요하다. 이 승인은 서비스 계층이 수행한다. 검증 전에는 완료로 표시하지 않는다. 임의 삭제와 적법 만료 파기를 구분한다';
COMMENT ON COLUMN deletion_queue.id IS '파기 대상 큐 내부 식별자';
COMMENT ON COLUMN deletion_queue.target_type IS '대상 종류';
COMMENT ON COLUMN deletion_queue.target_id IS '대상 레코드의 ID';
COMMENT ON COLUMN deletion_queue.office_id IS '소속 사무소';
COMMENT ON COLUMN deletion_queue.reason IS '파기 사유와 근거';
COMMENT ON COLUMN deletion_queue.scheduled_at IS '파기 예정 시각';
COMMENT ON COLUMN deletion_queue.executed_at IS '실행 처리 일시';
COMMENT ON COLUMN deletion_queue.result IS '처리 결과';
COMMENT ON COLUMN deletion_queue.exclusion_reason IS '제외 근거';
COMMENT ON COLUMN deletion_queue.hold_approved_by_operator_id IS '법정 보존이나 분쟁 보류를 승인한 운영자';
COMMENT ON COLUMN deletion_queue.hold_expires_at IS '보존·분쟁 보류 만료 시각';
COMMENT ON COLUMN deletion_queue.exclusion_reviewed_at IS '제외 재검토 예정일';
COMMENT ON COLUMN deletion_queue.storage_result IS '운영 DB 저장소 파기 결과';
COMMENT ON COLUMN deletion_queue.search_index_result IS '검색 색인 파기 결과';
COMMENT ON COLUMN deletion_queue.file_result IS '파일 저장소 파기 결과';
COMMENT ON COLUMN deletion_queue.temporary_export_result IS '임시 내보내기 파기 결과';
COMMENT ON COLUMN deletion_queue.backup_expires_at IS '백업 매체에서 해당 정보가 만료되는 시각';
COMMENT ON COLUMN deletion_queue.retry_count IS '실패 후 재시도 회수';
COMMENT ON COLUMN deletion_queue.verified_by_operator_id IS '파기 실행과 별도로 결과를 확인한 운영자';
COMMENT ON COLUMN deletion_queue.verified_at IS '모든 파기 대상 결과 검증 완료 시각';
COMMENT ON COLUMN deletion_queue.created_at IS '생성 일시';
COMMENT ON COLUMN deletion_queue.executed_by_operator_id IS '파기를 실행한 운영자. 검증 운영자와 달라야 한다';
COMMENT ON COLUMN deletion_queue.cancelled_at IS '예약된 파기를 취소한 일시다. 실행하기 전의 행에서만 값이 있고 값이 있으면 executed_at과 result는 비어 있어야 한다. 예약 파기 작업은 이 값이 있는 행을 제외한다';
COMMENT ON COLUMN deletion_queue.cancelled_by_operator_id IS '파기 예약을 취소한 운영자';
COMMENT ON COLUMN deletion_queue.cancel_reason IS '파기 예약을 취소한 사유다. 공백만 있는 값은 둘 수 없다';
COMMENT ON COLUMN deletion_queue.target_count IS '실행 전 미리보기에서 산정한 파기 대상 건수';
COMMENT ON COLUMN deletion_queue.excluded_count IS '실행 전 미리보기에서 법정 보존으로 제외한 건수';
COMMENT ON INDEX ix_deletion_queue_due IS '예약 파기 작업이 아직 실행하지 않았고 취소하지 않은 대상만 예정일 순으로 읽는 인덱스다. cancelled_at이 있는 행은 읽지 않는다';
COMMENT ON TABLE billing_reconciliation_entry IS 'KST 전일 승인·취소 거래의 PG 자료와 내부 원장을 대조한 결과다. 차이는 근거와 담당자를 남겨 해결하며 대사만으로 승인 또는 재청구를 생성하지 않는다';
COMMENT ON COLUMN billing_reconciliation_entry.id IS '대사 항목 ID';
COMMENT ON COLUMN billing_reconciliation_entry.business_date IS '대상 거래의 KST 영업일';
COMMENT ON COLUMN billing_reconciliation_entry.source_type IS 'PG 조회, PG 자료 파일, 내부 원장 중 입력 출처';
COMMENT ON COLUMN billing_reconciliation_entry.pg_order_id IS 'PG 주문 ID';
COMMENT ON COLUMN billing_reconciliation_entry.invoice_id IS '대상 청구서';
COMMENT ON COLUMN billing_reconciliation_entry.refund_request_id IS '대상 환불 신청';
COMMENT ON COLUMN billing_reconciliation_entry.office_id IS '대상 사무소';
COMMENT ON COLUMN billing_reconciliation_entry.internal_amount IS '내부 원장 금액 원화';
COMMENT ON COLUMN billing_reconciliation_entry.pg_amount IS 'PG 자료 금액 원화';
COMMENT ON COLUMN billing_reconciliation_entry.status IS '일치, 금액 불일치, PG에만 존재, 내부에만 존재, 확인 중 중 대사 결과';
COMMENT ON COLUMN billing_reconciliation_entry.difference_reason IS '차이가 발생한 원인';
COMMENT ON COLUMN billing_reconciliation_entry.resolution_evidence IS '차이 해소의 PG 조회 또는 자료 근거';
COMMENT ON COLUMN billing_reconciliation_entry.assigned_operator_id IS '대사 차이 담당 운영자';
COMMENT ON COLUMN billing_reconciliation_entry.resolved_at IS '차이 해결을 확인한 시각';
COMMENT ON COLUMN billing_reconciliation_entry.created_at IS '대사 항목 생성 시각';
COMMENT ON TABLE privacy_request IS '개인정보 권리 요청의 독립 사건이다. 보완 대기가 법정 기한을 자동으로 정지하지 않는다. 사무소 책임자 전달과 제한·거절의 근거를 이력으로 보존한다. 보관 기간이 지나도 비회원 권리 요청 접수 기록이 이 요청을 참조하는 동안은 지우지 않고 접수 기록의 보관이 끝난 뒤 지운다';
COMMENT ON COLUMN privacy_request.id IS '개인정보 권리 요청 ID';
COMMENT ON COLUMN privacy_request.requester_user_id IS '회원 요청자 사용자 ID';
COMMENT ON COLUMN privacy_request.support_inquiry_id IS '접수 지원 티켓 ID';
COMMENT ON COLUMN privacy_request.office_id IS '처리 책임 사무소';
COMMENT ON COLUMN privacy_request.request_type IS '열람, 정정, 삭제, 처리정지, 동의철회, 이전 중 요청 종류';
COMMENT ON COLUMN privacy_request.identity_status IS '요청자 본인확인 상태';
COMMENT ON COLUMN privacy_request.received_at IS '요청 접수 시각';
COMMENT ON COLUMN privacy_request.legal_basis IS '적용 법적 근거와 제한 근거';
COMMENT ON COLUMN privacy_request.legal_due_at IS '적용 법정 처리기한';
COMMENT ON COLUMN privacy_request.internal_due_at IS '내부 목표 처리기한';
COMMENT ON COLUMN privacy_request.request_scope IS '요청한 개인정보와 처리 범위';
COMMENT ON COLUMN privacy_request.status IS '접수부터 전달·보완·검토·승인·일부 제한·실행·완료·거절까지의 처리 상태';
COMMENT ON COLUMN privacy_request.decision_reason IS '승인·일부 제한·거절 결정 근거';
COMMENT ON COLUMN privacy_request.completion_evidence IS '실행 결과와 완료 증빙 위치';
COMMENT ON COLUMN privacy_request.assigned_operator_id IS '담당 개인정보 운영자';
COMMENT ON COLUMN privacy_request.completed_at IS '요청 처리 완료 시각';
COMMENT ON COLUMN privacy_request.handler_type IS '처리 책임 구분이다. SAIRO는 사이로가 처리자인 회원 본인 정보 요청, OFFICE는 사무소가 처리자이고 사이로가 지원하는 사무소 고객·승인자 정보 요청이다';
COMMENT ON TABLE privacy_request_event IS '개인정보 권리 요청의 전달·보완·결정·실행을 삭제하지 않는 사건 이력으로 남긴다';
COMMENT ON COLUMN privacy_request_event.id IS '요청 사건 이력 ID';
COMMENT ON COLUMN privacy_request_event.privacy_request_id IS '대상 개인정보 요청';
COMMENT ON COLUMN privacy_request_event.event_type IS '전달, 협조 요청, 보완, 결정, 실행, 완료 중 행위 종류';
COMMENT ON COLUMN privacy_request_event.previous_status IS '행위 전 요청 상태';
COMMENT ON COLUMN privacy_request_event.new_status IS '행위 후 요청 상태';
COMMENT ON COLUMN privacy_request_event.action_detail IS '처리 내역과 증빙 위치';
COMMENT ON COLUMN privacy_request_event.actor_operator_id IS '처리한 운영자';
COMMENT ON COLUMN privacy_request_event.occurred_at IS '행위 시각';
COMMENT ON TABLE trial_event IS '60×24시간 체험 자격의 신청창을 설정한다. 승인 후 신규 대상에만 적용하며 종료나 중단이 기존 체험을 소급 취소하지 않는다. 60×24시간 서술은 정합화 전 서술이며 기간 방식 DURATION에 해당한다. 고정 종료 방식 FIXED_END는 fixed_free_ends_at의 고정 시각까지 무료로 둔다. 가입 그룹의 경계는 이 이벤트의 자격 신청창 시작·종료 시각으로 표현하고 날짜는 이벤트 행의 값으로 입력한다. 시작 고객 이벤트는 가입 창과 판정 기준이 일반 이벤트와 다르다. 판정 기준 시각은 일반 이벤트가 최초 인증 완료시각이고 시작 고객 이벤트는 시작 고객 합의의 승인 시각이다. 이벤트 선택과 무료 종료 시각 계산 규칙은 서비스 계층이 수행한다';
COMMENT ON COLUMN trial_event.id IS '체험 이벤트 ID';
COMMENT ON COLUMN trial_event.name IS '운영자 화면의 이벤트명';
COMMENT ON COLUMN trial_event.starts_at IS '자격 신청창 시작 포함 시각';
COMMENT ON COLUMN trial_event.ends_at IS '자격 신청창 종료 제외 시각';
COMMENT ON COLUMN trial_event.office_created_during IS '기간 내 사무소 생성 요구 여부';
COMMENT ON COLUMN trial_event.first_application_during IS '기간 내 최초 인증 신청 요구 여부';
COMMENT ON COLUMN trial_event.status IS '초안, 검토, 예약, 활성, 종료 중 상태';
COMMENT ON COLUMN trial_event.approved_by_operator_id IS '대상 미리보기와 중복 수혜 검사를 승인한 운영자';
COMMENT ON COLUMN trial_event.created_by_operator_id IS '작성한 운영자다. 작성자와 승인자를 분리하는 검사에 쓰며 승인자와 같을 수 없다';
COMMENT ON COLUMN trial_event.created_at IS '이벤트 등록 시각';
COMMENT ON COLUMN trial_event.free_end_mode IS '무료 종료 방식이다. DURATION은 기간 방식, FIXED_END는 고정 종료 시각 방식이다. 기존 행은 기간 방식이다';
COMMENT ON COLUMN trial_event.fixed_free_ends_at IS '고정 무료 종료 시각이다. FIXED_END일 때만 값이 있고 FIXED_END이면 반드시 있다. 날짜는 이벤트 행의 값으로 입력하며 스키마에 고정하지 않는다';
COMMENT ON COLUMN trial_event.audience IS '체험 이벤트의 대상이다. GENERAL은 일반 가입자 이벤트이고 START_CUSTOMER는 시작 고객 합의가 승인된 사무소에만 적용하는 이벤트다. 기존 행은 GENERAL이다. 활성 또는 예약 상태의 GENERAL 이벤트는 가입 창이 서로 겹치지 않는다. 이 검사는 배제 제약 ex_trial_event_general_window가 한다';
COMMENT ON COLUMN trial_event.max_offices IS '시작 고객 이벤트에서 승인할 수 있는 합의의 상한 수다. START_CUSTOMER일 때만 값이 있을 수 있고 NULL이면 상한이 없다. 상한 검사는 합의 승인 트랜잭션에서 서비스 계층이 이벤트 단위 잠금 아래 수행한다';
COMMENT ON CONSTRAINT ex_trial_event_general_window ON trial_event IS '활성 또는 예약 상태의 일반 체험 이벤트는 가입 창(시작 포함, 종료 제외)이 겹칠 수 없다. 일반 가입자가 어느 이벤트에 속하는지가 하나로 정해지게 한다';
COMMENT ON TABLE price_schedule IS 'VAT 포함 Solo·Team 요금 산식의 불변 버전이다. n=1은 solo_amount, 2~4인은 solo_amount+(n-1)×team_first_extra, 5인 이상은 solo_amount+3×team_first_extra+(n-4)×team_after_four_extra다. 새 버전 적용에는 사전 안내와 명시적 동의가 필요하다';
COMMENT ON COLUMN price_schedule.id IS '가격표 ID';
COMMENT ON COLUMN price_schedule.version IS '청구서에 고정하는 가격표 버전';
COMMENT ON COLUMN price_schedule.solo_amount IS 'Solo VAT 포함 월액 원화';
COMMENT ON COLUMN price_schedule.team_first_extra IS '2~4인 구간 1명당 추가 월액 원화';
COMMENT ON COLUMN price_schedule.team_after_four_extra IS '5인 이상 구간 1명당 추가 월액 원화';
COMMENT ON COLUMN price_schedule.effective_at IS '가격 적용 시작 시각';
COMMENT ON COLUMN price_schedule.notice_at IS '고객에게 가격 변경을 사전 안내한 시각';
COMMENT ON COLUMN price_schedule.status IS '초안, 검토, 예약, 활성, 종료 중 상태';
COMMENT ON COLUMN price_schedule.approved_by_operator_id IS '가격표 게시 승인 운영자';
COMMENT ON COLUMN price_schedule.created_by_operator_id IS '작성한 운영자다. 작성자와 승인자를 분리하는 검사에 쓰며 승인자와 같을 수 없다';
COMMENT ON COLUMN price_schedule.created_at IS '가격표 버전 생성 시각';
COMMENT ON COLUMN price_schedule.audience IS '요금표 버전의 대상이다. STANDARD는 모든 사무소의 표준 가격이고 START_CUSTOMER는 시작 고객 합의에 연결하는 전용 가격이다. 기존 행은 STANDARD다. 시작 고객 전용 버전은 billing_start_customer_agreement에 연결된 사무소에만 적용하며 공개 요금 페이지에 노출하지 않는다';
COMMENT ON INDEX uq_price_schedule_standard_effective IS '같은 효력 시각의 활성 또는 예약 상태 표준 요금표 버전은 하나뿐이다. 표준 가격 선택 때 효력 시각이 가장 늦은 버전이 하나로 정해지게 한다';
COMMENT ON TABLE billing_start_customer_agreement IS '시작 고객 합의다. 운영자가 대표와 별도 합의서로 체결한 사실을 등록하고 등록자와 다른 결제담당이 승인한다. 승인된 합의는 사무소를 시작 고객 체험 이벤트와 시작 고객 전용 가격 버전에 연결한다. 시작 고객 자격 판정 기준 시각은 승인 시각이며 이벤트 가입 창 안이어야 한다. 이벤트별 승인 수가 이벤트의 max_offices 이하여야 한다는 규칙, 승인 시각과 체결일이 이벤트 창 안이라는 규칙, 이벤트와 가격 버전의 대상이 START_CUSTOMER라는 규칙은 서비스 계층이 이벤트 단위 잠금 아래 수행한다. 취소해도 이미 부여한 무료 기간을 소급 취소하지 않는다. 가격 금액은 이 표에 두지 않고 price_schedule 행의 값을 쓴다';
COMMENT ON COLUMN billing_start_customer_agreement.id IS '시작 고객 합의 내부 식별자';
COMMENT ON COLUMN billing_start_customer_agreement.office_id IS '합의 대상 사무소다. 사무소에는 REGISTERED 또는 APPROVED 합의가 하나만 있을 수 있다';
COMMENT ON COLUMN billing_start_customer_agreement.trial_event_id IS '연결한 시작 고객 체험 이벤트다. audience가 START_CUSTOMER인 이벤트여야 한다';
COMMENT ON COLUMN billing_start_customer_agreement.price_schedule_id IS '연결한 시작 고객 전용 요금표 버전이다. audience가 START_CUSTOMER인 버전이어야 한다';
COMMENT ON COLUMN billing_start_customer_agreement.price_starts_at IS '가격 보장 시작 시각이다. 서버가 이벤트의 고정 무료 종료 시각으로 채운다';
COMMENT ON COLUMN billing_start_customer_agreement.price_ends_at IS '가격 보장 종료 시각이며 종료는 제외한다. 서버가 가격 보장 시작에 보장 개월 수를 더해 채운다. 이 시각에 가격 보장이 끝나면 표준 가격이 적용되고 그 변경은 pricing_change_notice 규칙을 따른다';
COMMENT ON COLUMN billing_start_customer_agreement.status IS 'REGISTERED 등록됨, APPROVED 승인됨, REVOKED 취소됨 중 하나다. REGISTERED에서 APPROVED 또는 REVOKED로, APPROVED에서 REVOKED로 전이한다';
COMMENT ON COLUMN billing_start_customer_agreement.contracted_on IS '합의서 체결일이며 Asia/Seoul 날짜다. 이벤트 가입 창의 시작 날짜 이상이고 종료 날짜보다 앞서야 한다. 이 검사는 서비스 계층이 수행한다';
COMMENT ON COLUMN billing_start_customer_agreement.contract_reference IS '합의서 참조번호다. 합의서 원문 파일이나 개인정보는 이 표에 저장하지 않는다';
COMMENT ON COLUMN billing_start_customer_agreement.weekly_use_confirmed IS '주간 사용 협력 조건을 확인했는지다. 등록하려면 true여야 한다. 지키지 않아도 이미 부여한 무료 기간을 소급 취소하지 않는다';
COMMENT ON COLUMN billing_start_customer_agreement.monthly_interview_confirmed IS '월 1회 피드백 인터뷰 협력 조건을 확인했는지다. 등록하려면 true여야 한다. 지키지 않아도 이미 부여한 무료 기간을 소급 취소하지 않는다';
COMMENT ON COLUMN billing_start_customer_agreement.case_publication_consent IS '사례 공개 선택 동의다. false여도 시작 고객 자격에 영향이 없다';
COMMENT ON COLUMN billing_start_customer_agreement.agreement_text_version IS '체결한 합의서 문안 버전';
COMMENT ON COLUMN billing_start_customer_agreement.owner_acknowledged_at IS '대표가 서비스 안에서 합의 내용을 확인한 시각이다. 선택 동작이며 자격과 가격에 영향을 주지 않는다. 확인 전이면 NULL이다';
COMMENT ON COLUMN billing_start_customer_agreement.owner_acknowledged_by_membership_id IS '합의 내용을 확인한 대표의 소속이다. owner_acknowledged_at과 함께 값이 있거나 함께 NULL이다';
COMMENT ON COLUMN billing_start_customer_agreement.created_by_operator_id IS '합의를 등록한 운영담당 운영자다. 승인자와 같을 수 없다';
COMMENT ON COLUMN billing_start_customer_agreement.created_at IS '합의 등록 시각';
COMMENT ON COLUMN billing_start_customer_agreement.approved_by_operator_id IS '합의를 승인한 결제담당 운영자다. 등록자와 같을 수 없다';
COMMENT ON COLUMN billing_start_customer_agreement.approved_at IS '합의 승인 시각이며 시작 고객 자격 판정 기준 시각이다. 이벤트 가입 창 안이어야 한다';
COMMENT ON COLUMN billing_start_customer_agreement.revoked_by_operator_id IS '합의를 취소한 결제담당 운영자';
COMMENT ON COLUMN billing_start_customer_agreement.revoked_at IS '합의 취소 시각이다. REVOKED일 때만 값이 있다';
COMMENT ON COLUMN billing_start_customer_agreement.revoke_reason IS '합의 취소 사유다. REVOKED일 때만 값이 있다';
COMMENT ON COLUMN billing_start_customer_agreement.updated_at IS '합의를 마지막으로 바꾼 시각';
COMMENT ON COLUMN billing_start_customer_agreement.version IS '낙관적 잠금 버전이며 1부터 시작한다. 승인과 취소 요청은 If-Match로 이 값을 보낸다';
COMMENT ON INDEX uq_billing_sca_office_open IS '사무소 하나에는 등록됨 또는 승인됨 시작 고객 합의가 하나만 있을 수 있다. 취소된 합의는 이 제한에서 빠지므로 다시 등록할 수 있다';
COMMENT ON INDEX ix_billing_sca_event_status IS '이벤트별 승인 합의 수를 세는 상한 검사와 합의 목록 조회에 쓴다';
COMMENT ON TABLE pricing_change_notice IS '가격 변경의 대상 사무소·효력일·동의를 구독 단위로 추적한다. 새 표준 요금표 버전이 예약되면 결제담당이 대상 안내를 만들고 시작 고객 가격 보장 종료 45일 전에는 시스템이 만든다. 인상(INCREASE)은 효력 30일 전 이상 안내하고 대표의 명시적 동의가 있어야 새 가격으로 청구한다. 인하나 동일 금액(NON_INCREASE)은 동의 없이 안내만 한다. 응답 기한은 새 가격이 처음 적용되는 청구기간 시작 시각 이하다. 응답 기한까지 인상 건이 AGREED가 아니면 갱신 배치가 청구서를 만들지 않고 구독을 종료하며 PENDING이던 건은 ENDED_NO_CONSENT로 바꾼다. 무응답을 동의로 보지 않는다. 이 종료 처리와 안내 대상 선정은 서비스 계층이 수행한다. 금액은 현재 과금 인원 기준 VAT 포함 월 금액의 스냅샷이다';
COMMENT ON COLUMN pricing_change_notice.id IS '가격 변경 안내 내부 식별자';
COMMENT ON COLUMN pricing_change_notice.office_id IS '안내 대상 사무소';
COMMENT ON COLUMN pricing_change_notice.subscription_id IS '안내 대상 구독이며 같은 구독의 같은 새 가격 버전 안내는 하나뿐이다';
COMMENT ON COLUMN pricing_change_notice.from_price_schedule_id IS '변경 전 요금표 버전이며 새 버전과 같을 수 없다';
COMMENT ON COLUMN pricing_change_notice.to_price_schedule_id IS '변경 후 요금표 버전';
COMMENT ON COLUMN pricing_change_notice.change_kind IS 'INCREASE 인상, NON_INCREASE 인하 또는 동일 금액이다. 새 금액이 현재 금액보다 크면 INCREASE다';
COMMENT ON COLUMN pricing_change_notice.member_count_snapshot IS '금액 계산에 쓴 안내 시점의 과금 인원';
COMMENT ON COLUMN pricing_change_notice.current_amount_incl_vat IS '변경 전 버전과 위 인원 기준 VAT 포함 월 금액 원화';
COMMENT ON COLUMN pricing_change_notice.new_amount_incl_vat IS '변경 후 버전과 위 인원 기준 VAT 포함 월 금액 원화';
COMMENT ON COLUMN pricing_change_notice.notified_at IS '대표에게 안내한 시각이다. 인상이면 효력 시각이 이 시각의 30일 이후여야 한다';
COMMENT ON COLUMN pricing_change_notice.effective_at IS '새 가격의 효력 시각';
COMMENT ON COLUMN pricing_change_notice.applies_from_period_start IS '새 가격이 처음 적용되는 청구기간 시작 시각이며 효력 시각 이후다';
COMMENT ON COLUMN pricing_change_notice.response_due_at IS '대표의 응답 기한이다. 새 가격 첫 청구기간 시작 시각 이하다';
COMMENT ON COLUMN pricing_change_notice.notification_id IS '안내를 보낸 앱 내 알림이다. 서비스 필수 알림(요금 변경)이며 없을 수 있다';
COMMENT ON COLUMN pricing_change_notice.decision IS 'PENDING 응답 대기, AGREED 동의, DECLINED 거절, NOT_REQUIRED 동의가 필요 없는 안내, ENDED_NO_CONSENT 무응답으로 종료다. NON_INCREASE는 NOT_REQUIRED로 만든다';
COMMENT ON COLUMN pricing_change_notice.decided_at IS '동의·거절·무응답 종료 시각이다. PENDING과 NOT_REQUIRED이면 NULL이다';
COMMENT ON COLUMN pricing_change_notice.decided_by_membership_id IS '동의하거나 거절한 대표의 소속이다. AGREED와 DECLINED일 때만 값이 있다';
COMMENT ON COLUMN pricing_change_notice.purchase_consent_id IS '새 가격에 동의하며 저장한 구독 구매 동의 사건이다. AGREED일 때만 값이 있다';
COMMENT ON COLUMN pricing_change_notice.created_at IS '안내 행 생성 시각';
COMMENT ON INDEX ix_pricing_notice_pending_due IS '응답 기한이 도래한 응답 대기 안내를 갱신 배치가 찾는 데 쓴다';
COMMENT ON INDEX ix_pricing_notice_office IS '사무소 대표의 가격 변경 안내 목록 조회에 쓴다';
COMMENT ON TABLE company_service_info IS '고객에게 게시하는 사업자·지원·개인정보 창구의 버전별 실제 입력값이다. 필수 정보와 문의 수신 시험 전에는 운영 출시를 허용하지 않는다';
COMMENT ON COLUMN company_service_info.id IS '회사 제공 정보 버전 ID';
COMMENT ON COLUMN company_service_info.version_no IS '게시 버전 번호';
COMMENT ON COLUMN company_service_info.business_name IS '실제 사업자 상호';
COMMENT ON COLUMN company_service_info.representative_name IS '실제 사업자 대표자명';
COMMENT ON COLUMN company_service_info.business_number IS '사업자 등록번호';
COMMENT ON COLUMN company_service_info.address IS '사업장 주소';
COMMENT ON COLUMN company_service_info.contact_phone IS '사업자 연락처';
COMMENT ON COLUMN company_service_info.ecommerce_notice IS '해당할 때의 통신판매 신고정보';
COMMENT ON COLUMN company_service_info.support_email IS '고객 지원 수신 이메일';
COMMENT ON COLUMN company_service_info.support_hours IS '고객 지원 운영시간';
COMMENT ON COLUMN company_service_info.emergency_contact IS '긴급 연락 경로';
COMMENT ON COLUMN company_service_info.privacy_officer IS '개인정보 책임자 또는 담당 부서';
COMMENT ON COLUMN company_service_info.privacy_contact IS '개인정보 담당 연락처';
COMMENT ON COLUMN company_service_info.privacy_request_path IS '권리 요청 접수 경로';
COMMENT ON COLUMN company_service_info.cancellation_path IS '구독 해지 경로다. 고객이 해지를 신청하는 화면이나 연락 경로를 안내 문구로 적는다';
COMMENT ON COLUMN company_service_info.inquiry_delivery_tested_at IS '실제 지원 이메일 수신 시험 성공 시각';
COMMENT ON COLUMN company_service_info.reviewed_by_operator_id IS '회사 정보 검토 운영자';
COMMENT ON COLUMN company_service_info.published_at IS '고객 게시 시작 시각';
COMMENT ON TABLE ops_business_calendar IS '지원 첫 답변과 기업 문의 회신·상담 제안의 영업일 목표를 KST 날짜별로 계산한다';
COMMENT ON COLUMN ops_business_calendar.calendar_date IS 'Asia/Seoul 기준 날짜';
COMMENT ON COLUMN ops_business_calendar.is_business_day IS '고객 지원 업무일 여부';
COMMENT ON COLUMN ops_business_calendar.reason IS '휴무 또는 임시 영업 사유';
COMMENT ON COLUMN ops_business_calendar.updated_by_operator_id IS '일정을 승인해 반영한 운영자';
COMMENT ON COLUMN ops_business_calendar.updated_at IS '마지막 반영 시각';
COMMENT ON TABLE integration_config IS 'PG·이메일·본인확인·저장소·AI 공급자별 연결 상태다. 비밀값은 외부 비밀관리 저장소에 두고 이 표에는 참조 ID만 둔다. 시험환경의 실제 과금과 운영 고객 발송은 서비스 계층이 차단한다';
COMMENT ON COLUMN integration_config.id IS '연동 설정 ID';
COMMENT ON COLUMN integration_config.environment IS '시험 또는 운영 환경';
COMMENT ON COLUMN integration_config.provider IS '연동 공급자';
COMMENT ON COLUMN integration_config.function_code IS '결제, 이메일, 본인확인, 저장소, AI 중 기능 코드';
COMMENT ON COLUMN integration_config.enabled IS '현재 환경에서 연동 활성 여부';
COMMENT ON COLUMN integration_config.secret_reference_id IS '비밀관리 저장소의 자격정보 참조 ID';
COMMENT ON COLUMN integration_config.masked_connection IS '운영자에게 보여줄 마스킹된 연결 식별값';
COMMENT ON COLUMN integration_config.processing_region IS '공급자의 처리 지역';
COMMENT ON COLUMN integration_config.retention_policy IS '공급자에게 제공한 개인정보의 보유기간과 파기 기준';
COMMENT ON COLUMN integration_config.contract_status IS '수탁·연동 계약의 대기, 체결, 만료, 종료 상태';
COMMENT ON COLUMN integration_config.consent_status IS '해당하는 개인정보 동의의 불필요, 대기, 획득, 철회 상태';
COMMENT ON COLUMN integration_config.contract_notice_reviewed_at IS '공급자·처리지역 변경의 계약·고지 점검 시각';
COMMENT ON COLUMN integration_config.last_check_result IS '마지막 연결 검사 결과';
COMMENT ON COLUMN integration_config.last_success_at IS '마지막 성공 시각';
COMMENT ON COLUMN integration_config.assigned_operator_id IS '연동 운영 담당자';
COMMENT ON COLUMN integration_config.approved_by_operator_id IS '활성화 승인 운영자';
COMMENT ON TABLE privacy_incident IS '개인정보 사고의 제한 접근 기록이다. 장애 원인 내부 메모를 고객 공지에 자동 게시하지 않는다';
COMMENT ON COLUMN privacy_incident.id IS '개인정보 사고 ID';
COMMENT ON COLUMN privacy_incident.incident_log_id IS '연결한 장애 사건';
COMMENT ON COLUMN privacy_incident.affected_scope IS '개인정보 사고 대상과 범위';
COMMENT ON COLUMN privacy_incident.report_requirement IS '검토한 법적 신고 요건';
COMMENT ON COLUMN privacy_incident.notice_requirement IS '검토한 정보주체 통지 요건';
COMMENT ON COLUMN privacy_incident.report_due_at IS '해당하는 신고 기한';
COMMENT ON COLUMN privacy_incident.notice_due_at IS '해당하는 통지 기한';
COMMENT ON COLUMN privacy_incident.response_evidence IS '신고·통지·조치 증빙 위치';
COMMENT ON COLUMN privacy_incident.assigned_operator_id IS '개인정보 사고 담당자';
COMMENT ON COLUMN privacy_incident.created_at IS '개인정보 사고 등록 시각';
COMMENT ON TABLE rate_limit_counter IS '공개 링크·이메일 인증 발송 등 요청 제한용 고정 윈도우 카운터. 식별값은 원문이 아니라 요청 제한 전용 HMAC 변환값으로 저장한다';
COMMENT ON COLUMN rate_limit_counter.bucket_key IS '요청 제한 키';
COMMENT ON COLUMN rate_limit_counter.window_started_at IS '현재 윈도우 시작 시각';
COMMENT ON COLUMN rate_limit_counter.request_count IS '윈도우 내 요청 수';
COMMENT ON TABLE shedlock IS '월말결산 마감, D-90류 배치, 미납 처리 배치 등 정기 작업의 중복 실행 방지';
COMMENT ON COLUMN shedlock.name IS '이름';
COMMENT ON COLUMN shedlock.lock_until IS '락 만료 시각';
COMMENT ON COLUMN shedlock.locked_at IS '락 획득 시각';
COMMENT ON COLUMN shedlock.locked_by IS '락을 획득한 인스턴스';
COMMENT ON COLUMN office.updated_at IS '사무소 집계의 마지막 변경 시각';
COMMENT ON COLUMN office.version IS '사무소 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN office_registration.updated_at IS '인증 신청의 마지막 변경 시각';
COMMENT ON COLUMN office_registration.version IS '인증 신청의 낙관적 잠금 버전';
COMMENT ON COLUMN office_membership.updated_at IS '소속 집계의 마지막 변경 시각';
COMMENT ON COLUMN office_membership.version IS '소속 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN property.version IS '매물 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN customer.updated_at IS '고객 집계의 마지막 변경 시각';
COMMENT ON COLUMN customer.version IS '고객 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN visit_coordination.version IS '방문 조율 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN contract.updated_at IS '계약 집계의 마지막 변경 시각';
COMMENT ON COLUMN contract.version IS '계약 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN monthly_settlement.created_at IS '월말결산 집계의 생성 시각';
COMMENT ON COLUMN monthly_settlement.updated_at IS '월말결산 집계의 마지막 변경 시각';
COMMENT ON COLUMN monthly_settlement.version IS '월말결산 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN task.updated_at IS '업무 집계의 마지막 변경 시각';
COMMENT ON COLUMN task.version IS '업무 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN subscription.updated_at IS '구독 집계의 마지막 변경 시각';
COMMENT ON COLUMN subscription.version IS '구독 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN subscription.first_billing_scheduled_at IS '첫 실제 청구가 시작될 예정 시각이다. 결제 준비와 수단 등록과 구매 동의는 이 시각과 분리하며 값이 없으면 예정 시각이 정해지지 않은 것이다';
COMMENT ON COLUMN subscription.pre_payment_since IS '무료 종료 시점에 유효한 동의나 카드가 없어 PRE_PAYMENT로 둔 시작 시각이다. 이 시각부터 30일 뒤 종료한다. 이 상태가 시작되지 않았으면 NULL이다';
COMMENT ON COLUMN import_batch.updated_at IS '데이터 이전 집계의 마지막 변경 시각';
COMMENT ON COLUMN import_batch.version IS '데이터 이전 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN support_inquiry.updated_at IS '지원 문의 집계의 마지막 변경 시각';
COMMENT ON COLUMN support_inquiry.version IS '지원 문의 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN enterprise_lead.updated_at IS '기업 문의 집계의 마지막 변경 시각';
COMMENT ON COLUMN enterprise_lead.version IS '기업 문의 집계의 낙관적 잠금 버전';
COMMENT ON COLUMN enterprise_lead.contract_reference IS '계약서 번호나 전자계약 문서 번호. CONTRACTED 상태에서만 값이 있다';
COMMENT ON COLUMN enterprise_lead.contracted_at IS '계약 체결 시각. CONTRACTED 상태에서만 값이 있다';
COMMENT ON COLUMN enterprise_lead.closed_reason IS '`NO_RESPONSE`, `CUSTOMER_WITHDREW`, `OUT_OF_SCOPE`, `DUPLICATE`, `OTHER` 중 하나. CLOSED 상태에서만 값이 있다';
COMMENT ON COLUMN enterprise_lead.closed_note IS '종료 사유 설명. CLOSED 상태에서만 값이 있다';
COMMENT ON COLUMN enterprise_lead.closed_from_status IS '종료 전 진행 상태. 재개할 때 되돌릴 단계를 정한다';
COMMENT ON COLUMN enterprise_lead.closed_at IS '문의를 종료한 시각. CLOSED 상태에서만 값이 있다';
COMMENT ON INDEX uq_import_support_request_active_batch IS '한 이전 실행 단위에는 취소·거절되지 않은 유료 이전 지원 신청이 하나만 있을 수 있다';
COMMENT ON TABLE approver_profile IS '승인자 선택적 계정이다. 휴대폰 번호의 HMAC 해시와 마지막 네 자리만 저장하고 번호 원문, 이름, 이메일, 비밀번호는 저장하지 않는다. 해지하면 번호 정보를 지우고 껍데기 행만 남긴다. 승인자 링크 방식은 계정과 무관하게 유지된다';
COMMENT ON COLUMN approver_profile.id IS '승인자 프로필 식별자';
COMMENT ON COLUMN approver_profile.phone_hash IS '정규화한 휴대폰 번호의 HMAC-SHA256 해시. 번호 원문은 저장하지 않는다. ACTIVE일 때만 값이 있고 해지하면 지운다. 같은 번호의 프로필은 하나다';
COMMENT ON COLUMN approver_profile.phone_last4 IS '화면 표시용. ACTIVE일 때만 값이 있고 해지하면 지운다';
COMMENT ON COLUMN approver_profile.status IS 'ACTIVE, CLOSED 중 하나';
COMMENT ON COLUMN approver_profile.created_at IS '프로필 생성 시각';
COMMENT ON COLUMN approver_profile.last_login_at IS '마지막 로그인 성공 시각';
COMMENT ON COLUMN approver_profile.closed_at IS 'CLOSED와 동치';
COMMENT ON COLUMN approver_profile.close_source IS 'SELF(승인자 본인), OPERATOR(개인정보 권리 요청 처리) 중 하나. CLOSED일 때만 값 존재';
COMMENT ON COLUMN approver_profile.version IS '낙관적 잠금 버전';
COMMENT ON TABLE approver_profile_approval IS '승인자 프로필과 출입승인의 연결과 연결 제안이다. 출입승인당 활성 연결은 하나다. 링크 화면에서 번호 인증을 마치면 그 출입승인이 바로 연결되고 같은 번호 해시의 다른 출입승인은 승인자가 수락해야 연결된다. 거절하거나 해제한 출입승인은 다시 제안하지 않는다';
COMMENT ON COLUMN approver_profile_approval.id IS '연결 식별자';
COMMENT ON COLUMN approver_profile_approval.profile_id IS '승인자 프로필';
COMMENT ON COLUMN approver_profile_approval.approval_id IS '연결 대상 출입승인';
COMMENT ON COLUMN approver_profile_approval.status IS 'PENDING_CONFIRM(연결 제안), LINKED(연결됨), REJECTED(거절), UNLINKED(해제) 중 하나';
COMMENT ON COLUMN approver_profile_approval.linked_via IS 'LINK_TOKEN(링크 화면에서 번호 인증), PHONE_MATCH(번호 해시 일치로 제안) 중 하나';
COMMENT ON COLUMN approver_profile_approval.proposed_at IS '연결 제안 또는 연결을 만든 시각';
COMMENT ON COLUMN approver_profile_approval.decided_at IS '수락·거절·링크 인증 연결 시각. PENDING_CONFIRM이면 NULL';
COMMENT ON COLUMN approver_profile_approval.unlinked_at IS 'UNLINKED일 때만 값 존재';
COMMENT ON INDEX uq_approver_profile_approval_linked IS '출입승인당 활성 연결은 하나만 둔다';
COMMENT ON TABLE approver_condition_bulk_batch IS '승인자가 여러 출입승인에 같은 조건을 한 번에 적용한 요청 한 건의 처리 결과다. 한 번에 최대 20개이며 출입승인마다 독립 트랜잭션으로 처리한다';
COMMENT ON COLUMN approver_condition_bulk_batch.id IS '일괄 처리 식별자';
COMMENT ON COLUMN approver_condition_bulk_batch.profile_id IS '요청한 승인자 프로필';
COMMENT ON COLUMN approver_condition_bulk_batch.requested_count IS '요청한 출입승인 수. 1 이상 20 이하';
COMMENT ON COLUMN approver_condition_bulk_batch.applied_count IS '적용된 출입승인 수. 0 이상';
COMMENT ON COLUMN approver_condition_bulk_batch.needs_impact_ack_count IS '영향 확인이 필요해 적용하지 않은 출입승인 수. 0 이상';
COMMENT ON COLUMN approver_condition_bulk_batch.failed_count IS '실패한 출입승인 수. 0 이상';
COMMENT ON COLUMN approver_condition_bulk_batch.created_at IS '요청을 받은 시각';
COMMENT ON COLUMN approver_condition_bulk_batch.completed_at IS '모든 출입승인 처리가 끝난 시각';
COMMENT ON TABLE approver_condition_bulk_item IS '일괄 처리 한 건 안의 출입승인별 결과다. 적용된 항목은 새 조건 버전을 가리키고 실패한 항목은 사유를 가진다';
COMMENT ON COLUMN approver_condition_bulk_item.id IS '일괄 처리 항목 식별자';
COMMENT ON COLUMN approver_condition_bulk_item.batch_id IS '소속 일괄 처리';
COMMENT ON COLUMN approver_condition_bulk_item.approval_id IS '대상 출입승인';
COMMENT ON COLUMN approver_condition_bulk_item.result IS 'APPLIED, NEEDS_IMPACT_ACK, FAILED 중 하나';
COMMENT ON COLUMN approver_condition_bulk_item.condition_id IS 'APPLIED일 때만 값 존재. 새 조건 버전이 같은 출입승인에 속하는지 복합 FK로 검증';
COMMENT ON COLUMN approver_condition_bulk_item.failure_code IS 'FAILED일 때만 값 존재. NOT_LINKED, NOT_PRIMARY, APPROVAL_INACTIVE, OFFICE_RESTRICTED, INVALID_CONDITION 중 하나';
COMMENT ON COLUMN approver_condition_bulk_item.affected_item_count IS '영향받는 확정 방문 수. 0 이상';
COMMENT ON TABLE approver_auth_event IS '승인자 계정의 생성, 로그인, 연결, 일괄 적용, 해지 사건을 기록하는 추가 전용 감사 이력이다. 번호 원문과 인증번호는 남기지 않는다';
COMMENT ON COLUMN approver_auth_event.id IS '사건 식별자';
COMMENT ON COLUMN approver_auth_event.profile_id IS '사건의 프로필';
COMMENT ON COLUMN approver_auth_event.approval_id IS '출입승인과 관련된 사건이면 값 존재';
COMMENT ON COLUMN approver_auth_event.batch_id IS 'BULK_APPLIED일 때만 값 존재';
COMMENT ON COLUMN approver_auth_event.event_type IS 'CLAIM_COMPLETED, LOGIN_SUCCEEDED, LOGIN_FAILED, APPROVAL_LINKED, APPROVAL_REJECTED, APPROVAL_UNLINKED, BULK_APPLIED, SESSION_REVOKED, PROFILE_CLOSED 중 하나';
COMMENT ON COLUMN approver_auth_event.reason IS 'SELF, PHONE_CHANGED, APPROVAL_ENDED, PROFILE_CLOSED, TOO_MANY_SESSIONS 같은 사유 코드';
COMMENT ON COLUMN approver_auth_event.ip_hmac IS '보안 감사용 접속 IP의 서버 비밀키 HMAC-SHA256 변환값이다. IP 원문은 저장하지 않는다. 사건이 발생한 지 90일이 지나면 익명화 배치가 이 값과 키 버전을 비운다. 이 보관 일수는 변호사 검토 전 초안이다';
COMMENT ON COLUMN approver_auth_event.hmac_key_version IS '변환에 쓴 비밀키의 버전이다. IP 변환값과 함께 값이 있거나 함께 NULL이다';
COMMENT ON CONSTRAINT ck_approver_auth_event_ip ON approver_auth_event IS 'IP 변환값과 키 버전은 함께 있거나 함께 없다';
COMMENT ON COLUMN approver_auth_event.occurred_at IS '사건 발생 시각';
COMMENT ON TABLE visit_approver_condition_date_rule IS '승인자 조건 버전에 딸린 날짜별 필수 조건이다. 행 하나는 한 날짜의 한 항목이며 그 날짜의 그 항목에 한해 조건 버전의 기본 값을 대체한다. 행이 없는 항목은 기본 값을 쓴다. 방식 VALUE는 값 지정이고 UNLIMITED는 그 날짜는 제한 없음이다. 숫자 기본값을 두지 않는다. 보유기한이 지나도 조건 버전과 함께 지우지 않고 값을 그대로 남긴다. 신청 판정 이력의 근거이기 때문이다';
COMMENT ON COLUMN visit_approver_condition_date_rule.id IS '날짜별 필수 조건 식별자';
COMMENT ON COLUMN visit_approver_condition_date_rule.condition_id IS '소속 조건 버전';
COMMENT ON COLUMN visit_approver_condition_date_rule.rule_date IS '규칙을 적용하는 KST 날짜. 조건 버전의 적용 기간 안인지는 서비스 계층이 검사한다';
COMMENT ON COLUMN visit_approver_condition_date_rule.rule_item IS 'MAX_VISITS_PER_DAY, MIN_GAP, MIN_LEAD, SINGLE_VISIT_MAX 중 하나';
COMMENT ON COLUMN visit_approver_condition_date_rule.limit_kind IS 'VALUE(값 지정), UNLIMITED(그 날짜는 그 항목을 제한하지 않음) 중 하나';
COMMENT ON COLUMN visit_approver_condition_date_rule.limit_value IS 'VALUE일 때만 값이 있다. 하루 최대 횟수와 1회 허용 시간은 1 이상, 방문 간 최소 간격과 최소 사전 신청 시간은 0 이상. 숫자 기본값을 두지 않는다';
COMMENT ON TABLE visit_property_apply_grant IS '매물을 가진 사무소가 출입승인 단위로 다른 사무소 또는 그 사무소의 특정 승인된 중개사에게 방문 신청 권한을 허용한 기록이다. 활성 허용이 있어야 다른 사무소가 그 매물에 방문 신청을 낼 수 있다. 허용은 새 출입승인으로 옮겨지지 않고 재허용은 없다. 허용으로 받는 권한은 후보 매물 담기, 방문 신청, 확정 변경 신청, 신청 철회, 자기 조율 건의 결과 기록이며 승인자 정보와 조건 값, 링크 발급은 포함하지 않는다';
COMMENT ON COLUMN visit_property_apply_grant.id IS '신청 허용 식별자';
COMMENT ON COLUMN visit_property_apply_grant.approval_id IS '허용이 묶인 출입승인. 대표 승인자 출입승인인지는 서비스 계층이 검사한다';
COMMENT ON COLUMN visit_property_apply_grant.property_id IS '대상 매물. 출입승인의 매물과 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_property_apply_grant.owner_office_id IS '매물을 가진 사무소. 매물의 소속 사무소와 일치를 복합 FK로 검증';
COMMENT ON COLUMN visit_property_apply_grant.grantee_office_id IS '방문 신청 권한을 허용받은 사무소. 소유 사무소와 달라야 한다';
COMMENT ON COLUMN visit_property_apply_grant.grantee_membership_id IS '값이 있으면 그 중개사 한 명에게만 허용한다. NULL이면 허용받은 사무소의 승인된 대표와 소속공인중개사 전체. 소속이 허용받은 사무소의 것인지 복합 FK로 검증';
COMMENT ON COLUMN visit_property_apply_grant.granted_by_membership_id IS '허용한 소유 사무소의 승인된 대표 또는 소속공인중개사';
COMMENT ON COLUMN visit_property_apply_grant.granted_at IS '허용 시각';
COMMENT ON COLUMN visit_property_apply_grant.expires_at IS 'NULL이면 출입승인이 끝나거나 철회될 때까지. 값이 있으면 허용 시각보다 늦어야 한다. 출입승인 유효 종료 이하인지는 서비스 계층이 검사한다';
COMMENT ON COLUMN visit_property_apply_grant.revoked_at IS 'NULL이면 회수되지 않음';
COMMENT ON COLUMN visit_property_apply_grant.revoke_source IS 'OFFICE(직원이 회수), SYSTEM(매물 보관 등 시스템 회수). 회수되었을 때만 값이 있다';
COMMENT ON COLUMN visit_property_apply_grant.revoked_by_membership_id IS 'OFFICE 회수일 때만 값 존재. 소유 사무소의 소속';
COMMENT ON COLUMN visit_property_apply_grant.revoke_reason IS '회수되었을 때만 값이 있고 공백이 아니어야 한다';
COMMENT ON INDEX uq_visit_property_apply_grant_active_office IS '같은 출입승인과 같은 허용받은 사무소의 사무소 전체 활성 허용은 하나만 둔다';
COMMENT ON INDEX uq_visit_property_apply_grant_active_member IS '같은 출입승인과 같은 허용받은 중개사의 활성 허용은 하나만 둔다';
COMMENT ON TABLE visit_property_apply_grant_event IS '신청 허용의 부여, 회수, 만료를 기록하는 추가 전용 이력이다. 허용당 부여 사건과 만료 사건은 각각 한 번만 기록한다. 종결된 신청 수와 사유 코드를 함께 남긴다';
COMMENT ON COLUMN visit_property_apply_grant_event.id IS '이력 식별자';
COMMENT ON COLUMN visit_property_apply_grant_event.grant_id IS '대상 허용';
COMMENT ON COLUMN visit_property_apply_grant_event.event_type IS 'GRANTED(부여), REVOKED(회수), EXPIRED(만료 처리) 중 하나';
COMMENT ON COLUMN visit_property_apply_grant_event.source IS 'OFFICE(직원), SYSTEM(시스템) 중 하나';
COMMENT ON COLUMN visit_property_apply_grant_event.actor_membership_id IS 'OFFICE일 때만 값 존재';
COMMENT ON COLUMN visit_property_apply_grant_event.reason IS 'USER_REVOKED, PROPERTY_ARCHIVED, APPROVAL_REVOKED, GRANT_EXPIRED 같은 사유 코드. 자유 텍스트 사유는 허용 행의 revoke_reason에 둔다';
COMMENT ON COLUMN visit_property_apply_grant_event.affected_request_count IS '이 사건으로 기간 만료로 종결된 신청 대기 신청 수. 0 이상';
COMMENT ON COLUMN visit_property_apply_grant_event.occurred_at IS '사건 발생 시각';
COMMENT ON TABLE visit_review IS '승인자가 결과가 완료인 방문 한 건에 대해 남긴 평가다. 승인자에서 중개사로 가는 단방향이며 방문 일정 항목당 한 건이다. 시간 준수, 사전 연락, 신청 내용 준수를 예, 아니오, 답하지 않음으로 받고 자유 서술, 점수, 별점은 두지 않는다. 평가 대상 중개사는 확정 근거 신청을 낸 구성원이다. 신뢰 요약은 상태가 ACTIVE이고 방문 일정 항목의 현재 결과가 완료인 평가만 쓴다. 행을 지우지 않고 상태로 종결한다. 설계 기준이며 구현 완료를 뜻하지 않는다. 평가 입력일부터 보관 기간(REVIEW_RECORD)이 지나면 이의 기록을 먼저 지운 뒤 평가를 파기 큐로 지운다';
COMMENT ON COLUMN visit_review.id IS '방문 평가 내부 식별자';
COMMENT ON COLUMN visit_review.schedule_item_id IS '평가 대상 방문 일정 항목이다. 방문 일정 항목당 평가는 한 건이다';
COMMENT ON COLUMN visit_review.request_id IS '평가 시점의 확정 근거 신청이다. 방문 일정 항목의 확정 근거 신청과 일치함을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review.approval_id IS '평가한 승인자의 출입승인이다. 확정 근거 신청의 출입승인과 일치함을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review.reviewed_membership_id IS '평가받은 중개사의 소속이다. 확정 근거 신청의 신청 구성원과 일치함을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review.reviewed_office_id IS '평가받은 중개사의 사무소다. 확정 근거 신청의 신청 사무소와 일치함을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review.approver_link_id IS '마지막 입력을 승인자 매물 링크로 했을 때의 링크다. 출입승인과 일치함을 복합 외래키로 검증한다. 승인자 계정으로 입력했으면 NULL이며 approver_profile_id와 둘 중 하나만 값이 있다';
COMMENT ON COLUMN visit_review.approver_profile_id IS '마지막 입력을 승인자 계정으로 했을 때의 프로필이다. 프로필과 출입승인의 연결 행이 있음을 복합 외래키로 검증하며 연결이 활성(LINKED)이고 대표 승인자 출입승인인지는 서비스 계층이 검사한다. 링크로 입력했으면 NULL이다';
COMMENT ON COLUMN visit_review.punctuality IS '시간 준수 응답이다. YES, NO, SKIP 중 하나이며 SKIP은 답하지 않음이다';
COMMENT ON COLUMN visit_review.advance_contact IS '사전 연락 응답이다. YES, NO, SKIP 중 하나이며 SKIP은 답하지 않음이다';
COMMENT ON COLUMN visit_review.as_requested IS '신청 내용 준수 응답이다. YES, NO, SKIP 중 하나이며 SKIP은 답하지 않음이다. 세 항목이 모두 SKIP인 평가는 저장하지 않는다';
COMMENT ON COLUMN visit_review.status IS 'ACTIVE, DISPUTED, REMOVED, WITHDRAWN 중 하나다. ACTIVE만 신뢰 요약에 쓴다. DISPUTED는 이의 처리 중이며 요약에서 제외한다. REMOVED는 운영자가 삭제한 평가이고 WITHDRAWN은 승인자가 철회한 평가다';
COMMENT ON COLUMN visit_review.review_deadline_at IS '평가 입력 기한이다. 최초 입력 때 현재 완료 결과 기록 시각에 14일을 더해 저장하며 최초 입력 시각보다 늦어야 한다';
COMMENT ON COLUMN visit_review.submitted_at IS '최초 입력 시각';
COMMENT ON COLUMN visit_review.last_revised_at IS '마지막 입력, 수정, 철회, 재입력 시각이다. 이의 제기 가능 기간의 시작 기준이다';
COMMENT ON COLUMN visit_review.revision_count IS '승인자의 수정 횟수다. 0 이상 2 이하이며 철회 뒤 재입력도 수정으로 센다';
COMMENT ON COLUMN visit_review.withdrawn_at IS '승인자가 철회한 시각이다. 상태가 WITHDRAWN일 때만 값이 있고 재입력하면 NULL로 돌아간다';
COMMENT ON COLUMN visit_review.removed_at IS '운영자가 삭제한 시각이다. 상태가 REMOVED와 동치다';
COMMENT ON COLUMN visit_review.removed_reason_code IS 'DISPUTE_ACCEPTED, LEGAL_REQUEST, PRIVACY_REQUEST, OPERATOR_DISCRETION 중 하나다. 상태가 REMOVED일 때만 값이 있다';
COMMENT ON COLUMN visit_review.removed_by_operator_id IS '삭제한 운영자다. 상태가 REMOVED일 때만 값이 있다';
COMMENT ON COLUMN visit_review.updated_at IS '마지막 변경 일시';
COMMENT ON COLUMN visit_review.version IS '낙관적 잠금 버전';
COMMENT ON INDEX ix_visit_review_membership_active IS '신뢰 요약이 평가받은 구성원의 ACTIVE 평가만 빠르게 모으도록 하는 부분 인덱스다';
COMMENT ON INDEX ix_visit_review_approval IS '승인자 링크 화면이 출입승인의 평가를 모으는 인덱스다';
COMMENT ON TABLE visit_review_dispute IS '평가받은 중개사나 같은 사무소 대표가 평가에 낸 이의다. 평가당 한 건이며 접수되면 평가가 요약 계산에서 빠진다. 사이로 운영자의 지원 역할이 평가 유지 또는 평가 삭제로 결정한다. 처리 목표 7영업일은 표시용이며 기한이 지나도 자동으로 처리하지 않는다. 설계 기준이며 구현 완료를 뜻하지 않는다';
COMMENT ON COLUMN visit_review_dispute.id IS '이의 내부 식별자';
COMMENT ON COLUMN visit_review_dispute.review_id IS '이의 대상 평가다. 평가당 이의는 한 건이다';
COMMENT ON COLUMN visit_review_dispute.office_id IS '평가받은 중개사의 사무소다. 평가의 사무소와 일치함을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review_dispute.filed_by_membership_id IS '이의를 낸 직원이다. 평가받은 구성원 본인 또는 같은 사무소 대표여야 하며 이 조건은 서비스 계층이 검사한다. 같은 사무소 소속은 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_review_dispute.reason_code IS 'FACT_INCORRECT는 사실과 다름, WRONG_TARGET은 다른 방문이나 다른 중개사에 대한 평가, OTHER는 기타다';
COMMENT ON COLUMN visit_review_dispute.reason_text IS '사유 설명이다. 1자 이상 500자 이하이며 고객 이름과 연락처를 넣지 않는다';
COMMENT ON COLUMN visit_review_dispute.status IS 'OPEN은 처리 중, UPHELD는 평가 유지, REMOVED는 평가 삭제다. OPEN에서 나머지 둘로만 전이한다';
COMMENT ON COLUMN visit_review_dispute.filed_at IS '이의 접수 시각이다. 처리 목표는 이 시각부터 7영업일이다';
COMMENT ON COLUMN visit_review_dispute.decided_at IS '운영자가 결정한 시각이다. 상태가 OPEN이 아닐 때만 값이 있다';
COMMENT ON COLUMN visit_review_dispute.decided_by_operator_id IS '결정한 운영자다. 결정 시각과 함께 값이 있다';
COMMENT ON COLUMN visit_review_dispute.decision_note IS '결정 사유 메모다. 상태가 OPEN이 아니면 필수이고 500자 이하이며 중개사 화면에 보인다';
COMMENT ON COLUMN visit_review_dispute.version IS '낙관적 잠금 버전';
COMMENT ON INDEX ix_visit_review_dispute_open IS '운영자 이의 큐가 열린 이의를 접수 순으로 모으는 부분 인덱스다';
COMMENT ON TABLE visit_preferred_broker IS '승인자가 출입승인 단위로 지정한 선호 중개사다. 대상은 중개사(구성원)이며 지정은 승인자 비교 목록의 위쪽 묶음과 칩 표시에만 쓰인다. 선택, 확정, 재검증, 시간 마감에 영향을 주지 않고 신청 중개사에게 보이지 않는다. 출입승인당 활성 지정은 최대 5명이며 이 상한은 서비스 계층이 검사한다. 해제는 행을 지우지 않고 해제 시각을 남긴다. 설계 기준이며 구현 완료를 뜻하지 않는다';
COMMENT ON COLUMN visit_preferred_broker.id IS '선호 지정 내부 식별자';
COMMENT ON COLUMN visit_preferred_broker.approval_id IS '매물과 승인자 단위인 출입승인이다. 지정과 해제에 쓴 링크가 이 출입승인의 링크임을 복합 외래키로 검증하며 이 값이 출입승인 행에 존재함은 링크의 외래키가 보장한다';
COMMENT ON COLUMN visit_preferred_broker.broker_membership_id IS '선호 중개사로 지정된 구성원이다. 이 출입승인에서 신청을 냈거나 방문을 완료한 구성원이어야 하며 이 조건은 서비스 계층이 검사한다';
COMMENT ON COLUMN visit_preferred_broker.designated_via_link_id IS '지정을 승인자 매물 링크로 했을 때의 링크다. 승인자 계정으로 지정했으면 NULL이며 designated_via_profile_id와 둘 중 하나만 값이 있다';
COMMENT ON COLUMN visit_preferred_broker.designated_via_profile_id IS '지정을 승인자 계정으로 했을 때의 프로필이다. 프로필과 출입승인의 연결 행이 있음을 복합 외래키로 검증한다';
COMMENT ON COLUMN visit_preferred_broker.released_via_profile_id IS '해제를 승인자 계정으로 했을 때의 프로필이다. 해제 시각이 있을 때 released_via_link_id와 둘 중 하나만 값이 있다';
COMMENT ON COLUMN visit_preferred_broker.source_request_id IS '지정 근거로 보낸 방문 신청이다. 근거 방문 일정 항목과 정확히 하나만 값이 있다';
COMMENT ON COLUMN visit_preferred_broker.source_schedule_item_id IS '지정 근거로 보낸 완료 방문 일정 항목이다. 근거 신청과 정확히 하나만 값이 있다';
COMMENT ON COLUMN visit_preferred_broker.designated_at IS '지정 시각';
COMMENT ON COLUMN visit_preferred_broker.released_at IS '해제 시각이다. NULL이면 활성 지정이다';
COMMENT ON COLUMN visit_preferred_broker.released_via_link_id IS '해제를 승인자 매물 링크로 했을 때의 링크다. 해제 시각이 있으면 링크와 프로필 중 하나만 값이 있다';
COMMENT ON INDEX uq_visit_preferred_broker_active IS '같은 출입승인에서 같은 구성원의 활성 지정은 하나만 둔다';
COMMENT ON TABLE visit_selection_trust_snapshot IS '승인자가 신청을 선택하는 트랜잭션에서 비교에 쓴 신청마다 저장한 신뢰 요약 스냅샷이다. 정책 버전, 기준 시각, 구성원, 선호 여부, 건수, 상태, 구간을 남겨 선택 시점의 비교 근거를 보존한다. 재검증이 실패해도 남기며 신뢰 요약은 재검증이나 확정에 쓰지 않는다. 선택 시점에 승인 대기였던 신청만 담으므로 선택 기록의 비교한 신청 수보다 행이 적을 수 있다. 건수는 마스킹하지 않은 실제 집계값이다. 추가 전용이며 이 릴리스는 이 표를 읽는 API를 두지 않는다. 설계 기준이며 구현 완료를 뜻하지 않는다';
COMMENT ON COLUMN visit_selection_trust_snapshot.id IS '스냅샷 내부 식별자';
COMMENT ON COLUMN visit_selection_trust_snapshot.selection_id IS '이 스냅샷을 만든 승인자 선택 사건이다';
COMMENT ON COLUMN visit_selection_trust_snapshot.compared_request_id IS '비교에 쓴 방문 신청이다';
COMMENT ON COLUMN visit_selection_trust_snapshot.broker_membership_id IS '비교한 신청의 신청 구성원이다. 신청 행의 구성원과 일치함은 서비스 계층이 보장한다';
COMMENT ON COLUMN visit_selection_trust_snapshot.is_selected IS '이 신청이 승인자가 선택한 신청이면 true다. 선택 사건당 하나만 true다';
COMMENT ON COLUMN visit_selection_trust_snapshot.is_preferred IS '선택 시점에 이 구성원이 출입승인의 활성 선호 중개사였는지 여부다';
COMMENT ON COLUMN visit_selection_trust_snapshot.policy_version IS '신뢰 요약 계산에 쓴 정책 버전이다. 현재 TRUST_V1이다';
COMMENT ON COLUMN visit_selection_trust_snapshot.as_of IS '집계 기준 시각이다';
COMMENT ON COLUMN visit_selection_trust_snapshot.window_months IS '집계 기간 개월 수다. 현재 12다';
COMMENT ON COLUMN visit_selection_trust_snapshot.state IS 'NO_DATA, INSUFFICIENT, AVAILABLE 중 하나다. 평가 반영 방문 수가 0이면 NO_DATA, 5 미만이거나 서로 다른 출입승인 수가 3 미만이거나 구간이 계산된 항목이 없으면 INSUFFICIENT, 그 밖에는 AVAILABLE이다';
COMMENT ON COLUMN visit_selection_trust_snapshot.overall_band IS '전체 구간이다. HIGH, MID, LOW 중 하나이며 상태가 AVAILABLE일 때만 값이 있다';
COMMENT ON COLUMN visit_selection_trust_snapshot.completed_visit_count IS '집계 기간의 완료 방문 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.evaluated_visit_count IS '상태가 ACTIVE인 평가가 있는 완료 방문 수다. 완료 방문 수 이하다';
COMMENT ON COLUMN visit_selection_trust_snapshot.distinct_approver_count IS '그 평가들의 서로 다른 출입승인 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.punctuality_answered_count IS '시간 준수 항목에서 예 또는 아니오로 응답한 수다. 답하지 않음은 세지 않는다';
COMMENT ON COLUMN visit_selection_trust_snapshot.punctuality_yes_count IS '시간 준수 항목의 예 응답 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.punctuality_band IS '시간 준수 항목 구간이다. 응답 수가 5 이상이고 상태가 AVAILABLE일 때만 값이 있다';
COMMENT ON COLUMN visit_selection_trust_snapshot.advance_contact_answered_count IS '사전 연락 항목에서 예 또는 아니오로 응답한 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.advance_contact_yes_count IS '사전 연락 항목의 예 응답 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.advance_contact_band IS '사전 연락 항목 구간이다. 응답 수가 5 이상이고 상태가 AVAILABLE일 때만 값이 있다';
COMMENT ON COLUMN visit_selection_trust_snapshot.as_requested_answered_count IS '신청 내용 준수 항목에서 예 또는 아니오로 응답한 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.as_requested_yes_count IS '신청 내용 준수 항목의 예 응답 수다';
COMMENT ON COLUMN visit_selection_trust_snapshot.as_requested_band IS '신청 내용 준수 항목 구간이다. 응답 수가 5 이상이고 상태가 AVAILABLE일 때만 값이 있다';
COMMENT ON COLUMN visit_selection_trust_snapshot.created_at IS '스냅샷 저장 시각';
COMMENT ON INDEX uq_visit_selection_trust_snapshot_selected IS '선택 사건당 선택된 신청의 스냅샷은 하나만 둔다';
COMMENT ON TABLE legal_retention_rule IS '데이터군별 보관 기간 규칙이다. 보관 일수는 코드에 고정하지 않고 이 표의 값을 읽는다. status가 ASSUMPTION인 값은 확정 규칙 값이며 변호사 검토 전 초안이다. 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_retention_rule.id IS '규칙 식별자';
COMMENT ON COLUMN legal_retention_rule.rule_code IS '규칙 코드다. 배치와 서비스 계층이 이 코드로 값을 찾는다';
COMMENT ON COLUMN legal_retention_rule.data_group_label IS '데이터군 한글 이름이다';
COMMENT ON COLUMN legal_retention_rule.retention_days IS '기산점부터 보관하는 일수다';
COMMENT ON COLUMN legal_retention_rule.anchor_event IS '보관 기간을 세기 시작하는 사건이다';
COMMENT ON COLUMN legal_retention_rule.basis_note IS '확정 규칙의 근거 설명이다. 근거 조항을 확인하지 못했으면 검토 대상 법령 이름만 적는다';
COMMENT ON COLUMN legal_retention_rule.status IS 'ASSUMPTION은 확정 규칙 값이며 법률 확인 전, LAWYER_CONFIRMED는 변호사 확인, ADVISOR_CONFIRMED는 세무사 확인이다';
COMMENT ON COLUMN legal_retention_rule.effective_from IS '이 값을 적용하기 시작한 날이다';
COMMENT ON COLUMN legal_retention_rule.updated_by_operator_id IS '마지막으로 값을 바꾼 운영자이며 초기 값은 비어 있다';
COMMENT ON COLUMN legal_retention_rule.updated_at IS '마지막 변경 시각';
COMMENT ON COLUMN legal_retention_rule.version IS '낙관적 잠금 버전';
COMMENT ON TABLE consent_notice_delivery IS '광고성 정보 수신 설정의 처리 결과 통지와 2년 주기 재확인 안내의 발송 이력이다. 통지 기한의 기준은 이용자가 의사를 표시한 날이다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN consent_notice_delivery.id IS '발송 이력 식별자';
COMMENT ON COLUMN consent_notice_delivery.user_id IS '안내를 받는 사용자';
COMMENT ON COLUMN consent_notice_delivery.terms_agreement_id IS '통지의 원인이 된 동의 또는 철회 이벤트다. 재확인 안내는 현재 동의를 만든 이벤트를 가리킨다';
COMMENT ON COLUMN consent_notice_delivery.notice_type IS 'MARKETING_RESULT는 처리 결과 통지, MARKETING_RECONFIRM은 2년 주기 재확인 안내다';
COMMENT ON COLUMN consent_notice_delivery.cycle_no IS '재확인 안내의 주기 번호다. 처리 결과 통지는 항상 1이다';
COMMENT ON COLUMN consent_notice_delivery.expressed_at IS '이용자가 의사를 표시한 시각이다. 재확인 안내는 동의한 시각이다';
COMMENT ON COLUMN consent_notice_delivery.target_at IS '내부 목표 발송 시각이다. 처리 결과 통지는 당일, 재확인 안내는 기한 30일 전이다';
COMMENT ON COLUMN consent_notice_delivery.due_at IS '발송 기한이다. 처리 결과 통지는 의사 표시일부터 14일, 재확인 안내는 주기가 끝나는 날의 전날이다';
COMMENT ON COLUMN consent_notice_delivery.status IS '발송 상태다. SKIPPED_NO_EMAIL은 인증된 이메일이 없어 화면 안내만 한 경우다';
COMMENT ON COLUMN consent_notice_delivery.attempt_count IS '발송 시도 횟수';
COMMENT ON COLUMN consent_notice_delivery.sent_at IS '발송을 마친 시각';
COMMENT ON COLUMN consent_notice_delivery.failure_code IS '마지막 실패 코드다';
COMMENT ON COLUMN consent_notice_delivery.created_at IS '발송 대상으로 만든 시각';
COMMENT ON TABLE consent_guest_notice_ack IS '비회원 링크 화면에서 개인정보 안내를 확인한 뒤 입력이나 선택을 제출한 사건이다. 비회원에게 동의를 받는 것이 아니라 어느 버전의 안내를 보고 제출했는지를 남긴다. 사무소 단위로 묶어 조회한다. 고객 링크 행을 지우면 함께 지운다. 승인자 매물 링크 행은 지우지 않고 익명화하며 그때 배치가 이 링크의 확인 기록을 지운다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN consent_guest_notice_ack.id IS '확인 기록 식별자';
COMMENT ON COLUMN consent_guest_notice_ack.office_id IS '링크를 발급한 사무소다. 승인자 계정 세션으로 제출한 경우에는 그 제출이 다룬 출입승인을 가진 사무소다';
COMMENT ON COLUMN consent_guest_notice_ack.link_kind IS 'APPROVER_PROPERTY는 승인자 매물 링크, CUSTOMER는 고객 링크, APPROVER_PORTAL은 승인자 계정 세션이다';
COMMENT ON COLUMN consent_guest_notice_ack.approver_profile_id IS '승인자 계정 세션으로 제출한 경우의 프로필이다. link_kind가 APPROVER_PORTAL일 때만 값이 있다. 이때 office_id는 그 제출이 다룬 출입승인을 가진 사무소다';
COMMENT ON COLUMN consent_guest_notice_ack.approver_property_link_id IS '승인자 매물 링크다. link_kind가 APPROVER_PROPERTY일 때만 값이 있다';
COMMENT ON COLUMN consent_guest_notice_ack.customer_link_id IS '고객 링크다. link_kind가 CUSTOMER일 때만 값이 있다';
COMMENT ON COLUMN consent_guest_notice_ack.terms_code IS '화면에 보인 안내 항목 코드다. display_context가 LINK_NOTICE인 항목이다';
COMMENT ON COLUMN consent_guest_notice_ack.terms_version IS '화면에 보인 안내 버전이다';
COMMENT ON COLUMN consent_guest_notice_ack.action_type IS '제출한 동작이다. 조건 저장, 시간 제출, 신청 선택, 권리 요청 접수, 방문 평가 제출, 선호 중개사 지정, 승인자 계정 만들기 중 하나다';
COMMENT ON COLUMN consent_guest_notice_ack.resource_version IS '제출로 만들어진 조건 버전이나 응답 버전이다. 해당하는 값이 없으면 비운다';
COMMENT ON COLUMN consent_guest_notice_ack.acknowledged_at IS '서버가 제출을 받은 시각이다';
COMMENT ON TABLE legal_public_link_access_log IS '비회원 링크 접속과 제출의 로그다. IP와 단말 정보는 서버 비밀키로 만든 HMAC 변환값만 저장하고 원문은 남기지 않는다. 링크 행이 지워져도 보관 기한까지 남아야 하므로 링크에 외래키를 걸지 않는다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_public_link_access_log.id IS '로그 식별자';
COMMENT ON COLUMN legal_public_link_access_log.accessed_at IS '요청을 받은 시각';
COMMENT ON COLUMN legal_public_link_access_log.link_kind IS '링크 종류다. 토큰으로 링크를 찾지 못한 요청은 비운다';
COMMENT ON COLUMN legal_public_link_access_log.link_id IS '링크 행 식별자다. link_kind가 APPROVER_PORTAL이면 승인자 프로필 식별자다. 외래키가 아니며 토큰 원문과 세션 식별자는 저장하지 않는다';
COMMENT ON COLUMN legal_public_link_access_log.office_id IS '링크를 발급한 사무소다';
COMMENT ON COLUMN legal_public_link_access_log.action_type IS '요청 종류다. 같은 링크와 같은 IP 변환값의 VIEW는 1분에 한 번만 남긴다';
COMMENT ON COLUMN legal_public_link_access_log.http_status IS '응답 상태 코드다';
COMMENT ON COLUMN legal_public_link_access_log.ip_hmac IS 'IP의 HMAC-SHA256 변환값이다';
COMMENT ON COLUMN legal_public_link_access_log.user_agent_hash IS '사용자 환경 문자열의 해시다';
COMMENT ON COLUMN legal_public_link_access_log.hmac_key_version IS '변환에 쓴 비밀키의 버전이다';
COMMENT ON COLUMN legal_public_link_access_log.purge_after IS '이 날짜가 지나면 배치가 지운다. GUEST_LINK_ACCESS_LOG 일수로 정한다';
COMMENT ON TABLE legal_guest_privacy_intake IS '비회원 링크 화면에서 정보주체가 직접 낸 열람·정정·삭제·처리정지 요청의 접수 기록이다. 운영자가 확인한 뒤 privacy_request로 바꾸어 책임 사무소에 전달한다. 연락처는 결과 통지에 필요한 기간만 보관하고 지운다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_guest_privacy_intake.id IS '접수 식별자';
COMMENT ON COLUMN legal_guest_privacy_intake.office_id IS '링크를 발급한 사무소이며 처리 책임 사무소의 기본값이다';
COMMENT ON COLUMN legal_guest_privacy_intake.link_kind IS '요청에 쓴 링크의 종류';
COMMENT ON COLUMN legal_guest_privacy_intake.link_id IS '요청에 쓴 링크 행 식별자다. link_kind가 APPROVER_PORTAL이면 승인자 프로필 식별자다. 링크 행이 먼저 지워질 수 있으므로 외래키를 걸지 않는다';
COMMENT ON COLUMN legal_guest_privacy_intake.request_type IS '열람, 정정, 삭제, 처리정지 중 요청 종류다. 비회원은 동의를 한 적이 없으므로 동의 철회와 이전은 받지 않는다';
COMMENT ON COLUMN legal_guest_privacy_intake.requester_role IS 'SELF는 정보주체 본인, AGENT는 대리인이다. 대리인은 운영자가 위임 서류를 따로 요청한다';
COMMENT ON COLUMN legal_guest_privacy_intake.contact_channel IS '결과를 받을 연락 방법';
COMMENT ON COLUMN legal_guest_privacy_intake.contact_encrypted IS '암호화한 연락처다. 처리를 마친 뒤 GUEST_INTAKE_CONTACT 일수가 지나면 비운다';
COMMENT ON COLUMN legal_guest_privacy_intake.contact_wiped_at IS '연락처를 지운 시각이다';
COMMENT ON COLUMN legal_guest_privacy_intake.request_note IS '요청 내용을 적은 글이다. 주민등록번호와 전체 계좌번호 패턴은 서비스 계층이 거절한다';
COMMENT ON COLUMN legal_guest_privacy_intake.verification_status IS '운영자가 연락처로 본인 여부를 확인한 결과다. 자동 인증은 출시 후 확장이다';
COMMENT ON COLUMN legal_guest_privacy_intake.status IS 'RECEIVED는 접수, CONVERTED는 권리 요청으로 전환, CLOSED는 종결이다';
COMMENT ON COLUMN legal_guest_privacy_intake.privacy_request_id IS '전환한 개인정보 권리 요청이다';
COMMENT ON COLUMN legal_guest_privacy_intake.received_at IS '접수 시각';
COMMENT ON COLUMN legal_guest_privacy_intake.internal_due_at IS '운영자가 본인 확인에 착수하고 권리 요청으로 전환해야 하는 내부 목표 기한이다. 접수일로부터 3일이다. 권리 요청으로 전환할 때 법정 기한은 접수일 10일 뒤, 내부 기한은 7일 뒤로 정하며 두 값은 확정 값이며 법정 기한은 변호사 검토 전 초안이다';
COMMENT ON COLUMN legal_guest_privacy_intake.closed_at IS '종결 시각';
COMMENT ON COLUMN legal_guest_privacy_intake.closed_reason IS '종결 사유다';
COMMENT ON TABLE legal_kakao_unlink_event IS '카카오 연결 끊기와 관련한 두 방향의 사건이다. OUTBOUND_CALL은 회원 탈퇴 때 사이로가 카카오에 연결 끊기를 요청하는 작업이고 INBOUND_WEBHOOK은 이용자가 카카오 쪽에서 먼저 끊었을 때 카카오가 보내는 알림이다. 식별자 원문은 호출이 끝나기 전까지만 암호화해 보관한다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_kakao_unlink_event.id IS '사건 식별자';
COMMENT ON COLUMN legal_kakao_unlink_event.direction IS '호출 방향이다';
COMMENT ON COLUMN legal_kakao_unlink_event.user_id IS '대상 사용자다. 수신 사건에서 사용자를 찾지 못하면 비운다';
COMMENT ON COLUMN legal_kakao_unlink_event.kakao_key_hmac IS '카카오 회원 식별값의 HMAC-SHA256 변환값이다. 수신 사건의 사용자 대조와 중복 확인에 쓴다';
COMMENT ON COLUMN legal_kakao_unlink_event.hmac_key_version IS '변환에 쓴 비밀키의 버전이다';
COMMENT ON COLUMN legal_kakao_unlink_event.target_key_encrypted IS '호출에 쓸 카카오 회원 식별값의 암호문이다. 호출이 끝나거나 보관 상한이 지나면 비운다';
COMMENT ON COLUMN legal_kakao_unlink_event.referrer_type IS '카카오가 알려 준 끊김 사유 값을 그대로 담는다';
COMMENT ON COLUMN legal_kakao_unlink_event.status IS 'PENDING은 호출 대기, SUCCEEDED는 호출 성공, FAILED_RETRYING은 재시도 중, ABANDONED는 재시도 한도를 넘겨 포기, APPLIED는 수신 반영, NO_MATCH는 일치하는 사용자 없음, DUPLICATE_IGNORED는 중복 수신이다';
COMMENT ON COLUMN legal_kakao_unlink_event.attempt_count IS '호출 시도 횟수';
COMMENT ON COLUMN legal_kakao_unlink_event.next_attempt_at IS '다음 호출 시각이다. 대기와 재시도 상태에서만 값이 있다';
COMMENT ON COLUMN legal_kakao_unlink_event.last_error_code IS '마지막 호출 실패 코드다';
COMMENT ON COLUMN legal_kakao_unlink_event.occurred_at IS '사건을 만든 시각이다';
COMMENT ON COLUMN legal_kakao_unlink_event.completed_at IS '처리를 마친 시각이다';
COMMENT ON COLUMN legal_kakao_unlink_event.key_wiped_at IS '식별자 암호문을 지운 시각이다';
COMMENT ON TABLE legal_authority_request IS '수사기관·법원·감독기관의 자료 요청을 접수하고 제공 여부를 결정한 기록이다. 출시 후 확장 항목이며 접근은 개인정보담당 운영자로 제한한다. 제공 결정은 기록자와 다른 운영자가 승인한다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_authority_request.id IS '요청 식별자';
COMMENT ON COLUMN legal_authority_request.received_at IS '요청을 받은 시각';
COMMENT ON COLUMN legal_authority_request.agency_type IS '요청 기관 종류다';
COMMENT ON COLUMN legal_authority_request.agency_name IS '요청 기관 이름이다';
COMMENT ON COLUMN legal_authority_request.document_reference IS '요청 문서 번호다';
COMMENT ON COLUMN legal_authority_request.legal_basis_note IS '운영자가 확인한 법적 근거 메모다. 조항을 확인하지 못했으면 검토 대상 법령 이름만 적는다';
COMMENT ON COLUMN legal_authority_request.target_office_id IS '요청 대상 사무소다';
COMMENT ON COLUMN legal_authority_request.target_user_id IS '요청 대상 회원이다';
COMMENT ON COLUMN legal_authority_request.requested_items IS '요청받은 자료의 범위';
COMMENT ON COLUMN legal_authority_request.decision IS '제공 결정이다';
COMMENT ON COLUMN legal_authority_request.provided_items IS '실제로 제공한 자료의 범위다';
COMMENT ON COLUMN legal_authority_request.provided_at IS '제공한 시각';
COMMENT ON COLUMN legal_authority_request.office_notice_status IS '대상 사무소에 알리는 문제의 검토 결과다. 알릴 수 없는 사유는 변호사 확인 대상이다';
COMMENT ON COLUMN legal_authority_request.recorded_by_operator_id IS '접수를 기록한 운영자';
COMMENT ON COLUMN legal_authority_request.approved_by_operator_id IS '제공을 승인한 운영자다. 기록자와 달라야 한다';
COMMENT ON COLUMN legal_authority_request.closed_at IS '요청을 종결한 시각';
COMMENT ON COLUMN legal_authority_request.retention_until IS '기록을 지우는 날이다. 종결할 때 AUTHORITY_REQUEST 일수로 정한다';
COMMENT ON COLUMN legal_authority_request.created_at IS '기록 생성 시각';
COMMENT ON TABLE legal_provider_contract_copy IS '공급자 계약서와 처리 조건 사본의 보관 기록이다. 사본 파일은 비공개 파일 저장소에 두고 이 표는 위치와 해시만 가진다. 출시 후 확장 항목이다. 변호사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN legal_provider_contract_copy.id IS '사본 식별자';
COMMENT ON COLUMN legal_provider_contract_copy.integration_id IS '연동 설정 행이다';
COMMENT ON COLUMN legal_provider_contract_copy.document_kind IS '서비스 계약, 처리 조건, 재수탁자 고지, 기타 중 문서 종류다';
COMMENT ON COLUMN legal_provider_contract_copy.version_label IS '공급자가 부여한 버전 이름이나 체결 차수다';
COMMENT ON COLUMN legal_provider_contract_copy.signed_on IS '체결일';
COMMENT ON COLUMN legal_provider_contract_copy.valid_until IS '유효 종료일';
COMMENT ON COLUMN legal_provider_contract_copy.storage_key IS '비공개 저장소의 객체 키다. 공개 주소가 아니다';
COMMENT ON COLUMN legal_provider_contract_copy.content_sha256 IS '사본 파일의 SHA-256 해시다';
COMMENT ON COLUMN legal_provider_contract_copy.subprocessor_change_notified_at IS '재수탁자 변경을 사무소 대표에게 사전 고지한 시각이다';
COMMENT ON COLUMN legal_provider_contract_copy.uploaded_by_operator_id IS '사본을 올린 운영자';
COMMENT ON COLUMN legal_provider_contract_copy.uploaded_at IS '올린 시각';
COMMENT ON COLUMN legal_provider_contract_copy.retention_until IS '사본을 지우는 날이다. 계약이 끝난 날에 PROVIDER_CONTRACT_COPY 일수를 더해 정한다';
COMMENT ON TABLE tax_invoice_recipient IS '사무소 대표가 입력하는 세금계산서 수신 정보다. 수정하면 새 행을 만들고 이전 행은 대체됨 상태로 남긴다. 청구가 시작되기 전에는 발급하지 않는다. 변호사와 세무사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다';
COMMENT ON COLUMN tax_invoice_recipient.id IS '수신 정보 식별자';
COMMENT ON COLUMN tax_invoice_recipient.office_id IS '구독 사무소';
COMMENT ON COLUMN tax_invoice_recipient.status IS 'ACTIVE는 현재 값, SUPERSEDED는 새 값으로 대체된 이전 값이다. 사무소당 ACTIVE는 하나다';
COMMENT ON COLUMN tax_invoice_recipient.business_number IS '수신 사업자등록번호 숫자 10자리다';
COMMENT ON COLUMN tax_invoice_recipient.company_name IS '수신 상호';
COMMENT ON COLUMN tax_invoice_recipient.representative_name IS '수신 대표자 이름';
COMMENT ON COLUMN tax_invoice_recipient.receiver_email IS '발급 안내를 받을 이메일이다';
COMMENT ON COLUMN tax_invoice_recipient.tax_type IS '수신자의 과세유형이다. 모르면 UNKNOWN이며 발급 방법은 세무사 확인 뒤 정한다';
COMMENT ON COLUMN tax_invoice_recipient.issue_requested IS '세금계산서 발급을 요청하는지다';
COMMENT ON COLUMN tax_invoice_recipient.registered_by_membership_id IS '입력한 대표의 소속';
COMMENT ON COLUMN tax_invoice_recipient.registered_at IS '입력 시각';
COMMENT ON COLUMN tax_invoice_recipient.superseded_at IS '대체된 시각';
COMMENT ON TABLE tax_document IS '청구서에 대한 세금계산서·현금영수증·전자계산서의 발급 상태 기록이다. 출시 시점에는 운영자가 국세청 서비스에서 발급한 뒤 승인번호와 금액을 기록하는 수동 방식이다. 수정 발급은 원본을 고치지 않고 AMENDED 행을 새로 만든다. 변호사와 세무사 검토 전 초안이며 법적 효력과 적합성은 검토 뒤 확정한다. 수정 발급 행이 원본 행을 참조하므로 보관 기간이 지나면 수정 발급 행을 먼저 지운다';
COMMENT ON COLUMN tax_document.id IS '발급 기록 식별자';
COMMENT ON COLUMN tax_document.billing_invoice_id IS '대상 청구서';
COMMENT ON COLUMN tax_document.recipient_id IS '발급 당시의 수신 정보 행이다';
COMMENT ON COLUMN tax_document.document_kind IS 'TAX_INVOICE는 세금계산서, CASH_RECEIPT는 현금영수증, EXEMPT_INVOICE는 면세 계산서다. 현금영수증과 면세 계산서는 필요 여부를 세무사에게 확인하기 전까지 운영자 기록으로만 쓴다';
COMMENT ON COLUMN tax_document.is_electronic IS '전자 발급인지다';
COMMENT ON COLUMN tax_document.status IS '발급 상태다. NOT_REQUIRED는 발급 대상이 아님, PENDING은 발급 대기, ISSUED는 발급됨, ISSUE_FAILED는 발급 실패, AMENDED는 수정 발급, CANCELLED는 취소다';
COMMENT ON COLUMN tax_document.approval_number IS '발급 서비스가 부여한 승인번호다';
COMMENT ON COLUMN tax_document.issued_on IS '발급일 또는 작성일자다';
COMMENT ON COLUMN tax_document.supply_amount IS '공급가액이다. 수정 발급은 음수일 수 있다';
COMMENT ON COLUMN tax_document.vat_amount IS '세액이다. 수정 발급은 음수일 수 있다';
COMMENT ON COLUMN tax_document.original_document_id IS '수정 발급의 원본 기록이다';
COMMENT ON COLUMN tax_document.operator_note IS '발급 실패, 수정 발급, 취소의 사유 메모다. 이 세 상태에서는 값이 필수다';
COMMENT ON COLUMN tax_document.recorded_by_operator_id IS '기록한 결제담당 운영자';
COMMENT ON COLUMN tax_document.recorded_at IS '기록 시각';
COMMENT ON COLUMN tax_document.updated_at IS '마지막 변경 시각';
COMMENT ON COLUMN tax_document.retention_until IS '기록을 지우는 날이다. 발급일에 TAX_DOCUMENT 일수를 더해 정한다';
COMMENT ON COLUMN tax_document.version IS '낙관적 잠금 버전';
